export default "       assert len(result_dict) == 1\\n            assert result_dict[0][\\\"result\\\"] == \\\"test_output\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_error_handling_with_cache_disabled(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test error handling when cache is disabled and server fails.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.use_cache = False\\n\\n        with (\\n            patch(\\\"langflow.api.v2.mcp.get_server\\\") as mock_get_server,\\n            patch(\\\"lfx.services.deps.session_scope\\\"),\\n            patch(\\\"langflow.services.database.models.user.crud.get_user_by_id\\\") as mock_get_user,\\n        ):\\n            # Simulate server error\\n            mock_get_server.side_effect = Exception(\\\"Server connection failed\\\")\\n            mock_get_user.return_value = MagicMock()\\n\\n            # Should handle error gracefully\\n            with pytest.raises(ValueError, match=\\\"Error updating tool list\\\"):\\n                await component.update_tool_list(\\\"failing_server\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_mcp_component_dynamic.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"86b083d54e479103f177297f430c051d3f1a4ea71e2c3b20bd20765572cb5ee5\",\"content\":\"\\\"\\\"\\\"Unit tests for the dynamic tool-onboarding fixes in MCPToolsComponent.\\n\\nCovers:\\n- ``_normalized_headers_for_cache`` handles list / dict / None header shapes\\n- ``_mcp_servers_cache_key`` is deterministic, header-hash scoped, and distinguishes auth contexts\\n- ``_ttl_tool_cache`` is a per-instance dict (not a class-level shared dict) so distinct\\n  components cannot leak tool lists into each other\\n- ``_get_tools`` honours the TTL cache hit / expiry / FIFO-eviction logic\\n- ``update_tool_list`` is serialized by ``_update_tool_list_lock`` (no interleaving)\\n- The shared ``servers`` cross-request cache evicts oldest entries when it exceeds\\n  ``SHARED_SERVERS_CACHE_MAX_ENTRIES``\\n- The Toolset output is declared / persisted with ``cache=False`` so saved flows\\n  do not memoize a stale tool list\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nfrom copy import deepcopy\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.base.agents.utils import safe_cache_get, safe_cache_set\\nfrom lfx.base.tools.constants import TOOL_OUTPUT_NAME\\nfrom lfx.components.models_and_agents.mcp_component import MCPToolsComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\ndef test_tool_mode_capability_is_available_before_server_discovery() -> None:\\n    \\\"\\\"\\\"The toolbar must not wait for an MCP connection to discover Tool Mode.\\\"\\\"\\\"\\n    tool_placeholder = next(input_ for input_ in MCPToolsComponent.inputs if input_.name == \\\"tool_placeholder\\\")\\n\\n    assert tool_placeholder.tool_mode is True\\n\\n\\ndef _make_tool(name: str) -> MagicMock:\\n    tool = MagicMock()\\n    tool.name = name\\n    return tool\\n\\n\\nclass TestHeaderNormalization:\\n    \\\"\\\"\\\"``_normalized_headers_for_cache`` is the input to the cache-key hash.\\\"\\\"\\\"\\n\\n    def test_list_of_key_value_dicts(self) -> None:\\n        component = MCPToolsComponent()\\n        component.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer abc\\\"},\\n            {\\\"key\\\": \\\"X-Tenant\\\", \\\"value\\\": \\\"acme\\\"},\\n        ]\\n\\n        assert component._normalized_headers_for_cache() == {\\n            \\\"Authorization\\\": \\\"Bearer abc\\\",\\n            \\\"X-Tenant\\\": \\\"acme\\\",\\n        }\\n\\n    def test_dict_input(self) -> None:\\n        component = MCPToolsComponent()\\n        component.headers = {\\\"Authorization\\\": \\\"Bearer abc\\\"}\\n\\n        assert component._normalized_headers_for_cache() == {\\\"Authorization\\\": \\\"Bearer abc\\\"}\\n\\n    def test_none_returns_empty_dict(self) -> None:\\n        component = MCPToolsComponent()\\n        component.headers = None\\n\\n        assert component._normalized_headers_for_cache() == {}\\n\\n    def test_malformed_list_items_are_skipped(self) -> None:\\n        component = MCPToolsComponent()\\n        component.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer abc\\\"},\\n            \\\"not-a-dict\\\",\\n            {\\\"no_key\\\": \\\"bad\\\"},\\n        ]\\n\\n        assert component._normalized_headers_for_cache() == {\\\"Authorization\\\": \\\"Bearer abc\\\"}\\n\\n\\nclass TestCacheKey:\\n    \\\"\\\"\\\"``_mcp_servers_cache_key`` must separate auth contexts and stay deterministic.\\\"\\\"\\\"\\n\\n    def test_empty_server_name_returns_empty_string(self) -> None:\\n        component = MCPToolsComponent()\\n        assert component._mcp_servers_cache_key(\\\"\\\") == \\\"\\\"\\n\\n    def test_no_headers_returns_bare_server_name(self) -> None:\\n        component = MCPToolsComponent()\\n        component.headers = []\\n\\n        assert component._mcp_servers_cache_key(\\\"srv\\\") == \\\"srv\\\"\\n\\n    def test_different_headers_produce_different_keys(self) -> None:\\n        a = MCPToolsComponent()\\n        a.headers = [{\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer tenant-a\\\"}]\\n        b = MCPToolsComponent()\\n        b.headers = [{\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer tenant-b\\\"}]\\n\\n        assert a._mcp_servers_cache_key(\\\"srv\\\") != b._mcp_servers_cache_key(\\\"srv\\\")\\n\\n    def test_different_users_produce_different_keys(self) -> None:\\n        a = MCPToolsComponent()\\n        a._user_id = \\\"tenant-a\\\"\\n        b = MCPToolsComponent()\\n        b._user_id = \\\"tenant-b\\\"\\n\\n        assert a._mcp_servers_cache_key(\\\"srv\\\") != b._mcp_servers_cache_key(\\\"srv\\\")\\n\\n    def test_same_user_produces_identical_keys(self) -> None:\\n        a = MCPToolsComponent()\\n        a._user_id = \\\"tenant-a\\\"\\n        b = MCPToolsComponent()\\n        b._user_id = \\\"tenant-a\\\"\\n\\n        assert a._mcp_servers_cache_key(\\\"srv\\\") == b._mcp_servers_cache_key(\\\"srv\\\")\\n\\n    def test_same_headers_produce_identical_keys(self) -> None:\\n        a = MCPToolsComponent()\\n        a.headers = [{\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer same\\\"}]\\n        b = MCPToolsComponent()\\n        b.headers = [{\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer same\\\"}]\\n\\n        assert a._mcp_servers_cache_key(\\\"srv\\\") == b._mcp_servers_cache_key(\\\"srv\\\")\\n\\n    def test_header_order_does_not_change_key(self) -> None:\\n        a = MCPToolsComponent()\\n        a.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer x\\\"},\\n            {\\\"key\\\": \\\"X-Tenant\\\", \\\"value\\\": \\\"acme\\\"},\\n        ]\\n        b = MCPToolsComponent()\\n        b.headers = [\\n            {\\\"key\\\": \\\"X-Tenant\\\", \\\"value\\\": \\\"acme\\\"},\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer x\\\"},\\n        ]\\n\\n        assert a._mcp_servers_cache_key(\\\"srv\\\") == b._mcp_servers_cache_key(\\\"srv\\\")\\n\\n\\nclass TestTtlToolCacheIsolation(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"``_ttl_tool_cache`` must be a per-instance dict, not class-level.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        return MCPToolsComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_fresh_instances_have_independent_dicts(self, component_class, default_kwargs) -> None:\\n        a = component_class(**default_kwargs)\\n        b = component_class(**default_kwargs)\\n\\n        assert a._ttl_tool_cache is not b._ttl_tool_cache\\n\\n    def test_write_to_one_instance_does_not_leak_to_another(self, component_class, default_kwargs) -> None:\\n        a = component_class(**default_kwargs)\\n        b = component_class(**default_kwargs)\\n        a._ttl_tool_cache[\\\"k\\\"] = (0.0, [_make_tool(\\\"leak\\\")])\\n\\n        assert \\\"k\\\" not in b._ttl_tool_cache\\n\\n    def test_invocation_copy_shares_cache_with_source_component(self, component_class, default_kwargs) -> None:\\n        component = component_class(**default_kwargs)\\n\\n        invocation_copy = deepcopy(component)\\n\\n        assert invocation_copy._ttl_tool_cache is component._ttl_tool_cache\\n\\n    @pytest.mark.asyncio\\n    async def test_sequential_invocation_copies_reuse_cached_tools(self, component_class, default_kwargs) -> None:\\n        component = component_class(**default_kwargs, mcp_server={\\\"name\\\": \\\"srv\\\"}, headers=[])\\n        first_invocation = deepcopy(component)\\n        second_invocation = deepcopy(component)\\n        tools = [_make_tool(\\\"cached\\\")]\\n\\n        update_tool_list = AsyncMock(return_value=(tools, {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {}}))\\n        with patch.object(component_class, \\\"update_tool_list\\\", new=update_tool_list):\\n            first_result = await first_invocation._get_tools()\\n            second_result = await second_invocation._get_tools()\\n\\n        assert first_result is tools\\n        assert second_result is tools\\n        update_tool_list.assert_awaited_once()\\n\\n\\nclass TestGetToolsTtlCache:\\n    \\\"\\\"\\\"``_get_tools`` uses the per-instance TTL cache with FIFO eviction + expiry.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_ttl_cache_hit_skips_update_tool_list(self) -> None:\\n        component = MCPToolsComponent()\\n        component.mcp_server = {\\\"name\\\": \\\"srv\\\"}\\n        component.headers = []\\n\\n        cached_tools = [_make_tool(\\\"cached\\\")]\\n        ttl_key = component._mcp_servers_cache_key(\\\"srv\\\")\\n        import time as _time\\n\\n        component._ttl_tool_cache[ttl_key] = (_time.monotonic(), cached_tools)\\n\\n        with patch.object(component, \\\"update_tool_list\\\", new=AsyncMock()) as mocked_update:\\n            result = await component._get_tools()\\n\\n        assert result is cached_tools\\n        mocked_update.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_ttl_cache_expired_entry_is_refetched(self) -> None:\\n        component = MCPToolsComponent()\\n        component.mcp_server = {\\\"name\\\": \\\"srv\\\"}\\n        component.headers = []\\n\\n        stale_tools = [_make_tool(\\\"stale\\\")]\\n        fresh_tools = [_make_tool(\\\"fresh\\\")]\\n        ttl_key = component._mcp_servers_cache_key(\\\"srv\\\")\\n        # Timestamp older than TOOL_TTL_SECS so the entry is considered expired.\\n        component._ttl_tool_cache[ttl_key] = (0.0, stale_tools)\\n\\n        with patch.object(\\n            component,\\n            \\\"update_tool_list\\\",\\n            new=AsyncMock(return_value=(fresh_tools, {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {}})),\\n        ):\\n            result = await component._get_tools()\\n\\n        assert result is fresh_tools\\n        # Stale entry was evicted and replaced with the fresh one.\\n        assert component._ttl_tool_cache[ttl_key][1] is fresh_tools\\n\\n    @pytest.mark.asyncio\\n    async def test_ttl_cache_bounded_by_max_entries_fifo(self) -> None:\\n        component = MCPToolsComponent()\\n        # Shrink the cap for a fast, deterministic FIFO check.\\n        component.TOOL_TTL_MAX_ENTRIES = 3\\n\\n        async def fake_update_tool_list(mcp_server):\\n            srv = mcp_server.get(\\\"name\\\") if isinstance(mcp_server, dict) else mcp_server\\n            return [_make_tool(f\\\"{srv}-tool\\\")], {\\\"name\\\": srv, \\\"config\\\": {}}\\n\\n        with patch.object(component, \\\"update_tool_list\\\", new=AsyncMock(side_effect=fake_update_tool_list)):\\n            for i in range(5):\\n                component.mcp_server = {\\\"name\\\": f\\\"srv-{i}\\\"}\\n                component.headers = []\\n                await component._get_tools()\\n\\n        assert len(component._ttl_tool_cache) == 3\\n        # FIFO eviction: the first two inserted keys must be gone, the last three must remain.\\n        remaining_keys = set(component._ttl_tool_cache.keys())\\n        for i in (0, 1):\\n            assert component._mcp_servers_cache_key(f\\\"srv-{i}\\\") not in remaining_keys\\n        for i in (2, 3, 4):\\n            assert component._mcp_servers_cache_key(f\\\"srv-{i}\\\") in remaining_keys\\n\\n    @pytest.mark.asyncio\\n    async def test_ttl_cache_disabled_when_ttl_is_zero(self) -> None:\\n        component = MCPToolsComponent()\\n        component.TOOL_TTL_SECS = 0\\n        component.mcp_server = {\\\"name\\\": \\\"srv\\\"}\\n        component.headers = []\\n\\n        fresh_tools = [_make_tool(\\\"fresh\\\")]\\n        with patch.object(\\n            component,\\n            \\\"update_tool_list\\\",\\n            new=AsyncMock(return_value=(fresh_tools, {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {}})),\\n        ):\\n            await component._get_tools()\\n\\n        # With TTL disabled, nothing should ever be written to the cache.\\n        assert component._ttl_tool_cache == {}\\n\\n\\nclass TestUpdateToolListLock:\\n    \\\"\\\"\\\"Concurrent ``update_tool_list`` calls must be serialized per component.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_concurrent_calls_are_serialized(self) -> None:\\n        component = MCPToolsComponent()\\n        component.use_cache = False\\n\\n        in_flight = 0\\n        peak = 0\\n        entered = asyncio.Event()\\n\\n        async def stub_run(_mcp_server):\\n            nonlocal in_flight, peak\\n            in_flight += 1\\n            peak = max(peak, in_flight)\\n            entered.set()\\n            await asyncio.sleep(0.02)\\n            in_flight -= 1\\n            return [], {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {}}\\n\\n        async def guarded(mcp_server):\\n            async with component._update_tool_list_lock:\\n                return await stub_run(mcp_server)\\n\\n        # Ten concurrent invocations must not overlap because the lock serializes them.\\n        await asyncio.gather(*(guarded(\\\"srv\\\") for _ in range(10)))\\n        assert peak == 1\\n        assert entered.is_set()\\n\\n\\nclass TestSharedServersCacheEviction:\\n    \\\"\\\"\\\"Shared ``servers`` cache must be bounded by ``SHARED_SERVERS_CACHE_MAX_ENTRIES``.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_fifo_eviction_when_over_limit(self) -> None:\\n        component = MCPToolsComponent()\\n        component.SHARED_SERVERS_CACHE_MAX_ENTRIES = 3\\n\\n        # Seed the shared cache up to capacity with placeholder entries.\\n        servers_cache: dict = {}\\n        for i in range(3):\\n            servers_cache[f\\\"old-{i}\\\"] = {\\n                \\\"tools\\\": [],\\n                \\\"tool_names\\\": [],\\n                \\\"tool_cache\\\": {},\\n                \\\"config\\\": {\\\"i\\\": i},\\n            }\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", servers_cache)\\n\\n        # The component's update_tool_list block applies FIFO eviction before inserting a new\\n        # key whenever len >= max_entries and the new key is absent. Reproduce that block here\\n        # to exercise the exact policy the component uses.\\n        new_key = \\\"new-key\\\"\\n        cache_data = {\\n            \\\"tools\\\": [],\\n            \\\"tool_names\\\": [],\\n            \\\"tool_cache\\\": {},\\n            \\\"config\\\": {\\\"new\\\": True},\\n        }\\n        current = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        max_entries = component.SHARED_SERVERS_CACHE_MAX_ENTRIES\\n        while len(current) >= max_entries and new_key not in current:\\n            oldest = next(iter(current))\\n            current.pop(oldest, None)\\n        current[new_key] = cache_data\\n        safe_cache_set(component._shared_component_cache, \\\"servers\\\", current)\\n\\n        final = safe_cache_get(component._shared_component_cache, \\\"servers\\\", {})\\n        assert len(final) == 3\\n        assert new_key in final\\n        # The oldest entry (\\\"old-0\\\") must have been evicted first.\\n        assert \\\"old-0\\\" not in final\\n        assert \\\"old-1\\\" in final\\n        assert \\\"old-2\\\" in final\\n\\n\\nclass TestUpdateBuildConfigRefresh:\\n    \\\"\\\"\\\"MCP node refresh should force a fresh connection attempt and surface failures.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _build_config(**overrides):\\n        config = {\\n            \\\"mcp_server\\\": {\\\"value\\\": {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test\\\"]}}},\\n            \\\"tool\\\": {\\\"show\\\": True, \\\"options\\\": [\\\"stale\\\"], \\\"value\\\": \\\"\\\", \\\"placeholder\\\": \\\"Select a tool\\\"},\\n            \\\"tool_placeholder\\\": {\\\"tool_mode\\\": False},\\n            \\\"tools_metadata\\\": {\\\"show\\\": False},\\n            \\\"use_cache\\\": {\\\"value\\\": True},\\n            \\\"verify_ssl\\\": {\\\"value\\\": True},\\n            \\\"headers\\\": {\\\"value\\\": []},\\n        }\\n        config.update(overrides)\\n        return config\\n\\n    @pytest.mark.asyncio\\n    async def test_clearing_server_keeps_tool_mode_capability(self) -> None:\\n        component = MCPToolsComponent()\\n\\n        build_config = await component.update_build_config(self._build_config(), {}, \\\"mcp_server\\\")\\n\\n        assert build_config[\\\"tool_placeholder\\\"][\\\"tool_mode\\\"] is True\\n\\n    @pytest.mark.asyncio\\n    async def test_refresh_bypasses_existing_options(self) -> None:\\n        component = MCPToolsComponent()\\n        component.use_cache = True\\n        tool = _make_tool(\\\"fresh\\\")\\n\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"srv\\\")\\n        with patch.object(\\n            component,\\n            \\\"update_tool_list\\\",\\n            new=AsyncMock(return_value=([tool], {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test\\\"]}})),\\n        ) as mocked_update:\\n            build_config = await component.update_build_config(\\n                self._build_config(is_refresh=True),\\n                {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test\\\"]}},\\n                \\\"mcp_server\\\",\\n            )\\n\\n        mocked_update.assert_awaited_once()\\n        assert build_config[\\\"tool\\\"][\\\"options\\\"] == [\\\"fresh\\\"]\\n        assert build_config[\\\"tool\\\"][\\\"placeholder\\\"] == \\\"Select a tool\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_mcp_server_error_placeholder_includes_root_cause(self) -> None:\\n        component = MCPToolsComponent()\\n        component.use_cache = False\\n\\n        with patch.object(\\n            component,\\n            \\\"update_tool_list\\\",\\n            new=AsyncMock(side_effect=ValueError(\\\"Connection refused\\\")),\\n        ):\\n            # is_refresh forces a fresh connection attempt (per this class's contract) so the\\n            # error surfaces deterministically. Without it, the cold-cache fast path preserves\\n            # the saved (\\\"stale\\\") options and never calls update_tool_list, which made this test\\n            # depend on shared-cache state left by a sibling test (order-dependent under xdist).\\n            build_config = await component.update_build_config(\\n                self._build_config(is_refresh=True),\\n                {\\\"name\\\": \\\"srv\\\", \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test\\\"]}},\\n                \\\"mcp_server\\\",\\n            )\\n\\n        assert build_config[\\\"tool\\\"][\\\"options\\\"] == []\\n        assert \\\"Connection refused\\\" in build_config[\\\"tool\\\"][\\\"placeholder\\\"]\\n\\n\\nclass TestToolsetOutputNotCached:\\n    \\\"\\\"\\\"Saved flows must not memoize the Toolset output.\\\"\\\"\\\"\\n\\n    def test_build_tool_output_declares_cache_false(self) -> None:\\n        component = MCPToolsComponent()\\n        output = component._build_tool_output()\\n\\n        assert output.name == TOOL_OUTPUT_NAME\\n        assert output.cache is False\\n\\n    def test_map_outputs_forces_cache_false_on_persisted_output(self) -> None:\\n        component = MCPToolsComponent()\\n        # Seed the outputs map with an entry that *claims* cache=True, as saved flow JSON\\n        # occasionally does. ``map_outputs`` must override it back to False.\\n        persisted = MagicMock()\\n        persisted.cache = True\\n        component._outputs_map = {TOOL_OUTPUT_NAME: persisted}\\n\\n        # Short-circuit the super() call; this test isolates the override behaviour.\\n        with patch(\\n            \\\"lfx.custom.custom_component.component_with_cache.ComponentWithCache.map_outputs\\\",\\n            return_value=None,\\n        ):\\n            component.map_outputs()\\n\\n        assert component._outputs_map[TOOL_OUTPUT_NAME].cache is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_mcp_component_output.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"60a76c9d3c47ee7f2b6892358b3ae59cb3dd2706681d4a5d0cc30cf390393340\",\"content\":\"\\\"\\\"\\\"Tests for MCP component output processing.\\\"\\\"\\\"\\n\\nfrom unittest.mock import AsyncMock, MagicMock\\n\\nimport pytest\\nfrom lfx.components.models_and_agents.mcp_component import MCPToolsComponent\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\nclass TestMCPComponentOutputProcessing:\\n    \\\"\\\"\\\"Test MCP component output processing, particularly for DataFrame compatibility.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Create an MCP component for testing.\\\"\\\"\\\"\\n        return MCPToolsComponent()\\n\\n    def test_process_output_item_with_dict_json(self, component):\\n        \\\"\\\"\\\"Test that process_output_item handles dict JSON correctly.\\\"\\\"\\\"\\n        item_dict = {\\\"type\\\": \\\"text\\\", \\\"text\\\": '{\\\"key\\\": \\\"value\\\", \\\"number\\\": 42}'}\\n\\n        result = component.process_output_item(item_dict)\\n\\n        assert isinstance(result, dict)\\n        assert result == {\\\"key\\\": \\\"value\\\", \\\"number\\\": 42}\\n\\n    def test_process_output_item_with_string_json(self, component):\\n        \\\"\\\"\\\"Test that process_output_item wraps string JSON values in dict.\\\"\\\"\\\"\\n        item_dict = {\\\"type\\\": \\\"text\\\", \\\"text\\\": '\\\"hello world\\\"'}\\n\\n        result = component.process_output_item(item_dict)\\n\\n        assert isinstance(result, dict)\\n        assert result[\\\"text\\\"] == '\\\"hello world\\\"'\\n        assert result[\\\"parsed_value\\\"] == \\\"hello world\\\"\\n        assert result[\\\"type\\\"] == \\\"text\\\"\\n\\n    def test_process_output_item_with_number_json(self, component):\\n        \\\"\\\"\\\"Test that process_output_item wraps number JSON values in dict.\\\"\\\"\\\"\\n        item_dict = {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"42\\\"}\\n\\n        result = component.process_output_item(item_dict)\\n\\n        assert isinstance(result, dict)\\n        assert result[\\\"text\\\"] == \\\"42\\\"\\n        assert result[\\\"parsed_value\\\"] == 42\\n        assert result[\\\"type\\\"] == \\\"text\\\"\\n\\n    def test_process_output_item_with_array_json(self, component):\\n        \\\"\\\"\\\"Test that process_output_item wraps array JSON values in dict.\\\"\\\"\\\"\\n        item_dict = {\\\"type\\\": \\\"text\\\", \\\"text\\\": '[\\\"item1\\\", \\\"item2\\\", \\\"item3\\\"]'}\\n\\n        result = component.process_output_item(item_dict)\\n\\n        assert isinstance(result, dict)\\n        assert result[\\\"text\\\"] == '[\\\"item1\\\", \\\"item2\\\", \\\"item3\\\"]'\\n        assert result[\\\"parsed_value\\\"] == [\\\"item1\\\", \\\"item2\\\", \\\"item3\\\"]\\n        assert result[\\\"type\\\"] == \\\"text\\\"\\n\\n    def test_process_output_item_with_invalid_json(self, component):\\n        \\\"\\\"\\\"Test that process_output_item handles invalid JSON gracefully.\\\"\\\"\\\"\\n        item_dict = {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"not valid json {\\\"}\\n\\n        result = component.process_output_item(item_dict)\\n\\n        assert isinstance(result, dict)\\n        assert result == item_dict\\n\\n    def test_process_output_item_non_text_type(self, component):\\n        \\\"\\\"\\\"Test that process_output_item returns non-text items unchanged.\\\"\\\"\\\"\\n        item_dict = {\\\"type\\\": \\\"image\\\", \\\"url\\\": \\\"https://example.com/image.png\\\"}\\n\\n        result = component.process_output_item(item_dict)\\n\\n        assert result == item_dict\\n\\n    @pytest.mark.asyncio\\n    async def test_build_output_creates_valid_dataframe(self, component):\\n        \\\"\\\"\\\"Test that build_output creates a valid DataFrame with mixed JSON types.\\\"\\\"\\\"\\n        # Setup component with mocked tools and cache\\n        component.tool = \\\"test_tool\\\"\\n        component.tools = []\\n\\n        # Mock the tool cache\\n        mock_tool = MagicMock()\\n        mock_result = MagicMock()\\n\\n        # Create mock output with various JSON types\\n        mock_content_item1 = MagicMock()\\n        mock_content_item1.model_dump.return_value = {\\\"type\\\": \\\"text\\\", \\\"text\\\": '{\\\"status\\\": \\\"success\\\"}'}\\n\\n        mock_content_item2 = MagicMock()\\n        mock_content_item2.model_dump.return_value = {\\\"type\\\": \\\"text\\\", \\\"text\\\": '\\\"just a string\\\"'}\\n\\n        mock_content_item3 = MagicMock()\\n        mock_content_item3.model_dump.return_value = {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"42\\\"}\\n\\n        mock_result.isError = False\\n        mock_result.content = [mock_content_item1, mock_content_item2, mock_content_item3]\\n        mock_tool.coroutine = AsyncMock(return_value=mock_result)\\n\\n        component._tool_cache = {\\\"test_tool\\\": mock_tool}\\n\\n        # Mock update_tool_list\\n        component.update_tool_list = AsyncMock(return_value=([], None))\\n\\n        # Mock get_inputs_for_all_tools to return empty list\\n        component.get_inputs_for_all_tools = MagicMock(return_value={\\\"test_tool\\\": []})\\n\\n        # Execute build_output\\n        result = await component.build_output()\\n\\n        # Verify result is a DataFrame\\n        assert isinstance(result, DataFrame)\\n\\n        # Verify all items in DataFrame are dictionaries\\n        for _idx, row in result.iterrows():\\n            # Each row should be a valid Series (which can be converted to dict)\\n            assert row is not None\\n\\n        # Verify the DataFrame has the expected number of rows\\n        assert len(result) == 3\\n\\n        # Verify first row is the original dict\\n        assert result.iloc[0][\\\"status\\\"] == \\\"success\\\"\\n\\n        # Verify second row is wrapped string\\n        assert result.iloc[1][\\\"parsed_value\\\"] == \\\"just a string\\\"\\n        assert result.iloc[1][\\\"type\\\"] == \\\"text\\\"\\n\\n        # Verify third row is wrapped number\\n        assert result.iloc[2][\\\"parsed_value\\\"] == 42\\n        assert result.iloc[2][\\\"type\\\"] == \\\"text\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_build_output_raises_on_iserror_tool_result(self, component):\\n        \\\"\\\"\\\"A tool result with isError=True is a FAILED call and must raise, not become data.\\n\\n        The HITL guard (and any MCP server error) reports failure via CallToolResult.isError\\n        with the explanation in content; swallowing it returns the error text as a valid\\n        DataFrame and the run looks successful.\\n        \\\"\\\"\\\"\\n        component.tool = \\\"test_tool\\\"\\n        component.tools = []\\n\\n        error_item = MagicMock()\\n        error_item.model_dump.return_value = {\\n            \\\"type\\\": \\\"text\\\",\\n            \\\"text\\\": \\\"This flow uses Human-in-the-Loop and cannot run as an MCP tool.\\\",\\n        }\\n        mock_result = MagicMock()\\n        mock_result.isError = True\\n        mock_result.content = [error_item]\\n        mock_tool = MagicMock()\\n        mock_tool.coroutine = AsyncMock(return_value=mock_result)\\n\\n        component._tool_cache = {\\\"test_tool\\\": mock_tool}\\n        component.update_tool_list = AsyncMock(return_value=([], None))\\n        component.get_inputs_for_all_tools = MagicMock(return_value={\\\"test_tool\\\": []})\\n\\n        with pytest.raises(ValueError, match=\\\"Human-in-the-Loop\\\") as excinfo:\\n            await component.build_output()\\n\\n        assert \\\"test_tool\\\" in str(excinfo.value)\\n\\n    @pytest.mark.asyncio\\n    async def test_build_output_with_no_tool_selected(self, component):\\n        \\\"\\\"\\\"Test that build_output returns error DataFrame when no tool is selected.\\\"\\\"\\\"\\n        component.tool = \\\"\\\"\\n        component.update_tool_list = AsyncMock(return_value=([], None))\\n\\n        result = await component.build_output()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1\\n        assert result.iloc[0][\\\"error\\\"] == \\\"You must select a tool\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_build_output_adds_page_default_for_empty_kwargs(self, component):\\n        \\\"\\\"\\\"Test that build_output calls coroutine with empty kwargs when no params provided.\\n\\n        With exclude_none in MCP util, optional params (page, page_size) are omitted from\\n        the payload sent to the server, allowing the backend to use its defaults.\\n        \\\"\\\"\\\"\\n        from pydantic import Field, create_model\\n\\n        component.tool = \\\"list_tool\\\"\\n        component.tools = []\\n\\n        mock_tool = MagicMock()\\n        mock_tool.name = \\\"list_tool\\\"\\n        mock_result = MagicMock()\\n        mock_result.isError = False\\n        mock_result.content = [\\n            MagicMock(model_dump=MagicMock(return_value={\\\"type\\\": \\\"text\\\", \\\"text\\\": '{\\\"results\\\": []}'}))\\n        ]\\n        mock_tool.coroutine = AsyncMock(return_value=mock_result)\\n\\n        schema = create_model(\\n            \\\"ListSchema\\\",\\n            page=(int | None, Field(default=None, description=\\\"Page\\\")),\\n            page_size=(int | None, Field(default=None, description=\\\"Page size\\\")),\\n        )\\n        mock_tool.args_schema = schema\\n        mock_tool.args_schema.model_fields = schema.model_fields\\n\\n        component._tool_cache = {\\\"list_tool\\\": mock_tool}\\n        component.update_tool_list = AsyncMock(return_value=([], None))\\n        component.get_inputs_for_all_tools = MagicMock(return_value={\\\"list_tool\\\": []})\\n\\n        await component.build_output()\\n\\n        mock_tool.coroutine.assert_called_once()\\n        call_kwargs = mock_tool.coroutine.call_args[1]\\n        assert call_kwargs == {}  # Empty kwargs; exclude_none sends {} to MCP server\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_message_history_component_outputs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e34eae32a29c28b019e7bd26ce96f626b426b6923333b445b89525fa94d5270c\",\"content\":\"from lfx.components.models_and_agents.memory import MemoryComponent\\n\\n\\ndef test_message_history_update_outputs_sets_types_and_selected_for_retrieve_mode():\\n    component = MemoryComponent()\\n\\n    node = {\\\"outputs\\\": []}\\n    updated = component.update_outputs(node, field_name=\\\"mode\\\", field_value=\\\"Retrieve\\\")\\n\\n    outputs = updated[\\\"outputs\\\"]\\n    assert len(outputs) == 2\\n\\n    by_name = {o.name: o for o in outputs}\\n\\n    assert by_name[\\\"messages_text\\\"].types == [\\\"Message\\\"]\\n    assert by_name[\\\"messages_text\\\"].selected == \\\"Message\\\"\\n\\n    assert by_name[\\\"dataframe\\\"].types == [\\\"Table\\\"]\\n    assert by_name[\\\"dataframe\\\"].selected == \\\"Table\\\"\\n\\n\\ndef test_message_history_update_outputs_sets_types_and_hidden_for_store_mode():\\n    component = MemoryComponent()\\n\\n    node = {\\\"outputs\\\": []}\\n    updated = component.update_outputs(node, field_name=\\\"mode\\\", field_value=\\\"Store\\\")\\n\\n    outputs = updated[\\\"outputs\\\"]\\n    assert len(outputs) == 1\\n\\n    output = outputs[0]\\n    assert output.name == \\\"stored_messages\\\"\\n    assert output.types == [\\\"Message\\\"]\\n    assert output.selected == \\\"Message\\\"\\n    assert output.hidden is True\\n\\n\\ndef test_message_history_update_outputs_ignores_non_mode_field_name():\\n    component = MemoryComponent()\\n\\n    sentinel = object()\\n    node = {\\\"outputs\\\": [sentinel]}\\n\\n    updated = component.update_outputs(node, field_name=\\\"not_mode\\\", field_value=\\\"Retrieve\\\")\\n\\n    assert updated is node\\n    assert updated[\\\"outputs\\\"] == [sentinel]\\n\\n\\ndef test_message_history_update_outputs_clears_outputs_for_unexpected_mode_value():\\n    component = MemoryComponent()\\n\\n    sentinel = object()\\n    node = {\\\"outputs\\\": [sentinel]}\\n\\n    updated = component.update_outputs(node, field_name=\\\"mode\\\", field_value=\\\"Delete\\\")\\n\\n    assert updated is node\\n    assert updated[\\\"outputs\\\"] == []\\n\\n\\ndef test_message_history_update_outputs_overwrites_preexisting_outputs_for_retrieve_mode():\\n    component = MemoryComponent()\\n\\n    sentinel = object()\\n    node = {\\\"outputs\\\": [sentinel]}\\n\\n    updated = component.update_outputs(node, field_name=\\\"mode\\\", field_value=\\\"Retrieve\\\")\\n\\n    outputs = updated[\\\"outputs\\\"]\\n    assert len(outputs) == 2\\n    assert sentinel not in outputs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_multimodal_agent.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9c9cd95c65e7810f48cda2c480b998eba68dbae859330d1721c9eb2b5a7651bb\",\"content\":\"\\\"\\\"\\\"Test multimodal input handling in agents.\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom lfx.base.agents.agent import LCAgentComponent\\nfrom lfx.schema.message import Message\\n\\n\\nclass MockAgentComponent(LCAgentComponent):\\n    \\\"\\\"\\\"Mock agent component for testing.\\\"\\\"\\\"\\n\\n    def __init__(self):\\n        self.input_value = None\\n        self.chat_history = []\\n        self.tools = []\\n        self.display_name = \\\"TestAgent\\\"\\n        self._event_manager = None\\n        self.log = MagicMock()\\n\\n    def get_langchain_callbacks(self):\\n        return []\\n\\n    async def send_message(self, message):\\n        return message\\n\\n    async def _send_message_event(self, message, category=None):\\n        pass\\n\\n\\n@pytest.mark.asyncio\\nasync def test_multimodal_input_text_extraction():\\n    \\\"\\\"\\\"Test that text is correctly extracted from multimodal content.\\\"\\\"\\\"\\n    component = MockAgentComponent()\\n\\n    # Create a message with multiple text items\\n    message = Message(text=\\\"Test\\\")\\n    mock_lc_message = MagicMock()\\n    mock_lc_message.content = [\\n        {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"First part\\\"},\\n        {\\\"type\\\": \\\"image\\\", \\\"image_url\\\": \\\"https://example.com/image.jpg\\\"},\\n        {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Second part\\\"},\\n    ]\\n\\n    component.input_value = message\\n\\n    # We need to test the logic directly since it's in run_agent\\n    # Let's extract the relevant logic\\n    image_dicts = [item for item in mock_lc_message.content if item.get(\\\"type\\\") == \\\"image\\\"]\\n    text_content = [item for item in mock_lc_message.content if item.get(\\\"type\\\") != \\\"image\\\"]\\n\\n    text_strings = [\\n        item.get(\\\"text\\\", \\\"\\\") for item in text_content if item.get(\\\"type\\\") == \\\"text\\\" and item.get(\\\"text\\\", \\\"\\\").strip()\\n    ]\\n\\n    result_text = \\\" \\\".join(text_strings) if text_strings else \\\"\\\"\\n\\n    # Verify\\n    assert result_text == \\\"First part Second part\\\"\\n    assert len(image_dicts) == 1\\n    assert image_dicts[0][\\\"image_url\\\"] == \\\"https://example.com/image.jpg\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_multimodal_input_only_images():\\n    \\\"\\\"\\\"Test that when only images are present, input becomes empty string.\\\"\\\"\\\"\\n    mock_lc_message = MagicMock()\\n    mock_lc_message.content = [\\n        {\\\"type\\\": \\\"image\\\", \\\"image_url\\\": \\\"https://example.com/image1.jpg\\\"},\\n        {\\\"type\\\": \\\"image\\\", \\\"image_url\\\": \\\"https://example.com/image2.jpg\\\"},\\n    ]\\n\\n    # Extract logic\\n    text_content = [item for item in mock_lc_message.content if item.get(\\\"type\\\") != \\\"image\\\"]\\n    text_strings = [\\n        item.get(\\\"text\\\", \\\"\\\") for item in text_content if item.get(\\\"type\\\") == \\\"text\\\" and item.get(\\\"text\\\", \\\"\\\").strip()\\n    ]\\n\\n    result_text = \\\" \\\".join(text_strings) if text_strings else \\\"\\\"\\n\\n    # Verify\\n    assert result_text == \\\"\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_simple_text_input():\\n    \\\"\\\"\\\"Test that simple text input (non-multimodal) works correctly.\\\"\\\"\\\"\\n    mock_lc_message = MagicMock()\\n    mock_lc_message.content = \\\"Simple text message\\\"\\n\\n    # This should not trigger multimodal logic since content is not a list\\n    assert not isinstance(mock_lc_message.content, list)\\n\\n    # The input should be set to the content directly\\n    result = mock_lc_message.content\\n    assert result == \\\"Simple text message\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_multimodal_input_empty_text():\\n    \\\"\\\"\\\"Test that empty text items are filtered out.\\\"\\\"\\\"\\n    mock_lc_message = MagicMock()\\n    mock_lc_message.content = [\\n        {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"\\\"},\\n        {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"   \\\"},\\n        {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Valid text\\\"},\\n        {\\\"type\\\": \\\"image\\\", \\\"image_url\\\": \\\"https://example.com/image.jpg\\\"},\\n    ]\\n\\n    # Extract logic\\n    text_content = [item for item in mock_lc_message.content if item.get(\\\"type\\\") != \\\"image\\\"]\\n    text_strings = [\\n        item.get(\\\"text\\\", \\\"\\\") for item in text_content if item.get(\\\"type\\\") == \\\"text\\\" and item.get(\\\"text\\\", \\\"\\\").strip()\\n    ]\\n\\n    result_text = \\\" \\\".join(text_strings) if text_strings else \\\"\\\"\\n\\n    # Verify - only non-empty text should be included\\n    assert result_text == \\\"Valid text\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_prompt_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9f5f025b9e622d31cf26199f6ae68e7a52a446d702ff8e166573d7e1ae9f2503\",\"content\":\"import pytest\\nfrom lfx.components.models_and_agents import PromptComponent\\n\\nfrom tests.base import ComponentTestBaseWithClient\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nclass TestPromptComponent(ComponentTestBaseWithClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return PromptComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\\"template\\\": \\\"Hello {name}!\\\", \\\"name\\\": \\\"John\\\", \\\"_session_id\\\": \\\"123\\\"}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"prompts\\\", \\\"file_name\\\": \\\"Prompt\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"prompts\\\", \\\"file_name\\\": \\\"prompt\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"prompts\\\", \\\"file_name\\\": \\\"prompt\\\"},\\n        ]\\n\\n    def test_post_code_processing(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        frontend_node = component.to_frontend_node()\\n        node_data = frontend_node[\\\"data\\\"][\\\"node\\\"]\\n        assert node_data[\\\"template\\\"][\\\"template\\\"][\\\"value\\\"] == \\\"Hello {name}!\\\"\\n        assert \\\"name\\\" in node_data[\\\"custom_fields\\\"][\\\"template\\\"]\\n        assert \\\"name\\\" in node_data[\\\"template\\\"]\\n        assert node_data[\\\"template\\\"][\\\"name\\\"][\\\"value\\\"] == \\\"John\\\"\\n\\n    def test_prompt_component_latest(self, component_class, default_kwargs):\\n        result = component_class(**default_kwargs)()\\n        assert result is not None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_tool_calling_agent.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"55107c93aa7fb5651e2533d3e5ea26a4636d38224834a4c08b1a5e0310f702a8\",\"content\":\"from unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx.components.langchain_utilities import ToolCallingAgentComponent\\nfrom lfx.components.tools.calculator import CalculatorToolComponent\\n\\n\\nclass TestToolCallingAgentUpdateBuildConfig:\\n    \\\"\\\"\\\"Unit tests for ToolCallingAgentComponent.update_build_config field visibility.\\\"\\\"\\\"\\n\\n    def _make_component(self):\\n        component = ToolCallingAgentComponent()\\n        component._user_id = None\\n        component.cache = {}\\n        return component\\n\\n    def _get_build_config(self, component):\\n        return component.to_frontend_node()[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n    @patch(\\\"lfx.components.langchain_utilities.tool_calling.get_language_model_options\\\")\\n    def test_shows_watsonx_fields_when_watsonx_selected(self, mock_opts):\\n        \\\"\\\"\\\"Selecting IBM WatsonX should show base_url_ibm_watsonx and project_id.\\\"\\\"\\\"\\n        watsonx_model = [{\\\"name\\\": \\\"ibm/granite-13b-chat-v2\\\", \\\"provider\\\": \\\"IBM WatsonX\\\", \\\"metadata\\\": {}}]\\n        mock_opts.return_value = watsonx_model\\n        component = self._make_component()\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, watsonx_model, field_name=\\\"model\\\")\\n\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is True\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"required\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is True\\n        assert \\\"ollama_base_url\\\" not in updated\\n\\n    @patch(\\\"lfx.components.langchain_utilities.tool_calling.get_language_model_options\\\")\\n    def test_hides_watsonx_fields_when_openai_selected(self, mock_opts):\\n        \\\"\\\"\\\"Selecting OpenAI should hide all provider-specific fields.\\\"\\\"\\\"\\n        openai_model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n        mock_opts.return_value = openai_model\\n        component = self._make_component()\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, openai_model, field_name=\\\"model\\\")\\n\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is False\\n        assert \\\"ollama_base_url\\\" not in updated\\n\\n    @patch(\\\"lfx.components.langchain_utilities.tool_calling.get_language_model_options\\\")\\n    def test_hides_all_provider_fields_with_no_model_selected(self, mock_opts):\\n        \\\"\\\"\\\"With no model selected, all provider-specific fields should be hidden.\\\"\\\"\\\"\\n        mock_opts.return_value = []\\n        component = self._make_component()\\n        build_config = self._get_build_config(component)\\n\\n        updated = component.update_build_config(build_config, \\\"\\\", field_name=None)\\n\\n        assert updated[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is False\\n        assert updated[\\\"project_id\\\"][\\\"show\\\"] is False\\n        assert \\\"ollama_base_url\\\" not in updated\\n\\n\\nclass TestToolCallingAgentBackwardCompatStreaming:\\n    \\\"\\\"\\\"Force streaming=True on the LLM resolved by ToolCallingAgentComponent._get_llm.\\n\\n    Bug repro for ``openrag_agent.json`` (code_hash ``154c71cf7441``): the saved\\n    flow embeds the pre-PR-13358 ``AgentComponent`` class body whose ``_get_llm()``\\n    calls ``get_llm(...)`` WITHOUT ``stream=True``. When the flow loads, Python\\n    exec's the old class \u2014 it still inherits from the LIVE\\n    ``ToolCallingAgentComponent`` (parents are resolved at exec time), but its\\n    own ``_get_llm`` produces a chat model with ``streaming=False``. PR #13358's\\n    fix in ``agent.py`` cannot reach serialized class bodies. Without forcing\\n    streaming at the live parent chokepoint, ``runnable.astream_events(v2)``\\n    never emits ``on_chat_model_stream`` and the Playground silently shows the\\n    response in a single batch.\\n    \\\"\\\"\\\"\\n\\n    def _build_component(self):\\n        component = ToolCallingAgentComponent()\\n        component._user_id = None\\n        component.cache = {}\\n        component.tools = []\\n        component.system_prompt = \\\"Test prompt\\\"\\n        return component\\n\\n    def test_should_force_streaming_true_when_legacy_serialized_agent_returns_non_streaming_llm(self):\\n        component = self._build_component()\\n\\n        # Simulate the legacy serialized ``_get_llm()`` that built the LLM via\\n        # ``get_llm()`` without the ``stream=True`` kwarg \u2014 resulting chat model\\n        # has ``streaming=False``.\\n        legacy_llm = Mock()\\n        legacy_llm.__class__.__name__ = \\\"ChatOpenAI\\\"\\n        legacy_llm.__class__.__module__ = \\\"langchain_openai\\\"\\n        legacy_llm.model_id = \\\"gpt-4o\\\"\\n        legacy_llm.model_name = \\\"gpt-4o\\\"\\n        legacy_llm.streaming = False\\n        legacy_llm.bind_tools = Mock(return_value=legacy_llm)\\n\\n        captured: dict[str, object] = {}\\n\\n        def _capture(llm, _tools, _prompt):\\n            captured[\\\"llm\\\"] = llm\\n            return Mock()\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=legacy_llm),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\",\\n                side_effect=_capture,\\n            ),\\n        ):\\n            component.create_agent_runnable()\\n\\n        assert captured[\\\"llm\\\"] is legacy_llm, \\\"create_tool_calling_agent must receive the resolved LLM\\\"\\n        assert legacy_llm.streaming is True, (\\n            \\\"ToolCallingAgentComponent.create_agent_runnable() must force streaming=True \\\"\\n            \\\"on the resolved LLM so serialized flows whose embedded AgentComponent code \\\"\\n            \\\"predates PR #13358 (e.g. openrag_agent.json with code_hash 154c71cf7441) \\\"\\n            \\\"still emit on_chat_model_stream chunks through astream_events(v2). \\\"\\n            \\\"PR #13358's _get_llm fix in agent.py cannot reach serialized class bodies.\\\"\\n        )\\n\\n    def test_should_preserve_streaming_true_when_modern_agent_returns_streaming_llm(self):\\n        \\\"\\\"\\\"No-op for already-streaming LLMs: don't downgrade or trigger setattr surprises.\\\"\\\"\\\"\\n        component = self._build_component()\\n\\n        modern_llm = Mock()\\n        modern_llm.__class__.__name__ = \\\"ChatOpenAI\\\"\\n        modern_llm.__class__.__module__ = \\\"langchain_openai\\\"\\n        modern_llm.model_id = \\\"gpt-4o\\\"\\n        modern_llm.model_name = \\\"gpt-4o\\\"\\n        modern_llm.streaming = True\\n        modern_llm.bind_tools = Mock(return_value=modern_llm)\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=modern_llm),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\",\\n                return_value=Mock(),\\n            ),\\n        ):\\n            component.create_agent_runnable()\\n\\n        assert modern_llm.streaming is True\\n\\n    def test_should_not_crash_when_llm_has_no_streaming_attribute(self):\\n        \\\"\\\"\\\"Future providers may lack the legacy ``streaming`` attribute.\\n\\n        Guards against a provider that implements streaming through a different\\n        knob (e.g. ``model_kwargs={\\\"stream\\\": True}``). The shim must use\\n        ``getattr(llm, \\\"streaming\\\", True)`` so a missing attr defaults to True\\n        (no mutation) and ``create_agent_runnable`` proceeds normally.\\n        \\\"\\\"\\\"\\n        component = self._build_component()\\n\\n        # Stand-in for a chat model that doesn't expose ``streaming``.\\n        def _no_streaming_bind_tools(self, _tools):\\n            return self\\n\\n        chat_exotic_cls = type(\\n            \\\"ChatExoticProvider\\\",\\n            (),\\n            {\\n                \\\"__module__\\\": \\\"langchain_exotic\\\",\\n                \\\"model_id\\\": \\\"exotic-1\\\",\\n                \\\"model_name\\\": \\\"exotic-1\\\",\\n                \\\"bind_tools\\\": _no_streaming_bind_tools,\\n            },\\n        )\\n        llm_obj = chat_exotic_cls()\\n        assert not hasattr(llm_obj, \\\"streaming\\\"), \\\"fixture invariant: no streaming attr\\\"\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=llm_obj),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\",\\n                return_value=Mock(),\\n            ),\\n        ):\\n            component.create_agent_runnable()  # must NOT raise AttributeError\\n\\n        assert not hasattr(llm_obj, \\\"streaming\\\"), (\\n            \\\"Shim must NOT setattr when the LLM has no ``streaming`` attribute: \\\"\\n            \\\"getattr default of True short-circuits the ``is False`` branch.\\\"\\n        )\\n\\n    def test_should_not_crash_when_llm_streaming_attribute_is_read_only(self):\\n        \\\"\\\"\\\"``contextlib.suppress`` must swallow setattr failures.\\n\\n        A future Pydantic-v2-strict chat model may freeze ``streaming``. The\\n        shim's job is to TRY forcing streaming; if the provider refuses, the\\n        agent must still run \u2014 better to surface a streaming bug downstream\\n        than to crash the whole flow at agent-build time.\\n        \\\"\\\"\\\"\\n        component = self._build_component()\\n\\n        def _readonly_bind_tools(self, _tools):\\n            return self\\n\\n        def _readonly_streaming_getter(_obj):\\n            return False\\n\\n        chat_strict_cls = type(\\n            \\\"ChatStrict\\\",\\n            (),\\n            {\\n                \\\"__module__\\\": \\\"langchain_strict\\\",\\n                \\\"model_id\\\": \\\"strict-1\\\",\\n                \\\"model_name\\\": \\\"strict-1\\\",\\n                # property with no setter \u2014 setattr raises AttributeError, exercised by contextlib.suppress\\n                \\\"streaming\\\": property(_readonly_streaming_getter),\\n                \\\"bind_tools\\\": _readonly_bind_tools,\\n            },\\n        )\\n        llm_obj = chat_strict_cls()\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=llm_obj),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\",\\n                return_value=Mock(),\\n            ),\\n        ):\\n            component.create_agent_runnable()  # must NOT raise AttributeError\\n\\n        # streaming still False because the property has no setter, but\\n        # the agent build did not crash \u2014 which is the contract.\\n        assert llm_obj.streaming is False\\n\\n    def test_should_be_idempotent_when_create_agent_runnable_called_twice(self):\\n        \\\"\\\"\\\"Repeated calls must not interact in surprising ways.\\n\\n        Some workflows resolve the LLM lazily and rebuild the runnable on\\n        retries; the shim must be a stable transformation (``streaming=True``\\n        is a fixed point) so the second invocation is a no-op.\\n        \\\"\\\"\\\"\\n        component = self._build_component()\\n\\n        llm = Mock()\\n        llm.__class__.__name__ = \\\"ChatOpenAI\\\"\\n        llm.__class__.__module__ = \\\"langchain_openai\\\"\\n        llm.model_id = \\\"gpt-4o\\\"\\n        llm.model_name = \\\"gpt-4o\\\"\\n        llm.streaming = False\\n        llm.bind_tools = Mock(return_value=llm)\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=llm),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.create_tool_calling_agent\\\",\\n                return_value=Mock(),\\n            ),\\n        ):\\n            component.create_agent_runnable()\\n            assert llm.streaming is True, \\\"first call must enable streaming\\\"\\n            component.create_agent_runnable()\\n            assert llm.streaming is True, \\\"second call must leave streaming=True intact\\\"\\n\\n    def test_should_force_streaming_true_on_granite_path(self):\\n        \\\"\\\"\\\"The Granite branch also passes through the live shim chokepoint.\\n\\n        ``create_granite_agent`` is selected when ``is_granite_model(llm)`` and\\n        the agent has tools; the shim runs BEFORE that branch (line ordering),\\n        so the resolved LLM must already have ``streaming=True`` even on the\\n        WatsonX path.\\n        \\\"\\\"\\\"\\n        component = self._build_component()\\n        component.tools = [Mock(name=\\\"t1\\\")]\\n        component.tools[0].name = \\\"tool_1\\\"\\n\\n        granite_llm = Mock()\\n        granite_llm.__class__.__name__ = \\\"ChatWatsonx\\\"\\n        granite_llm.__class__.__module__ = \\\"langchain_ibm\\\"\\n        granite_llm.model_id = \\\"ibm/granite-13b-chat-v2\\\"\\n        granite_llm.model_name = \\\"ibm/granite-13b-chat-v2\\\"\\n        granite_llm.streaming = False\\n        granite_llm.bind_tools = Mock(return_value=granite_llm)\\n\\n        captured: dict[str, object] = {}\\n\\n        def _capture_granite(llm, _tools, _prompt):\\n            captured[\\\"llm\\\"] = llm\\n            return Mock()\\n\\n        with (\\n            patch.object(component, \\\"_get_llm\\\", return_value=granite_llm),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.create_granite_agent\\\",\\n                side_effect=_capture_granite,\\n            ),\\n            patch(\\n                \\\"lfx.components.langchain_utilities.tool_calling.is_granite_model\\\",\\n                return_value=True,\\n            ),\\n        ):\\n            component.create_agent_runnable()\\n\\n        assert captured[\\\"llm\\\"] is granite_llm\\n        assert granite_llm.streaming is True, (\\n            \\\"Granite/WatsonX flows must also receive streaming=True so token-by-token \\\"\\n            \\\"delivery works on IBM Granite serialized flows.\\\"\\n        )\\n\\n\\n@pytest.mark.api_key_required\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_tool_calling_agent_component():\\n    tools = [CalculatorToolComponent().build_tool()]  # Use the Calculator component as a tool\\n    input_value = \\\"What is 2 + 2?\\\"\\n    chat_history = []\\n\\n    from tests.api_keys import get_openai_api_key\\n\\n    api_key = get_openai_api_key()\\n    temperature = 0.1\\n\\n    # Default OpenAI Model Component\\n    openai_model_component = pytest.importorskip(\\\"lfx_openai.components.openai.openai_chat_model\\\").OpenAIModelComponent\\n    llm_component = openai_model_component().set(\\n        api_key=api_key,\\n        temperature=temperature,\\n    )\\n    llm = llm_component.build_model()\\n\\n    agent = ToolCallingAgentComponent(_session_id=\\\"test\\\")\\n    agent.set(model=llm, tools=[tools], chat_history=chat_history, input_value=input_value)\\n\\n    # Chat output\\n    response = await agent.message_response()\\n    assert \\\"4\\\" in response.data.get(\\\"text\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/outputs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/outputs/test_chat_output_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"934f2ecc183c6666e4299665ab4649868be780b372ea44d0db588876034a1647\",\"content\":\"import pytest\\nfrom lfx.components.input_output import ChatOutput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\nfrom lfx.utils.constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_NAME_AI\\n\\nfrom tests.base import ComponentTestBaseWithClient\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nclass TestChatOutput(ComponentTestBaseWithClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return ChatOutput\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"input_value\\\": \\\"Hello, how are you?\\\",\\n            \\\"should_store_message\\\": True,\\n            \\\"sender\\\": MESSAGE_SENDER_AI,\\n            \\\"sender_name\\\": MESSAGE_SENDER_NAME_AI,\\n            \\\"session_id\\\": \\\"test_session_123\\\",\\n            \\\"data_template\\\": \\\"{text}\\\",\\n            \\\"background_color\\\": \\\"#f0f0f0\\\",\\n            \\\"chat_icon\\\": \\\"\ud83e\udd16\\\",\\n            \\\"text_color\\\": \\\"#000000\\\",\\n            \\\"clean_data\\\": True,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"outputs\\\", \\\"file_name\\\": \\\"ChatOutput\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"outputs\\\", \\\"file_name\\\": \\\"chat\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"outputs\\\", \\\"file_name\\\": \\\"chat\\\"},\\n        ]\\n\\n    async def test_process_string_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test processing a simple string input.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        input_text = \\\"Hello, this is a test message\\\"\\n        component.input_value = input_text\\n        result = await component.message_response()\\n        assert result.text == input_text\\n        assert result.sender == MESSAGE_SENDER_AI\\n        assert result.sender_name == MESSAGE_SENDER_NAME_AI\\n\\n    async def test_process_data_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test processing a Data object input.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        data = Data(text=\\\"Test data message\\\")\\n        component.input_value = data\\n        result = await component.message_response()\\n        assert result.text == '```json\\\\n{\\\\n  \\\"text\\\": \\\"Test data message\\\"\\\\n}\\\\n```'\\n        assert result.sender == MESSAGE_SENDER_AI\\n\\n    async def test_process_dataframe_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test processing a DataFrame input.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        sample_df = DataFrame(data={\\\"col1\\\": [\\\"A\\\", \\\"B\\\"], \\\"col2\\\": [1, 2]})\\n        component.input_value = sample_df\\n        result = await component.message_response()\\n        assert \\\"col1\\\" in result.text\\n        assert \\\"col2\\\" in result.text\\n        assert \\\"A\\\" in result.text\\n        assert \\\"B\\\" in result.text\\n\\n    async def test_process_message_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test processing a Message object input.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        message = Message(text=\\\"Test message content\\\")\\n        component.input_value = message\\n        result = await component.message_response()\\n        assert result.text == \\\"Test message content\\\"\\n        assert result.sender == MESSAGE_SENDER_AI\\n\\n    async def test_process_list_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test processing a list of inputs.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        input_list = [\\\"First message\\\", Data(text=\\\"Second message\\\"), Message(text=\\\"Third message\\\")]\\n        component.input_value = input_list\\n        result = await component.message_response()\\n        assert \\\"First message\\\" in result.text\\n        assert \\\"Second message\\\" in result.text\\n        assert \\\"Third message\\\" in result.text\\n\\n    async def test_invalid_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test handling of invalid input.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        component.input_value = None\\n        with pytest.raises(ValueError, match=\\\"Input data cannot be None\\\"):\\n            await component.message_response()\\n\\n        component.input_value = 123  # Invalid type\\n        with pytest.raises(TypeError, match=\\\"Expected Data or DataFrame or Message or str, Generator or None\\\"):\\n            await component.message_response()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/outputs/test_output_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"62e6b92fef37b29fb9678eb67c84337cc585d67ef5db26d6485f5f80aff43a90\",\"content\":\"import pytest\\nfrom lfx.components.input_output import TextOutputComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestTextOutputComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return TextOutputComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"input_value\\\": \\\"Hello, world!\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"outputs\\\", \\\"file_name\\\": \\\"TextOutput\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"outputs\\\", \\\"file_name\\\": \\\"text\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"outputs\\\", \\\"file_name\\\": \\\"text\\\"},\\n        ]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_data_operations_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"21be08f52100a37b250e42b26a73ea0c531f00be515845715614e9964dac75cb\",\"content\":\"import importlib\\nimport sys\\n\\nimport pytest\\nfrom lfx.components.processing.data_operations import DataOperationsComponent\\nfrom lfx.schema import Data\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\ndef test_should_import_module_when_jq_not_installed(monkeypatch):\\n    \\\"\\\"\\\"Module must be importable even when jq is not installed (e.g. on Windows).\\n\\n    The jq library is a C extension not available on Windows. The module-level\\n    import was removed so that update_build_config and non-jq operations work\\n    on all platforms. jq is only imported lazily inside json_query/json_path.\\n    \\\"\\\"\\\"\\n    # Remove jq from sys.modules and block re-import\\n    monkeypatch.delitem(sys.modules, \\\"jq\\\", raising=False)\\n    real_import = __import__\\n\\n    def mock_import(name, *args, **kwargs):\\n        if name == \\\"jq\\\":\\n            msg = \\\"No module named 'jq'\\\"\\n            raise ModuleNotFoundError(msg)\\n        return real_import(name, *args, **kwargs)\\n\\n    monkeypatch.setattr(\\\"builtins.__import__\\\", mock_import)\\n\\n    # Force reimport of the module\\n    monkeypatch.delitem(sys.modules, \\\"lfx.components.processing.data_operations\\\", raising=False)\\n\\n    # This must NOT raise ModuleNotFoundError\\n    mod = importlib.import_module(\\\"lfx.components.processing.data_operations\\\")\\n    component_cls = mod.DataOperationsComponent\\n\\n    # Non-jq operations must work\\n    component = component_cls(\\n        data=Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}),\\n        operations=[{\\\"name\\\": \\\"Select Keys\\\"}],\\n        select_keys_input=[\\\"key1\\\"],\\n    )\\n    result = component.as_data()\\n    assert \\\"key1\\\" in result.data\\n\\n\\nclass TestDataOperationsComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return DataOperationsComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"data\\\": Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\", \\\"key3\\\": \\\"value3\\\"}),\\n            \\\"actions\\\": [{\\\"name\\\": \\\"Select Keys\\\"}],\\n            \\\"select_keys_input\\\": [\\\"key1\\\", \\\"key2\\\"],\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_select_keys(self):\\n        \\\"\\\"\\\"Test the Select Keys operation.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\", \\\"key3\\\": \\\"value3\\\"}),\\n            operations=[{\\\"name\\\": \\\"Select Keys\\\"}],\\n            select_keys_input=[\\\"key1\\\", \\\"key2\\\"],\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert \\\"key1\\\" in result.data\\n        assert \\\"key2\\\" in result.data\\n        assert \\\"key3\\\" not in result.data\\n        assert result.data[\\\"key1\\\"] == \\\"value1\\\"\\n        assert result.data[\\\"key2\\\"] == \\\"value2\\\"\\n\\n    def test_remove_keys(self):\\n        \\\"\\\"\\\"Test the Remove Keys operation.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\", \\\"key3\\\": \\\"value3\\\"}),\\n            operations=[{\\\"name\\\": \\\"Remove Keys\\\"}],\\n            remove_keys_input=[\\\"key3\\\"],\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert \\\"key1\\\" in result.data\\n        assert \\\"key2\\\" in result.data\\n        assert \\\"key3\\\" not in result.data\\n\\n    def test_rename_keys(self):\\n        \\\"\\\"\\\"Test the Rename Keys operation.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}),\\n            operations=[{\\\"name\\\": \\\"Rename Keys\\\"}],\\n            rename_keys_input={\\\"key1\\\": \\\"new_key1\\\"},\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert \\\"new_key1\\\" in result.data\\n        assert \\\"key1\\\" not in result.data\\n        assert result.data[\\\"new_key1\\\"] == \\\"value1\\\"\\n\\n    def test_literal_eval(self):\\n        \\\"\\\"\\\"Test the Literal Eval operation.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"list_as_string\\\": \\\"[1, 2, 3]\\\", \\\"dict_as_string\\\": \\\"{'a': 1, 'b': 2}\\\"}),\\n            operations=[{\\\"name\\\": \\\"Literal Eval\\\"}],\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert isinstance(result.data[\\\"list_as_string\\\"], list)\\n        assert result.data[\\\"list_as_string\\\"] == [1, 2, 3]\\n        assert isinstance(result.data[\\\"dict_as_string\\\"], dict)\\n        assert result.data[\\\"dict_as_string\\\"] == {\\\"a\\\": 1, \\\"b\\\": 2}\\n\\n    def test_combine(self):\\n        \\\"\\\"\\\"Test the Combine operation.\\\"\\\"\\\"\\n        data1 = Data(data={\\\"key1\\\": \\\"value1\\\"})\\n        data2 = Data(data={\\\"key2\\\": \\\"value2\\\"})\\n\\n        component = DataOperationsComponent(\\n            data=[data1, data2],\\n            operations=[{\\\"name\\\": \\\"Combine\\\"}],\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert \\\"key1\\\" in result.data\\n        assert \\\"key2\\\" in result.data\\n        assert result.data[\\\"key1\\\"] == \\\"value1\\\"\\n        assert result.data[\\\"key2\\\"] == \\\"value2\\\"\\n\\n    def test_combine_with_overlapping_keys(self):\\n        \\\"\\\"\\\"Test the Combine operation with overlapping keys.\\\"\\\"\\\"\\n        data1 = Data(data={\\\"common_key\\\": \\\"value1\\\", \\\"key1\\\": \\\"value1\\\"})\\n        data2 = Data(data={\\\"common_key\\\": \\\"value2\\\", \\\"key2\\\": \\\"value2\\\"})\\n\\n        component = DataOperationsComponent(\\n            data=[data1, data2],\\n            operations=[{\\\"name\\\": \\\"Combine\\\"}],\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"common_key\\\"] == [\\\"value1\\\", \\\"value2\\\"]  # Combined string values\\n        assert result.data[\\\"key1\\\"] == \\\"value1\\\"\\n        assert result.data[\\\"key2\\\"] == \\\"value2\\\"\\n\\n    def test_append_update(self):\\n        \\\"\\\"\\\"Test the Append or Update Data operation.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"existing_key\\\": \\\"existing_value\\\"}),\\n            operations=[{\\\"name\\\": \\\"Append or Update\\\"}],\\n            append_update_data={\\\"new_key\\\": \\\"new_value\\\", \\\"existing_key\\\": \\\"updated_value\\\"},\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"existing_key\\\"] == \\\"updated_value\\\"\\n        assert result.data[\\\"new_key\\\"] == \\\"new_value\\\"\\n\\n    def test_no_actions(self):\\n        \\\"\\\"\\\"Test behavior when no actions are specified.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\"}),\\n            operations=[],\\n        )\\n\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert result.data == {}\\n\\n    def test_get_normalized_data(self):\\n        \\\"\\\"\\\"Test the get_normalized_data helper method.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\"}),\\n            operations=[],\\n        )\\n\\n        # Add data under the \\\"data\\\" key\\n        component.data = Data(data={\\\"test\\\": {\\\"key2\\\": \\\"value2\\\"}})\\n        normalized = component.get_normalized_data()\\n        assert normalized == {\\\"test\\\": {\\\"key2\\\": \\\"value2\\\"}}\\n\\n        # Test without the \\\"data\\\" key\\n        component.data = Data(data={\\\"key3\\\": \\\"value3\\\"})\\n        normalized = component.get_normalized_data()\\n        assert normalized == {\\\"key3\\\": \\\"value3\\\"}\\n\\n    def test_validate_single_data_with_multiple_data(self):\\n        \\\"\\\"\\\"Test that operations that don't support multiple data objects raise an error.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=[Data(data={\\\"key1\\\": \\\"value1\\\"}), Data(data={\\\"key2\\\": \\\"value2\\\"})],\\n            operations=[{\\\"name\\\": \\\"Select Keys\\\"}],\\n            select_keys_input=[\\\"key1\\\"],\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Select Keys operation is not supported for multiple data objects\\\"):\\n            component.as_data()\\n\\n    def test_removed_operation_raises_instead_of_returning_empty(self):\\n        \\\"\\\"\\\"A persisted flow referencing the removed 'Filter Values' op fails fast, not silently.\\\"\\\"\\\"\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"items\\\": [{\\\"name\\\": \\\"a\\\"}]}),\\n            operations=[{\\\"name\\\": \\\"Filter Values\\\"}],\\n        )\\n        with pytest.raises(ValueError, match=\\\"no longer supported\\\"):\\n            component.as_data()\\n\\n    def test_update_build_config_clears_input_fields_when_operation_removed(self):\\n        \\\"\\\"\\\"Test that removing the selected operation hides all operation-specific input fields.\\\"\\\"\\\"\\n        from lfx.schema.dotdict import dotdict\\n\\n        component = DataOperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\"}),\\n            operations=[],\\n        )\\n        # Simulate build_config after \\\"Rename Keys\\\" was selected (operation-specific fields visible)\\n        build_config = dotdict(\\n            {\\n                \\\"operations\\\": {\\\"value\\\": [], \\\"show\\\": True},\\n                \\\"data\\\": {\\\"value\\\": None, \\\"show\\\": True},\\n                \\\"rename_keys_input\\\": {\\\"value\\\": {\\\"old_key\\\": \\\"new_key\\\"}, \\\"show\\\": True},\\n                \\\"remove_keys_input\\\": {\\\"value\\\": [], \\\"show\\\": True},\\n                \\\"select_keys_input\\\": {\\\"value\\\": [], \\\"show\\\": False},\\n            }\\n        )\\n        result = component.update_build_config(build_config, [], \\\"operations\\\")\\n\\n        # All operation-specific fields should be hidden when no operation is selected\\n        assert result[\\\"rename_keys_input\\\"][\\\"show\\\"] is False\\n        assert result[\\\"remove_keys_input\\\"][\\\"show\\\"] is False\\n        assert result[\\\"select_keys_input\\\"][\\\"show\\\"] is False\\n        # Default fields (operations, data) should remain visible\\n        assert result[\\\"operations\\\"][\\\"show\\\"] is True\\n        assert result[\\\"data\\\"][\\\"show\\\"] is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_data_to_dataframe_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4ae319ec3f4dc6ca0ed0df68c1dfdda082070a500fca54738dd1b4f5b8295c65\",\"content\":\"import pytest\\nfrom lfx.components.processing.data_to_dataframe import DataToDataFrameComponent\\nfrom lfx.schema import Data, DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestDataToDataFrameComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return DataToDataFrameComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"data_list\\\": [\\n                Data(text=\\\"Row 1\\\", data={\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": 1}),\\n                Data(text=\\\"Row 2\\\", data={\\\"field1\\\": \\\"value2\\\", \\\"field2\\\": 2}),\\n            ]\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        # This is a new component, so we return an empty list\\n        return []\\n\\n    def test_basic_setup(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test basic component initialization.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        assert component.data_list == default_kwargs[\\\"data_list\\\"]\\n\\n    def test_build_dataframe_basic(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test basic DataFrame construction.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        result_df = component.build_dataframe()\\n\\n        assert isinstance(result_df, DataFrame)\\n        assert len(result_df) == 2\\n        assert list(result_df.columns) == [\\\"field1\\\", \\\"field2\\\", \\\"text\\\"]\\n        assert result_df[\\\"text\\\"].tolist() == [\\\"Row 1\\\", \\\"Row 2\\\"]\\n        assert result_df[\\\"field1\\\"].tolist() == [\\\"value1\\\", \\\"value2\\\"]\\n        assert result_df[\\\"field2\\\"].tolist() == [1, 2]\\n\\n    def test_single_data_input(self, component_class):\\n        \\\"\\\"\\\"Test handling single Data object input.\\\"\\\"\\\"\\n        single_data = Data(text=\\\"Single Row\\\", data={\\\"field1\\\": \\\"value\\\"})\\n        component = component_class()\\n        component.set_attributes({\\\"data_list\\\": single_data})\\n\\n        result_df = component.build_dataframe()\\n\\n        assert len(result_df) == 1\\n        assert result_df[\\\"text\\\"].iloc[0] == \\\"Single Row\\\"\\n        assert result_df[\\\"field1\\\"].iloc[0] == \\\"value\\\"\\n\\n    def test_empty_data_list(self, component_class):\\n        \\\"\\\"\\\"Test behavior with empty data list.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"data_list\\\": []})\\n\\n        result_df = component.build_dataframe()\\n\\n        assert len(result_df) == 0\\n\\n    def test_data_without_text(self, component_class):\\n        \\\"\\\"\\\"Test handling Data objects without text field.\\\"\\\"\\\"\\n        data_without_text = [Data(data={\\\"field1\\\": \\\"value1\\\"}), Data(data={\\\"field1\\\": \\\"value2\\\"})]\\n        component = component_class()\\n        component.set_attributes({\\\"data_list\\\": data_without_text})\\n\\n        result_df = component.build_dataframe()\\n\\n        assert len(result_df) == 2\\n        assert \\\"text\\\" not in result_df.columns\\n        assert result_df[\\\"field1\\\"].tolist() == [\\\"value1\\\", \\\"value2\\\"]\\n\\n    def test_data_without_data_dict(self, component_class):\\n        \\\"\\\"\\\"Test handling Data objects without data dictionary.\\\"\\\"\\\"\\n        data_without_dict = [Data(text=\\\"Text 1\\\"), Data(text=\\\"Text 2\\\")]\\n        component = component_class()\\n        component.set_attributes({\\\"data_list\\\": data_without_dict})\\n\\n        result_df = component.build_dataframe()\\n\\n        assert len(result_df) == 2\\n        assert list(result_df.columns) == [\\\"text\\\"]\\n        assert result_df[\\\"text\\\"].tolist() == [\\\"Text 1\\\", \\\"Text 2\\\"]\\n\\n    def test_mixed_data_fields(self, component_class):\\n        \\\"\\\"\\\"Test handling Data objects with different fields.\\\"\\\"\\\"\\n        mixed_data = [\\n            Data(text=\\\"Row 1\\\", data={\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": 1}),\\n            Data(text=\\\"Row 2\\\", data={\\\"field1\\\": \\\"value2\\\", \\\"field3\\\": \\\"extra\\\"}),\\n        ]\\n        component = component_class()\\n        component.set_attributes({\\\"data_list\\\": mixed_data})\\n\\n        result_df = component.build_dataframe()\\n\\n        assert len(result_df) == 2\\n        assert set(result_df.columns) == {\\\"field1\\\", \\\"field2\\\", \\\"field3\\\", \\\"text\\\"}\\n        assert result_df[\\\"field1\\\"].tolist() == [\\\"value1\\\", \\\"value2\\\"]\\n        assert result_df[\\\"field2\\\"].iloc[1] != result_df[\\\"field2\\\"].iloc[1]  # Check for NaN using inequality\\n        assert result_df[\\\"field3\\\"].iloc[0] != result_df[\\\"field3\\\"].iloc[0]  # Check for NaN using inequality\\n\\n    def test_invalid_input_type(self, component_class):\\n        \\\"\\\"\\\"Test error handling for invalid input types.\\\"\\\"\\\"\\n        invalid_data = [{\\\"not\\\": \\\"a Data object\\\"}]\\n        component = component_class()\\n        component.set_attributes({\\\"data_list\\\": invalid_data})\\n\\n        with pytest.raises(TypeError) as exc_info:\\n            component.build_dataframe()\\n        assert \\\"Expected Data objects\\\" in str(exc_info.value)\\n\\n    def test_status_update(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that status is properly updated.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        result = component.build_dataframe()\\n\\n        assert component.status is result  # Status should be set to the DataFrame\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_dataframe_operations.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ba916e565c33d8265cc5cb8d0da2ffc80ca9c8152f46f863c6fbd588a0211de7\",\"content\":\"import pandas as pd\\nimport pytest\\nfrom lfx.components.processing.dataframe_operations import DataFrameOperationsComponent\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\n@pytest.fixture\\ndef sample_dataframe():\\n    \\\"\\\"\\\"Create a comprehensive sample DataFrame for testing.\\\"\\\"\\\"\\n    data = {\\n        \\\"name\\\": [\\\"John Doe\\\", \\\"Jane Smith\\\", \\\"Bob Johnson\\\", \\\"Alice Brown\\\", \\\"Charlie Wilson\\\"],\\n        \\\"email\\\": [\\\"john@gmail.com\\\", \\\"jane@yahoo.com\\\", \\\"bob@gmail.com\\\", \\\"alice@hotmail.com\\\", \\\"charlie@outlook.com\\\"],\\n        \\\"age\\\": [25, 30, 35, 28, 42],\\n        \\\"salary\\\": [50000, 60000, 70000, 55000, 80000],\\n        \\\"department\\\": [\\\"IT\\\", \\\"HR\\\", \\\"Finance\\\", \\\"IT\\\", \\\"Marketing\\\"],\\n    }\\n    return DataFrame(pd.DataFrame(data))\\n\\n\\n@pytest.fixture\\ndef component():\\n    \\\"\\\"\\\"Create a DataFrameOperationsComponent instance.\\\"\\\"\\\"\\n    return DataFrameOperationsComponent()\\n\\n\\nclass TestBasicOperations:\\n    \\\"\\\"\\\"Test basic DataFrame operations with new SortableListInput format.\\\"\\\"\\\"\\n\\n    def test_add_column(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test adding a new column to the DataFrame.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Add Column\\\", \\\"icon\\\": \\\"plus\\\"}]\\n        component.new_column_name = \\\"bonus\\\"\\n        component.new_column_value = 5000\\n\\n        result = component.perform_operation()\\n\\n        assert \\\"bonus\\\" in result.columns\\n        assert len(result.columns) == 6  # Original 5 + 1 new\\n        assert all(result[\\\"bonus\\\"] == 5000)  # All values should be 5000\\n\\n    def test_drop_column(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test dropping a column from the DataFrame.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Drop Column\\\", \\\"icon\\\": \\\"minus\\\"}]\\n        component.column_name = \\\"salary\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert \\\"salary\\\" not in result.columns\\n        assert len(result.columns) == 4  # Original 5 - 1 dropped\\n\\n    def test_sort_ascending(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test sorting DataFrame in ascending order.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Sort\\\", \\\"icon\\\": \\\"arrow-up-down\\\"}]\\n        component.column_name = \\\"age\\\"\\n        component.ascending = True\\n\\n        result = component.perform_operation()\\n\\n        ages = result[\\\"age\\\"].tolist()\\n        assert ages == sorted(ages)  # Should be sorted ascending\\n        assert ages[0] == 25  # Youngest first\\n\\n    def test_sort_descending(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test sorting DataFrame in descending order.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Sort\\\", \\\"icon\\\": \\\"arrow-up-down\\\"}]\\n        component.column_name = \\\"salary\\\"\\n        component.ascending = False\\n\\n        result = component.perform_operation()\\n\\n        salaries = result[\\\"salary\\\"].tolist()\\n        assert salaries == sorted(salaries, reverse=True)  # Should be sorted descending\\n        assert salaries[0] == 80000  # Highest first\\n\\n    def test_head_operation(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test getting first N rows.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Head\\\", \\\"icon\\\": \\\"arrow-up\\\"}]\\n        component.num_rows = 2\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2\\n        assert result.iloc[0][\\\"name\\\"] == \\\"John Doe\\\"  # First row\\n\\n    def test_tail_operation(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test getting last N rows.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Tail\\\", \\\"icon\\\": \\\"arrow-down\\\"}]\\n        component.num_rows = 2\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2\\n        assert result.iloc[-1][\\\"name\\\"] == \\\"Charlie Wilson\\\"  # Last row\\n\\n    def test_rename_column(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test renaming a column.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Rename Column\\\", \\\"icon\\\": \\\"pencil\\\"}]\\n        component.column_name = \\\"name\\\"\\n        component.new_column_name = \\\"full_name\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert \\\"full_name\\\" in result.columns\\n        assert \\\"name\\\" not in result.columns\\n        assert result.iloc[0][\\\"full_name\\\"] == \\\"John Doe\\\"\\n\\n\\nclass TestFilterOperations:\\n    \\\"\\\"\\\"Test all filter operations with different operators.\\\"\\\"\\\"\\n\\n    def test_filter_equals(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test exact match filtering.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"department\\\"\\n        component.filter_operator = \\\"equals\\\"\\n        component.filter_value = \\\"IT\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # John and Alice work in IT\\n        assert all(result[\\\"department\\\"] == \\\"IT\\\")\\n\\n    def test_filter_not_equals(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test exclusion filtering.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"department\\\"\\n        component.filter_operator = \\\"not equals\\\"\\n        component.filter_value = \\\"IT\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 3  # Jane, Bob, Charlie not in IT\\n        assert all(result[\\\"department\\\"] != \\\"IT\\\")\\n\\n    def test_filter_contains(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test partial string matching - THE MAIN FEATURE WE ADDED!\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"email\\\"\\n        component.filter_operator = \\\"contains\\\"\\n        component.filter_value = \\\"gmail\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # John and Bob have gmail\\n        assert all(\\\"gmail\\\" in email for email in result[\\\"email\\\"])\\n\\n    def test_filter_starts_with(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test prefix matching.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"name\\\"\\n        component.filter_operator = \\\"starts with\\\"\\n        component.filter_value = \\\"J\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # John and Jane start with J\\n        assert all(name.startswith(\\\"J\\\") for name in result[\\\"name\\\"])\\n\\n    def test_filter_ends_with(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test suffix matching.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"email\\\"\\n        component.filter_operator = \\\"ends with\\\"\\n        component.filter_value = \\\".com\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 5  # All emails end with .com\\n        assert all(email.endswith(\\\".com\\\") for email in result[\\\"email\\\"])\\n\\n    def test_filter_greater_than(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test numeric greater than comparison.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"age\\\"\\n        component.filter_operator = \\\"greater than\\\"\\n        component.filter_value = \\\"30\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # Bob(35) and Charlie(42)\\n        assert all(age > 30 for age in result[\\\"age\\\"])\\n\\n    def test_filter_less_than(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test numeric less than comparison.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"salary\\\"\\n        component.filter_operator = \\\"less than\\\"\\n        component.filter_value = \\\"60000\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # John(50k) and Alice(55k)\\n        assert all(salary < 60000 for salary in result[\\\"salary\\\"])\\n\\n\\nclass TestEdgeCases:\\n    \\\"\\\"\\\"Test edge cases and error conditions.\\\"\\\"\\\"\\n\\n    def test_empty_selection(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test when no operation is selected (deselection).\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = []  # Empty selection\\n\\n        result = component.perform_operation()\\n\\n        # Should return original DataFrame unchanged\\n        assert len(result) == len(sample_dataframe)\\n        assert list(result.columns) == list(sample_dataframe.columns)\\n\\n    def test_invalid_operation_format(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test with invalid operation format raises error.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = \\\"Invalid String\\\"  # Not list format\\n\\n        with pytest.raises(ValueError, match=\\\"Unsupported operation\\\"):\\n            component.perform_operation()\\n\\n    def test_empty_dataframe(self, component):\\n        \\\"\\\"\\\"Test operations on empty DataFrame.\\\"\\\"\\\"\\n        component.df = DataFrame(pd.DataFrame())\\n        component.operation = [{\\\"name\\\": \\\"Head\\\", \\\"icon\\\": \\\"arrow-up\\\"}]\\n        component.num_rows = 3\\n\\n        result = component.perform_operation()\\n\\n        assert result.empty\\n\\n    def test_non_existent_column(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test operation on non-existent column.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Drop Column\\\", \\\"icon\\\": \\\"minus\\\"}]\\n        component.column_name = \\\"non_existent_column\\\"\\n\\n        with pytest.raises(KeyError):\\n            component.perform_operation()\\n\\n    def test_filter_no_matches(self, component, sample_dataframe):\\n        \\\"\\\"\\\"Test filter that returns no matches.\\\"\\\"\\\"\\n        component.df = sample_dataframe\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"department\\\"\\n        component.filter_operator = \\\"equals\\\"\\n        component.filter_value = \\\"NonExistentDepartment\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 0  # No matches\\n        assert list(result.columns) == list(sample_dataframe.columns)  # Columns preserved\\n\\n\\nclass TestDynamicUI:\\n    \\\"\\\"\\\"Test dynamic UI behavior with update_build_config.\\\"\\\"\\\"\\n\\n    def test_filter_fields_show(self, component):\\n        \\\"\\\"\\\"Test that filter fields show when Filter is selected.\\\"\\\"\\\"\\n        build_config = {\\n            \\\"column_name\\\": {\\\"show\\\": False},\\n            \\\"filter_value\\\": {\\\"show\\\": False},\\n            \\\"filter_operator\\\": {\\\"show\\\": False},\\n            \\\"ascending\\\": {\\\"show\\\": False},\\n            \\\"new_column_name\\\": {\\\"show\\\": False},\\n            \\\"new_column_value\\\": {\\\"show\\\": False},\\n            \\\"columns_to_select\\\": {\\\"show\\\": False},\\n            \\\"num_rows\\\": {\\\"show\\\": False},\\n            \\\"replace_value\\\": {\\\"show\\\": False},\\n            \\\"replacement_value\\\": {\\\"show\\\": False},\\n            \\\"merge_on_column\\\": {\\\"show\\\": False},\\n            \\\"merge_how\\\": {\\\"show\\\": False},\\n            \\\"left_dataframe\\\": {\\\"show\\\": False},\\n            \\\"right_dataframe\\\": {\\\"show\\\": False},\\n        }\\n\\n        # Select Filter operation\\n        updated_config = component.update_build_config(\\n            build_config, [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}], \\\"operation\\\"\\n        )\\n\\n        assert updated_config[\\\"column_name\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"filter_value\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"filter_operator\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"ascending\\\"][\\\"show\\\"] is False  # Not for filter\\n\\n    def test_sort_fields_show(self, component):\\n        \\\"\\\"\\\"Test that sort fields show when Sort is selected.\\\"\\\"\\\"\\n        build_config = {\\n            \\\"column_name\\\": {\\\"show\\\": False},\\n            \\\"filter_value\\\": {\\\"show\\\": False},\\n            \\\"filter_operator\\\": {\\\"show\\\": False},\\n            \\\"ascending\\\": {\\\"show\\\": False},\\n            \\\"new_column_name\\\": {\\\"show\\\": False},\\n            \\\"new_column_value\\\": {\\\"show\\\": False},\\n            \\\"columns_to_select\\\": {\\\"show\\\": False},\\n            \\\"num_rows\\\": {\\\"show\\\": False},\\n            \\\"replace_value\\\": {\\\"show\\\": False},\\n            \\\"replacement_value\\\": {\\\"show\\\": False},\\n            \\\"merge_on_column\\\": {\\\"show\\\": False},\\n            \\\"merge_how\\\": {\\\"show\\\": False},\\n            \\\"left_dataframe\\\": {\\\"show\\\": False},\\n            \\\"right_dataframe\\\": {\\\"show\\\": False},\\n        }\\n\\n        # Select Sort operation\\n        updated_config = component.update_build_config(\\n            build_config, [{\\\"name\\\": \\\"Sort\\\", \\\"icon\\\": \\\"arrow-up-down\\\"}], \\\"operation\\\"\\n        )\\n\\n        assert updated_config[\\\"column_name\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"ascending\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"filter_value\\\"][\\\"show\\\"] is False  # Not for sort\\n        assert updated_config[\\\"filter_operator\\\"][\\\"show\\\"] is False  # Not for sort\\n\\n    def test_empty_selection_hides_fields(self, component):\\n        \\\"\\\"\\\"Test that all fields hide when operation is deselected.\\\"\\\"\\\"\\n        build_config = {\\n            \\\"column_name\\\": {\\\"show\\\": True},\\n            \\\"filter_value\\\": {\\\"show\\\": True},\\n            \\\"filter_operator\\\": {\\\"show\\\": True},\\n            \\\"ascending\\\": {\\\"show\\\": True},\\n            \\\"new_column_name\\\": {\\\"show\\\": True},\\n            \\\"new_column_value\\\": {\\\"show\\\": True},\\n            \\\"columns_to_select\\\": {\\\"show\\\": True},\\n            \\\"num_rows\\\": {\\\"show\\\": True},\\n            \\\"replace_value\\\": {\\\"show\\\": True},\\n            \\\"replacement_value\\\": {\\\"show\\\": True},\\n            \\\"merge_on_column\\\": {\\\"show\\\": True},\\n            \\\"merge_how\\\": {\\\"show\\\": True},\\n            \\\"left_dataframe\\\": {\\\"show\\\": True},\\n            \\\"right_dataframe\\\": {\\\"show\\\": True},\\n        }\\n\\n        # Deselect operation (empty list)\\n        updated_config = component.update_build_config(\\n            build_config,\\n            [],  # Empty selection\\n            \\\"operation\\\",\\n        )\\n\\n        # All fields should be hidden\\n        assert updated_config[\\\"column_name\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"filter_value\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"filter_operator\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"ascending\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"new_column_name\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"new_column_value\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"columns_to_select\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"num_rows\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"replace_value\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"replacement_value\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"merge_on_column\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"merge_how\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"left_dataframe\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"right_dataframe\\\"][\\\"show\\\"] is False\\n\\n\\nclass TestDataTypes:\\n    \\\"\\\"\\\"Test different data types and conversions.\\\"\\\"\\\"\\n\\n    def test_numeric_string_conversion(self, component):\\n        \\\"\\\"\\\"Test that string numbers are properly converted for comparison.\\\"\\\"\\\"\\n        data = pd.DataFrame({\\\"values\\\": [10, 20, 30, 40, 50], \\\"names\\\": [\\\"a\\\", \\\"b\\\", \\\"c\\\", \\\"d\\\", \\\"e\\\"]})\\n\\n        component.df = DataFrame(data)\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"values\\\"\\n        component.filter_operator = \\\"greater than\\\"\\n        component.filter_value = \\\"25\\\"  # String input\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 3  # 30, 40, 50 are > 25\\n        assert all(val > 25 for val in result[\\\"values\\\"])\\n\\n    def test_mixed_data_types(self, component):\\n        \\\"\\\"\\\"Test filtering on mixed data types.\\\"\\\"\\\"\\n        data = pd.DataFrame({\\\"mixed\\\": [\\\"text\\\", 123, \\\"more_text\\\", 456], \\\"id\\\": [1, 2, 3, 4]})\\n\\n        component.df = DataFrame(data)\\n        component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n        component.column_name = \\\"mixed\\\"\\n        component.filter_operator = \\\"contains\\\"\\n        component.filter_value = \\\"text\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # \\\"text\\\" and \\\"more_text\\\"\\n\\n\\nclass TestConcatenateOperation:\\n    \\\"\\\"\\\"Test concatenate operation for combining multiple DataFrames.\\\"\\\"\\\"\\n\\n    def test_concatenate_two_dataframes(self, component):\\n        \\\"\\\"\\\"Test concatenating two DataFrames vertically.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [3, 4], \\\"name\\\": [\\\"Charlie\\\", \\\"Diana\\\"]}))\\n\\n        component.df = [df1, df2]\\n        component.operation = [{\\\"name\\\": \\\"Concatenate\\\", \\\"icon\\\": \\\"combine\\\"}]\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 4\\n        assert list(result[\\\"id\\\"]) == [1, 2, 3, 4]\\n        assert list(result[\\\"name\\\"]) == [\\\"Alice\\\", \\\"Bob\\\", \\\"Charlie\\\", \\\"Diana\\\"]\\n\\n    def test_concatenate_single_dataframe(self, component):\\n        \\\"\\\"\\\"Test concatenate with only one DataFrame returns it unchanged.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n\\n        component.df = [df1]\\n        component.operation = [{\\\"name\\\": \\\"Concatenate\\\", \\\"icon\\\": \\\"combine\\\"}]\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2\\n        assert list(result[\\\"id\\\"]) == [1, 2]\\n\\n    def test_concatenate_different_row_counts(self, component):\\n        \\\"\\\"\\\"Test concatenating DataFrames with different row counts.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2, 3], \\\"value\\\": [\\\"a\\\", \\\"b\\\", \\\"c\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [4, 5], \\\"value\\\": [\\\"d\\\", \\\"e\\\"]}))\\n\\n        component.df = [df1, df2]\\n        component.operation = [{\\\"name\\\": \\\"Concatenate\\\", \\\"icon\\\": \\\"combine\\\"}]\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 5\\n\\n\\nclass TestMergeOperation:\\n    \\\"\\\"\\\"Test merge operation for joining DataFrames.\\\"\\\"\\\"\\n\\n    def test_merge_inner_join(self, component):\\n        \\\"\\\"\\\"Test inner merge on common column.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2, 3], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\", \\\"Charlie\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 3, 4], \\\"city\\\": [\\\"NYC\\\", \\\"LA\\\", \\\"Chicago\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = df2\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"id\\\"\\n        component.merge_how = \\\"inner\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2  # Only ids 2 and 3 exist in both\\n        assert \\\"name\\\" in result.columns\\n        assert \\\"city\\\" in result.columns\\n\\n    def test_merge_outer_join(self, component):\\n        \\\"\\\"\\\"Test outer merge includes all records.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 3], \\\"city\\\": [\\\"NYC\\\", \\\"LA\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = df2\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"id\\\"\\n        component.merge_how = \\\"outer\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 3  # ids 1, 2, 3\\n\\n    def test_merge_left_join(self, component):\\n        \\\"\\\"\\\"Test left merge keeps all records from left DataFrame.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2, 3], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\", \\\"Charlie\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 4], \\\"city\\\": [\\\"NYC\\\", \\\"Chicago\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = df2\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"id\\\"\\n        component.merge_how = \\\"left\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 3  # All from left (df1)\\n\\n    def test_merge_right_join(self, component):\\n        \\\"\\\"\\\"Test right merge keeps all records from right DataFrame.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 3, 4], \\\"city\\\": [\\\"NYC\\\", \\\"LA\\\", \\\"Chicago\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = df2\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"id\\\"\\n        component.merge_how = \\\"right\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 3  # All from right (df2)\\n\\n    def test_should_preserve_left_rows_when_left_merge_with_explicit_inputs(self, component):\\n        \\\"\\\"\\\"Test that left merge deterministically preserves all rows from the explicit left DataFrame.\\n\\n        This is the core bug fix test: with overlapping but distinct customer_ids,\\n        a left merge must always keep all rows from left_dataframe regardless of\\n        connection order.\\n        \\\"\\\"\\\"\\n        # Arrange \u2014 exact scenario from bug report\\n        df_a = DataFrame(\\n            pd.DataFrame(\\n                {\\n                    \\\"customer_id\\\": [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-003\\\", \\\"CUST-004\\\"],\\n                    \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\", \\\"Carol\\\", \\\"David\\\"],\\n                }\\n            )\\n        )\\n        df_b = DataFrame(\\n            pd.DataFrame(\\n                {\\n                    \\\"customer_id\\\": [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-005\\\", \\\"CUST-006\\\"],\\n                    \\\"product\\\": [\\\"Notebook\\\", \\\"Mouse\\\", \\\"Keyboard\\\", \\\"Monitor\\\"],\\n                }\\n            )\\n        )\\n\\n        # Act \u2014 df_a is explicitly set as left, df_b as right\\n        component.left_dataframe = df_a\\n        component.right_dataframe = df_b\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"customer_id\\\"\\n        component.merge_how = \\\"left\\\"\\n\\n        result = component.perform_operation()\\n\\n        # Assert \u2014 all 4 rows from left (df_a) must be preserved\\n        result_ids = sorted(result[\\\"customer_id\\\"].tolist())\\n        assert result_ids == [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-003\\\", \\\"CUST-004\\\"]\\n        assert len(result) == 4\\n        # CUST-003 and CUST-004 should have NaN product (not in df_b)\\n        assert pd.isna(result.loc[result[\\\"customer_id\\\"] == \\\"CUST-003\\\", \\\"product\\\"].iloc[0])\\n        assert pd.isna(result.loc[result[\\\"customer_id\\\"] == \\\"CUST-004\\\", \\\"product\\\"].iloc[0])\\n\\n    def test_should_preserve_right_rows_when_right_merge_with_explicit_inputs(self, component):\\n        \\\"\\\"\\\"Test that right merge deterministically preserves all rows from the explicit right DataFrame.\\\"\\\"\\\"\\n        # Arrange \u2014 same data, but now we want df_b's rows preserved\\n        df_a = DataFrame(\\n            pd.DataFrame(\\n                {\\n                    \\\"customer_id\\\": [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-003\\\", \\\"CUST-004\\\"],\\n                    \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\", \\\"Carol\\\", \\\"David\\\"],\\n                }\\n            )\\n        )\\n        df_b = DataFrame(\\n            pd.DataFrame(\\n                {\\n                    \\\"customer_id\\\": [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-005\\\", \\\"CUST-006\\\"],\\n                    \\\"product\\\": [\\\"Notebook\\\", \\\"Mouse\\\", \\\"Keyboard\\\", \\\"Monitor\\\"],\\n                }\\n            )\\n        )\\n\\n        # Act \u2014 df_a is left, df_b is right, merge type is \\\"right\\\"\\n        component.left_dataframe = df_a\\n        component.right_dataframe = df_b\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"customer_id\\\"\\n        component.merge_how = \\\"right\\\"\\n\\n        result = component.perform_operation()\\n\\n        # Assert \u2014 all 4 rows from right (df_b) must be preserved\\n        result_ids = sorted(result[\\\"customer_id\\\"].tolist())\\n        assert result_ids == [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-005\\\", \\\"CUST-006\\\"]\\n        assert len(result) == 4\\n        # CUST-005 and CUST-006 should have NaN name (not in df_a)\\n        assert pd.isna(result.loc[result[\\\"customer_id\\\"] == \\\"CUST-005\\\", \\\"name\\\"].iloc[0])\\n        assert pd.isna(result.loc[result[\\\"customer_id\\\"] == \\\"CUST-006\\\", \\\"name\\\"].iloc[0])\\n\\n    def test_should_swap_results_when_left_right_inputs_are_swapped(self, component):\\n        \\\"\\\"\\\"Test that swapping left/right inputs produces different, deterministic results.\\\"\\\"\\\"\\n        df_a = DataFrame(\\n            pd.DataFrame(\\n                {\\n                    \\\"customer_id\\\": [\\\"CUST-001\\\", \\\"CUST-002\\\", \\\"CUST-003\\\"],\\n                    \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\", \\\"Carol\\\"],\\n                }\\n            )\\n        )\\n        df_b = DataFrame(\\n            pd.DataFrame(\\n                {\\n                    \\\"customer_id\\\": [\\\"CUST-002\\\", \\\"CUST-004\\\"],\\n                    \\\"city\\\": [\\\"NYC\\\", \\\"Chicago\\\"],\\n                }\\n            )\\n        )\\n\\n        # Left merge with df_a as left\\n        component.left_dataframe = df_a\\n        component.right_dataframe = df_b\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"customer_id\\\"\\n        component.merge_how = \\\"left\\\"\\n        result_a_left = component.perform_operation()\\n\\n        # Left merge with df_b as left (swapped)\\n        component.left_dataframe = df_b\\n        component.right_dataframe = df_a\\n        result_b_left = component.perform_operation()\\n\\n        # Results must be different \u2014 df_a has 3 rows, df_b has 2\\n        assert len(result_a_left) == 3  # All from df_a\\n        assert len(result_b_left) == 2  # All from df_b\\n\\n    def test_merge_single_dataframe_returns_original(self, component):\\n        \\\"\\\"\\\"Test merge with single left DataFrame and no right returns it unchanged.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = None\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"id\\\"\\n        component.merge_how = \\\"inner\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 2\\n\\n    def test_merge_invalid_column_raises_error(self, component):\\n        \\\"\\\"\\\"Test merge with non-existent column raises ValueError.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 3], \\\"city\\\": [\\\"NYC\\\", \\\"LA\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = df2\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"non_existent\\\"\\n        component.merge_how = \\\"inner\\\"\\n\\n        with pytest.raises(ValueError, match=\\\"not found in left DataFrame\\\"):\\n            component.perform_operation()\\n\\n    def test_merge_same_columns_coalesces_values(self, component):\\n        \\\"\\\"\\\"Test merge with same columns uses coalesce (left value or right value).\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"value\\\": [\\\"a\\\", \\\"b\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 3], \\\"value\\\": [\\\"x\\\", \\\"y\\\"]}))\\n\\n        component.left_dataframe = df1\\n        component.right_dataframe = df2\\n        component.operation = [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}]\\n        component.merge_on_column = \\\"id\\\"\\n        component.merge_how = \\\"outer\\\"\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 3\\n        # Check no duplicate columns with _right suffix\\n        assert \\\"value_right\\\" not in result.columns\\n        # Verify coalesced values\\n        assert result.loc[result[\\\"id\\\"] == 1, \\\"value\\\"].iloc[0] == \\\"a\\\"  # from left\\n        assert result.loc[result[\\\"id\\\"] == 2, \\\"value\\\"].iloc[0] == \\\"b\\\"  # from left (coalesced)\\n        assert result.loc[result[\\\"id\\\"] == 3, \\\"value\\\"].iloc[0] == \\\"y\\\"  # from right\\n\\n\\nclass TestListInputHandling:\\n    \\\"\\\"\\\"Test that component handles list inputs correctly.\\\"\\\"\\\"\\n\\n    def test_operations_use_first_dataframe_from_list(self, component):\\n        \\\"\\\"\\\"Test that non-merge operations use only the first DataFrame.\\\"\\\"\\\"\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [3, 4], \\\"name\\\": [\\\"Charlie\\\", \\\"Diana\\\"]}))\\n\\n        component.df = [df1, df2]\\n        component.operation = [{\\\"name\\\": \\\"Head\\\", \\\"icon\\\": \\\"arrow-up\\\"}]\\n        component.num_rows = 1\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == 1\\n        assert result.iloc[0][\\\"name\\\"] == \\\"Alice\\\"  # From first DataFrame\\n\\n\\nclass TestMergeDynamicUI:\\n    \\\"\\\"\\\"Test dynamic UI for Merge and Concatenate operations.\\\"\\\"\\\"\\n\\n    def test_merge_fields_show(self, component):\\n        \\\"\\\"\\\"Test that merge fields show when Merge is selected.\\\"\\\"\\\"\\n        build_config = {\\n            \\\"column_name\\\": {\\\"show\\\": False},\\n            \\\"filter_value\\\": {\\\"show\\\": False},\\n            \\\"filter_operator\\\": {\\\"show\\\": False},\\n            \\\"ascending\\\": {\\\"show\\\": False},\\n            \\\"new_column_name\\\": {\\\"show\\\": False},\\n            \\\"new_column_value\\\": {\\\"show\\\": False},\\n            \\\"columns_to_select\\\": {\\\"show\\\": False},\\n            \\\"num_rows\\\": {\\\"show\\\": False},\\n            \\\"replace_value\\\": {\\\"show\\\": False},\\n            \\\"replacement_value\\\": {\\\"show\\\": False},\\n            \\\"merge_on_column\\\": {\\\"show\\\": False},\\n            \\\"merge_how\\\": {\\\"show\\\": False},\\n            \\\"left_dataframe\\\": {\\\"show\\\": False},\\n            \\\"right_dataframe\\\": {\\\"show\\\": False},\\n        }\\n\\n        updated_config = component.update_build_config(build_config, [{\\\"name\\\": \\\"Merge\\\", \\\"icon\\\": \\\"merge\\\"}], \\\"operation\\\")\\n\\n        assert updated_config[\\\"merge_on_column\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"merge_how\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"left_dataframe\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"right_dataframe\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"column_name\\\"][\\\"show\\\"] is False\\n\\n    def test_concatenate_hides_all_extra_fields(self, component):\\n        \\\"\\\"\\\"Test that Concatenate operation hides all extra fields.\\\"\\\"\\\"\\n        build_config = {\\n            \\\"column_name\\\": {\\\"show\\\": True},\\n            \\\"filter_value\\\": {\\\"show\\\": True},\\n            \\\"filter_operator\\\": {\\\"show\\\": True},\\n            \\\"ascending\\\": {\\\"show\\\": True},\\n            \\\"new_column_name\\\": {\\\"show\\\": True},\\n            \\\"new_column_value\\\": {\\\"show\\\": True},\\n            \\\"columns_to_select\\\": {\\\"show\\\": True},\\n            \\\"num_rows\\\": {\\\"show\\\": True},\\n            \\\"replace_value\\\": {\\\"show\\\": True},\\n            \\\"replacement_value\\\": {\\\"show\\\": True},\\n            \\\"merge_on_column\\\": {\\\"show\\\": True},\\n            \\\"merge_how\\\": {\\\"show\\\": True},\\n            \\\"left_dataframe\\\": {\\\"show\\\": True},\\n            \\\"right_dataframe\\\": {\\\"show\\\": True},\\n        }\\n\\n        updated_config = component.update_build_config(\\n            build_config, [{\\\"name\\\": \\\"Concatenate\\\", \\\"icon\\\": \\\"combine\\\"}], \\\"operation\\\"\\n        )\\n\\n        # Concatenate doesn't need any extra fields\\n        assert updated_config[\\\"column_name\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"merge_on_column\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"merge_how\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"left_dataframe\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"right_dataframe\\\"][\\\"show\\\"] is False\\n\\n\\n# Integration test to verify all operators work together\\ndef test_all_filter_operators_comprehensive():\\n    \\\"\\\"\\\"Comprehensive test of all filter operators on the same dataset.\\\"\\\"\\\"\\n    data = pd.DataFrame(\\n        {\\n            \\\"name\\\": [\\\"John\\\", \\\"Jane\\\", \\\"Bob\\\", \\\"Alice\\\"],\\n            \\\"email\\\": [\\\"john@gmail.com\\\", \\\"jane@yahoo.com\\\", \\\"bob@gmail.com\\\", \\\"alice@test.org\\\"],\\n            \\\"age\\\": [25, 30, 35, 28],\\n            \\\"score\\\": [85.5, 92.0, 78.5, 88.0],\\n        }\\n    )\\n\\n    component = DataFrameOperationsComponent()\\n    component.df = DataFrame(data)\\n    component.operation = [{\\\"name\\\": \\\"Filter\\\", \\\"icon\\\": \\\"filter\\\"}]\\n\\n    # Test all operators\\n    test_cases = [\\n        (\\\"email\\\", \\\"contains\\\", \\\"gmail\\\", 2),  # John, Bob\\n        (\\\"name\\\", \\\"starts with\\\", \\\"J\\\", 2),  # John, Jane\\n        (\\\"email\\\", \\\"ends with\\\", \\\".com\\\", 3),  # All except Alice\\n        (\\\"age\\\", \\\"greater than\\\", \\\"28\\\", 2),  # Jane, Bob\\n        (\\\"score\\\", \\\"less than\\\", \\\"90\\\", 3),  # John, Bob, Alice\\n        (\\\"name\\\", \\\"equals\\\", \\\"John\\\", 1),  # Only John\\n        (\\\"email\\\", \\\"not equals\\\", \\\"jane@yahoo.com\\\", 3),  # All except Jane\\n    ]\\n\\n    for column, operator, value, expected_count in test_cases:\\n        component.column_name = column\\n        component.filter_operator = operator\\n        component.filter_value = value\\n\\n        result = component.perform_operation()\\n\\n        assert len(result) == expected_count, f\\\"Failed for {operator} on {column} with value {value}\\\"\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    pytest.main([__file__])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_dynamic_create_data_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3308887fb19113ecd7b9e995d6a3545ed1c53d34371449d0fdd559997ec982bd\",\"content\":\"from lfx.components.processing.dynamic_create_data import DynamicCreateDataComponent\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\n\\n\\nclass TestDynamicCreateDataComponent:\\n    def test_update_build_config_creates_dynamic_inputs(self):\\n        \\\"\\\"\\\"Test that dynamic inputs are created based on form_fields configuration.\\\"\\\"\\\"\\n        component = DynamicCreateDataComponent()\\n        build_config = {\\\"form_fields\\\": {\\\"value\\\": []}}\\n\\n        field_value = [\\n            {\\\"field_name\\\": \\\"username\\\", \\\"field_type\\\": \\\"Text\\\"},\\n            {\\\"field_name\\\": \\\"age\\\", \\\"field_type\\\": \\\"Number\\\"},\\n            {\\\"field_name\\\": \\\"active\\\", \\\"field_type\\\": \\\"Boolean\\\"},\\n        ]\\n\\n        result = component.update_build_config(build_config, field_value, \\\"form_fields\\\")\\n\\n        assert \\\"dynamic_username\\\" in result\\n        assert \\\"dynamic_age\\\" in result\\n        assert \\\"dynamic_active\\\" in result\\n        assert result[\\\"dynamic_username\\\"].display_name == \\\"username\\\"\\n        assert result[\\\"dynamic_age\\\"].display_name == \\\"age\\\"\\n\\n    def test_update_build_config_clears_old_dynamic_inputs(self):\\n        \\\"\\\"\\\"Test that old dynamic inputs are removed when form_fields change.\\\"\\\"\\\"\\n        component = DynamicCreateDataComponent()\\n        build_config = {\\n            \\\"dynamic_old_field\\\": {\\\"display_name\\\": \\\"Old Field\\\"},\\n            \\\"form_fields\\\": {\\\"value\\\": []},\\n        }\\n\\n        field_value = [{\\\"field_name\\\": \\\"new_field\\\", \\\"field_type\\\": \\\"Text\\\"}]\\n\\n        result = component.update_build_config(build_config, field_value, \\\"form_fields\\\")\\n\\n        assert \\\"dynamic_old_field\\\" not in result\\n        assert \\\"dynamic_new_field\\\" in result\\n\\n    def test_process_form_returns_data_with_simple_values(self):\\n        \\\"\\\"\\\"Test that process_form extracts and returns simple values from inputs.\\\"\\\"\\\"\\n        component = DynamicCreateDataComponent()\\n        component.form_fields = [\\n            {\\\"field_name\\\": \\\"name\\\", \\\"field_type\\\": \\\"Text\\\"},\\n            {\\\"field_name\\\": \\\"count\\\", \\\"field_type\\\": \\\"Number\\\"},\\n        ]\\n\\n        # Simulate manual input values\\n        component.dynamic_name = \\\"John Doe\\\"\\n        component.dynamic_count = 42\\n\\n        result = component.process_form()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"name\\\"] == \\\"John Doe\\\"\\n        assert result.data[\\\"count\\\"] == 42\\n\\n    def test_extract_simple_value_handles_message_objects(self):\\n        \\\"\\\"\\\"Test that Message objects are properly extracted to their text content.\\\"\\\"\\\"\\n        component = DynamicCreateDataComponent()\\n\\n        test_message = Message(text=\\\"Hello World\\\")\\n        result = component._extract_simple_value(test_message)\\n\\n        assert result == \\\"Hello World\\\"\\n        assert isinstance(result, str)\\n\\n    def test_get_message_formats_data_as_text(self):\\n        \\\"\\\"\\\"Test that get_message returns properly formatted text output.\\\"\\\"\\\"\\n        component = DynamicCreateDataComponent()\\n        component.form_fields = [\\n            {\\\"field_name\\\": \\\"title\\\", \\\"field_type\\\": \\\"Text\\\"},\\n            {\\\"field_name\\\": \\\"enabled\\\", \\\"field_type\\\": \\\"Boolean\\\"},\\n        ]\\n\\n        component.dynamic_title = \\\"Test Title\\\"\\n        component.dynamic_enabled = True\\n\\n        result = component.get_message()\\n\\n        assert isinstance(result, Message)\\n        assert \\\"title\\\" in result.text\\n        assert \\\"Test Title\\\" in result.text\\n        assert \\\"enabled\\\" in result.text\\n\\n    def test_handles_none_field_config_gracefully(self):\\n        \\\"\\\"\\\"Test that None values in form_fields are handled without errors.\\\"\\\"\\\"\\n        component = DynamicCreateDataComponent()\\n        build_config = {\\\"form_fields\\\": {\\\"value\\\": []}}\\n\\n        field_value = [\\n            {\\\"field_name\\\": \\\"valid_field\\\", \\\"field_type\\\": \\\"Text\\\"},\\n            None,  # This should be skipped\\n            {\\\"field_name\\\": \\\"another_field\\\", \\\"field_type\\\": \\\"Number\\\"},\\n        ]\\n\\n        result = component.update_build_config(build_config, field_value, \\\"form_fields\\\")\\n\\n        assert \\\"dynamic_valid_field\\\" in result\\n        assert \\\"dynamic_another_field\\\" in result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_operations_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"194dbac3ccff7fdba45181997801ec4b47560fafc6ab25dede11991e362ef77f\",\"content\":\"\\\"\\\"\\\"Tests for the unified Operations component.\\n\\nThe Operations component merges the legacy JSON Operations, Table Operations,\\nand Text Operations components into a single component with a flat operation\\npicker. These tests cover one representative operation from each data type,\\nthe dynamic input/output routing, and the removal of the legacy \\\"Filter\\nValues\\\" operation.\\n\\\"\\\"\\\"\\n\\nimport pandas as pd\\nimport pytest\\nfrom lfx.components.processing.data_operations import DataOperationsComponent\\nfrom lfx.components.processing.dataframe_operations import DataFrameOperationsComponent\\nfrom lfx.components.processing.operations import (\\n    JSON_OPERATIONS,\\n    OPERATIONS_BY_TYPE,\\n    TABLE_OPERATIONS,\\n    TEXT_OPERATIONS,\\n    OperationsComponent,\\n)\\nfrom lfx.components.processing.text_operations import TextOperations\\nfrom lfx.schema import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestOperationsComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return OperationsComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"text_input\\\": \\\"Hello world\\\",\\n            \\\"operation\\\": [{\\\"name\\\": \\\"Word Count\\\"}],\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"legacy_component\\\",\\n    [DataOperationsComponent, DataFrameOperationsComponent, TextOperations],\\n)\\ndef test_legacy_operations_components_point_to_unified_replacement(legacy_component):\\n    assert legacy_component.replacement == [\\\"processing.Operations\\\"]\\n\\n\\nclass TestOperationCatalog:\\n    \\\"\\\"\\\"The unified picker exposes every operation across all three data types.\\n\\n    The Operation picker is filtered by the Input Type selector, so the picker's\\n    ``options`` only ever hold one type's operations at a time. These tests\\n    assert against the full catalog (``OPERATIONS_BY_TYPE``) plus the Text-typed\\n    default the picker ships with.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _all_operations():\\n        \\\"\\\"\\\"Every operation across all input types (the full catalog).\\\"\\\"\\\"\\n        return [opt for options in OPERATIONS_BY_TYPE.values() for opt in options]\\n\\n    def test_picker_lists_all_operations(self):\\n        names = {opt[\\\"name\\\"] for opt in self._all_operations()}\\n        assert names == JSON_OPERATIONS | TABLE_OPERATIONS | TEXT_OPERATIONS\\n\\n    def test_default_picker_shows_text_operations(self):\\n        \\\"\\\"\\\"A freshly dropped component defaults to \\\"Text\\\", so the picker is pre-filtered to Text ops.\\\"\\\"\\\"\\n        component = OperationsComponent()\\n        operation_input = next(i for i in component.inputs if i.name == \\\"operation\\\")\\n        names = {opt[\\\"name\\\"] for opt in operation_input.options}\\n        assert names == TEXT_OPERATIONS\\n\\n    def test_filter_values_operation_is_removed(self):\\n        \\\"\\\"\\\"The legacy Data-List \\\"Filter Values\\\" remnant must not be carried forward.\\\"\\\"\\\"\\n        names = {opt[\\\"name\\\"] for opt in self._all_operations()}\\n        assert \\\"Filter Values\\\" not in names\\n\\n    def test_every_operation_has_field_mapping(self):\\n        component = OperationsComponent()\\n        for opt in self._all_operations():\\n            assert opt[\\\"name\\\"] in component.OPERATION_FIELDS\\n\\n\\nclass TestJsonOperations:\\n    def test_select_keys(self):\\n        component = OperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\", \\\"key3\\\": \\\"value3\\\"}),\\n            operation=[{\\\"name\\\": \\\"Select Keys\\\"}],\\n            select_keys_input=[\\\"key1\\\", \\\"key2\\\"],\\n        )\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert \\\"key1\\\" in result.data\\n        assert \\\"key3\\\" not in result.data\\n\\n    def test_remove_keys(self):\\n        component = OperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}),\\n            operation=[{\\\"name\\\": \\\"Remove Keys\\\"}],\\n            remove_keys_input=[\\\"key2\\\"],\\n        )\\n        result = component.as_data()\\n        assert \\\"key1\\\" in result.data\\n        assert \\\"key2\\\" not in result.data\\n\\n    def test_rename_keys(self):\\n        component = OperationsComponent(\\n            data=Data(data={\\\"key1\\\": \\\"value1\\\"}),\\n            operation=[{\\\"name\\\": \\\"Rename Keys\\\"}],\\n            rename_keys_input={\\\"key1\\\": \\\"new_key1\\\"},\\n        )\\n        result = component.as_data()\\n        assert \\\"new_key1\\\" in result.data\\n        assert \\\"key1\\\" not in result.data\\n\\n    def test_literal_eval(self):\\n        component = OperationsComponent(\\n            data=Data(data={\\\"list_as_string\\\": \\\"[1, 2, 3]\\\"}),\\n            operation=[{\\\"name\\\": \\\"Literal Eval\\\"}],\\n        )\\n        result = component.as_data()\\n        assert result.data[\\\"list_as_string\\\"] == [1, 2, 3]\\n\\n    def test_combine(self):\\n        component = OperationsComponent(\\n            data=[Data(data={\\\"key1\\\": \\\"value1\\\"}), Data(data={\\\"key2\\\": \\\"value2\\\"})],\\n            operation=[{\\\"name\\\": \\\"Combine\\\"}],\\n        )\\n        result = component.as_data()\\n        assert result.data[\\\"key1\\\"] == \\\"value1\\\"\\n        assert result.data[\\\"key2\\\"] == \\\"value2\\\"\\n\\n    def test_append_update(self):\\n        component = OperationsComponent(\\n            data=Data(data={\\\"existing_key\\\": \\\"existing_value\\\"}),\\n            operation=[{\\\"name\\\": \\\"Append or Update\\\"}],\\n            append_update_data={\\\"new_key\\\": \\\"new_value\\\", \\\"existing_key\\\": \\\"updated_value\\\"},\\n        )\\n        result = component.as_data()\\n        assert result.data[\\\"existing_key\\\"] == \\\"updated_value\\\"\\n        assert result.data[\\\"new_key\\\"] == \\\"new_value\\\"\\n\\n    def test_select_keys_rejects_multiple_data(self):\\n        component = OperationsComponent(\\n            data=[Data(data={\\\"key1\\\": \\\"value1\\\"}), Data(data={\\\"key2\\\": \\\"value2\\\"})],\\n            operation=[{\\\"name\\\": \\\"Select Keys\\\"}],\\n            select_keys_input=[\\\"key1\\\"],\\n        )\\n        with pytest.raises(ValueError, match=\\\"not supported for multiple data objects\\\"):\\n            component.as_data()\\n\\n\\nclass TestTableOperations:\\n    @pytest.fixture\\n    def sample_dataframe(self):\\n        data = {\\n            \\\"name\\\": [\\\"John\\\", \\\"Jane\\\", \\\"Bob\\\", \\\"Alice\\\"],\\n            \\\"email\\\": [\\\"john@gmail.com\\\", \\\"jane@yahoo.com\\\", \\\"bob@gmail.com\\\", \\\"alice@test.org\\\"],\\n            \\\"department\\\": [\\\"IT\\\", \\\"HR\\\", \\\"Finance\\\", \\\"IT\\\"],\\n        }\\n        return DataFrame(pd.DataFrame(data))\\n\\n    def test_filter_equals(self, sample_dataframe):\\n        component = OperationsComponent(\\n            df=sample_dataframe,\\n            operation=[{\\\"name\\\": \\\"Filter\\\"}],\\n            column_name=\\\"department\\\",\\n            filter_operator=\\\"equals\\\",\\n            filter_value=\\\"IT\\\",\\n        )\\n        result = component.as_dataframe()\\n        assert len(result) == 2\\n        assert all(result[\\\"department\\\"] == \\\"IT\\\")\\n\\n    def test_filter_contains(self, sample_dataframe):\\n        component = OperationsComponent(\\n            df=sample_dataframe,\\n            operation=[{\\\"name\\\": \\\"Filter\\\"}],\\n            column_name=\\\"email\\\",\\n            filter_operator=\\\"contains\\\",\\n            filter_value=\\\"gmail\\\",\\n        )\\n        result = component.as_dataframe()\\n        assert len(result) == 2\\n\\n    def test_drop_column(self, sample_dataframe):\\n        component = OperationsComponent(\\n            df=sample_dataframe,\\n            operation=[{\\\"name\\\": \\\"Drop Column\\\"}],\\n            column_name=\\\"email\\\",\\n        )\\n        result = component.as_dataframe()\\n        assert \\\"email\\\" not in result.columns\\n\\n    def test_add_column(self, sample_dataframe):\\n        component = OperationsComponent(\\n            df=sample_dataframe,\\n            operation=[{\\\"name\\\": \\\"Add Column\\\"}],\\n            new_column_name=\\\"active\\\",\\n            new_column_value=True,\\n        )\\n        result = component.as_dataframe()\\n        assert \\\"active\\\" in result.columns\\n        assert all(result[\\\"active\\\"])\\n\\n    def test_head(self, sample_dataframe):\\n        component = OperationsComponent(\\n            df=sample_dataframe,\\n            operation=[{\\\"name\\\": \\\"Head\\\"}],\\n            num_rows=2,\\n        )\\n        assert len(component.as_dataframe()) == 2\\n\\n    def test_concatenate(self):\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [3, 4], \\\"name\\\": [\\\"Charlie\\\", \\\"Diana\\\"]}))\\n        component = OperationsComponent(df=[df1, df2], operation=[{\\\"name\\\": \\\"Concatenate\\\"}])\\n        result = component.as_dataframe()\\n        assert len(result) == 4\\n\\n    def test_merge_inner_join(self):\\n        df1 = DataFrame(pd.DataFrame({\\\"id\\\": [1, 2, 3], \\\"name\\\": [\\\"Alice\\\", \\\"Bob\\\", \\\"Charlie\\\"]}))\\n        df2 = DataFrame(pd.DataFrame({\\\"id\\\": [2, 3, 4], \\\"city\\\": [\\\"NYC\\\", \\\"LA\\\", \\\"Chicago\\\"]}))\\n        component = OperationsComponent(\\n            operation=[{\\\"name\\\": \\\"Merge\\\"}],\\n            left_dataframe=df1,\\n            right_dataframe=df2,\\n            merge_on_column=\\\"id\\\",\\n            merge_how=\\\"inner\\\",\\n        )\\n        result = component.as_dataframe()\\n        assert len(result) == 2\\n        assert \\\"name\\\" in result.columns\\n        assert \\\"city\\\" in result.columns\\n\\n\\nclass TestTextOperations:\\n    def test_word_count_returns_data(self):\\n        component = OperationsComponent(\\n            text_input=\\\"Hello world this is a test\\\",\\n            operation=[{\\\"name\\\": \\\"Word Count\\\"}],\\n            count_words=True,\\n            count_characters=False,\\n            count_lines=False,\\n        )\\n        result = component.as_data()\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"word_count\\\"] == 6\\n\\n    def test_case_conversion_returns_message(self):\\n        component = OperationsComponent(\\n            text_input=\\\"hello\\\",\\n            operation=[{\\\"name\\\": \\\"Case Conversion\\\"}],\\n            case_type=\\\"uppercase\\\",\\n        )\\n        result = component.as_message()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"HELLO\\\"\\n\\n    def test_text_replace(self):\\n        component = OperationsComponent(\\n            text_input=\\\"hello world\\\",\\n            operation=[{\\\"name\\\": \\\"Text Replace\\\"}],\\n            search_pattern=\\\"world\\\",\\n            replacement_text=\\\"there\\\",\\n            use_regex=False,\\n        )\\n        assert component.as_message().text == \\\"hello there\\\"\\n\\n    def test_text_join(self):\\n        component = OperationsComponent(\\n            text_input=\\\"first\\\",\\n            operation=[{\\\"name\\\": \\\"Text Join\\\"}],\\n            text_input_2=\\\"second\\\",\\n        )\\n        assert component.as_message().text == \\\"first\\\\nsecond\\\"\\n        assert component.as_text().text == \\\"first\\\\nsecond\\\"\\n\\n    def test_text_to_dataframe(self):\\n        component = OperationsComponent(\\n            text_input=\\\"name|age\\\\nAlice|30\\\\nBob|25\\\",\\n            operation=[{\\\"name\\\": \\\"Text to DataFrame\\\"}],\\n            table_separator=\\\"|\\\",\\n            has_header=True,\\n        )\\n        result = component.as_dataframe()\\n        assert isinstance(result, DataFrame)\\n        assert list(result.columns) == [\\\"name\\\", \\\"age\\\"]\\n        assert len(result) == 2\\n\\n    def test_text_clean(self):\\n        component = OperationsComponent(\\n            text_input=\\\"hello    world\\\",\\n            operation=[{\\\"name\\\": \\\"Text Clean\\\"}],\\n            remove_extra_spaces=True,\\n        )\\n        assert component.as_message().text == \\\"hello world\\\"\\n\\n    def test_text_clean_spaces_and_empty_lines_together(self):\\n        \\\"\\\"\\\"remove_extra_spaces must preserve newlines so remove_empty_lines stays effective.\\\"\\\"\\\"\\n        component = OperationsComponent(\\n            text_input=\\\"line1  with   spaces\\\\n\\\\n\\\\nline2\\\",\\n            operation=[{\\\"name\\\": \\\"Text Clean\\\"}],\\n            remove_extra_spaces=True,\\n            remove_empty_lines=True,\\n        )\\n        assert component.as_message().text == \\\"line1 with spaces\\\\nline2\\\"\\n\\n\\nclass TestDynamicInputs:\\n    \\\"\\\"\\\"update_build_config surfaces the input matching the selected Input Type.\\n\\n    The Input Type selector drives which main input is shown; picking an\\n    operation then reveals that operation's fields. The build_config is seeded\\n    like the frontend: an ``input_type`` selector and an ``operation`` picker\\n    alongside every main and operation-specific field.\\n    \\\"\\\"\\\"\\n\\n    def _build_config(self, input_type=\\\"Text\\\"):\\n        fields = [*OperationsComponent.MAIN_INPUTS, *OperationsComponent.ALL_OPERATION_FIELDS]\\n        config = dotdict({f: {\\\"show\\\": True, \\\"required\\\": False, \\\"value\\\": None} for f in fields})\\n        config[\\\"input_type\\\"] = {\\\"show\\\": True, \\\"required\\\": False, \\\"value\\\": input_type}\\n        config[\\\"operation\\\"] = {\\\"show\\\": True, \\\"options\\\": OPERATIONS_BY_TYPE.get(input_type, []), \\\"value\\\": []}\\n        return config\\n\\n    def test_json_operation_shows_data_input(self):\\n        component = OperationsComponent()\\n        result = component.update_build_config(self._build_config(\\\"JSON\\\"), [{\\\"name\\\": \\\"Select Keys\\\"}], \\\"operation\\\")\\n        assert result[\\\"data\\\"][\\\"show\\\"] is True\\n        assert result[\\\"data\\\"][\\\"required\\\"] is True\\n        assert result[\\\"df\\\"][\\\"show\\\"] is False\\n        assert result[\\\"text_input\\\"][\\\"show\\\"] is False\\n        assert result[\\\"select_keys_input\\\"][\\\"show\\\"] is True\\n\\n    def test_table_operation_shows_df_input(self):\\n        component = OperationsComponent()\\n        result = component.update_build_config(self._build_config(\\\"Table\\\"), [{\\\"name\\\": \\\"Filter\\\"}], \\\"operation\\\")\\n        assert result[\\\"df\\\"][\\\"show\\\"] is True\\n        assert result[\\\"data\\\"][\\\"show\\\"] is False\\n        assert result[\\\"text_input\\\"][\\\"show\\\"] is False\\n        assert result[\\\"column_name\\\"][\\\"show\\\"] is True\\n        assert result[\\\"filter_value\\\"][\\\"show\\\"] is True\\n\\n    def test_text_operation_shows_text_input(self):\\n        component = OperationsComponent()\\n        result = component.update_build_config(self._build_config(\\\"Text\\\"), [{\\\"name\\\": \\\"Word Count\\\"}], \\\"operation\\\")\\n        assert result[\\\"text_input\\\"][\\\"show\\\"] is True\\n        assert result[\\\"data\\\"][\\\"show\\\"] is False\\n        assert result[\\\"df\\\"][\\\"show\\\"] is False\\n        assert result[\\\"count_words\\\"][\\\"show\\\"] is True\\n\\n    def test_combine_sets_data_is_list(self):\\n        component = OperationsComponent()\\n        config = self._build_config(\\\"JSON\\\")\\n        config[\\\"data\\\"][\\\"is_list\\\"] = False\\n        result = component.update_build_config(config, [{\\\"name\\\": \\\"Combine\\\"}], \\\"operation\\\")\\n        assert result[\\\"data\\\"][\\\"is_list\\\"] is True\\n\\n    def test_non_combine_json_op_unsets_data_is_list(self):\\n        component = OperationsComponent()\\n        config = self._build_config(\\\"JSON\\\")\\n        config[\\\"data\\\"][\\\"is_list\\\"] = True\\n        result = component.update_build_config(config, [{\\\"name\\\": \\\"Select Keys\\\"}], \\\"operation\\\")\\n        assert result[\\\"data\\\"][\\\"is_list\\\"] is False\\n\\n    def test_no_operation_shows_only_type_input(self):\\n        \\\"\\\"\\\"Clearing the operation leaves just the current input type's main input.\\\"\\\"\\\"\\n        component = OperationsComponent()\\n        result = component.update_build_config(self._build_config(\\\"Table\\\"), [], \\\"operation\\\")\\n        assert result[\\\"df\\\"][\\\"show\\\"] is True\\n        assert result[\\\"data\\\"][\\\"show\\\"] is False\\n        assert result[\\\"text_input\\\"][\\\"show\\\"] is False\\n        # All operation-specific fields hidden.\\n        assert result[\\\"select_keys_input\\\"][\\\"show\\\"] is False\\n        assert result[\\\"column_name\\\"][\\\"show\\\"] is False\\n\\n    def test_input_type_change_swaps_input_and_picker(self):\\n        \\\"\\\"\\\"Switching Input Type reveals its input, clears the operation, refilters the picker, drops stale fields.\\\"\\\"\\\"\\n        component = OperationsComponent()\\n        config = self._build_config(\\\"Text\\\")\\n        # A stale table field is visible before the switch.\\n        config[\\\"column_name\\\"][\\\"show\\\"] = True\\n        result = component.update_build_config(config, \\\"JSON\\\", \\\"input_type\\\")\\n        assert result[\\\"data\\\"][\\\"show\\\"] is True\\n        assert result[\\\"df\\\"][\\\"show\\\"] is False\\n        assert result[\\\"text_input\\\"][\\\"show\\\"] is False\\n        assert result[\\\"operation\\\"][\\\"value\\\"] == []\\n        assert {opt[\\\"name\\\"] for opt in result[\\\"operation\\\"][\\\"options\\\"]} == JSON_OPERATIONS\\n        assert result[\\\"column_name\\\"][\\\"show\\\"] is False\\n\\n    def test_switching_operation_hides_previous_fields(self):\\n        component = OperationsComponent()\\n        config = self._build_config(\\\"Table\\\")\\n        # Select a table op first.\\n        config = component.update_build_config(config, [{\\\"name\\\": \\\"Filter\\\"}], \\\"operation\\\")\\n        assert config[\\\"column_name\\\"][\\\"show\\\"] is True\\n        # Switch input type to Text and pick a text op: table fields must hide.\\n        config[\\\"input_type\\\"][\\\"value\\\"] = \\\"Text\\\"\\n        config = component.update_build_config(config, [{\\\"name\\\": \\\"Word Count\\\"}], \\\"operation\\\")\\n        assert config[\\\"column_name\\\"][\\\"show\\\"] is False\\n        assert config[\\\"filter_value\\\"][\\\"show\\\"] is False\\n        assert config[\\\"count_words\\\"][\\\"show\\\"] is True\\n        assert config[\\\"text_input\\\"][\\\"show\\\"] is True\\n\\n\\nclass TestDynamicOutputs:\\n    \\\"\\\"\\\"update_outputs picks the output type appropriate to the operation.\\\"\\\"\\\"\\n\\n    def _outputs_for(self, operation_name):\\n        component = OperationsComponent()\\n        frontend_node = {\\\"outputs\\\": []}\\n        result = component.update_outputs(frontend_node, \\\"operation\\\", [{\\\"name\\\": operation_name}])\\n        return result[\\\"outputs\\\"]\\n\\n    def test_json_operation_emits_data_output(self):\\n        outputs = self._outputs_for(\\\"Select Keys\\\")\\n        assert [o.name for o in outputs] == [\\\"data_output\\\"]\\n        assert outputs[0].method == \\\"as_data\\\"\\n\\n    def test_word_count_emits_data_output(self):\\n        outputs = self._outputs_for(\\\"Word Count\\\")\\n        assert [o.name for o in outputs] == [\\\"data_output\\\"]\\n\\n    def test_table_operation_emits_dataframe_output(self):\\n        outputs = self._outputs_for(\\\"Filter\\\")\\n        assert [o.name for o in outputs] == [\\\"dataframe_output\\\"]\\n        assert outputs[0].method == \\\"as_dataframe\\\"\\n\\n    def test_text_to_dataframe_emits_dataframe_output(self):\\n        outputs = self._outputs_for(\\\"Text to DataFrame\\\")\\n        assert [o.name for o in outputs] == [\\\"dataframe_output\\\"]\\n\\n    def test_generic_text_operation_emits_message_output(self):\\n        outputs = self._outputs_for(\\\"Case Conversion\\\")\\n        assert [o.name for o in outputs] == [\\\"message_output\\\"]\\n\\n    def test_text_join_emits_text_and_message_outputs(self):\\n        outputs = self._outputs_for(\\\"Text Join\\\")\\n        assert [o.name for o in outputs] == [\\\"text_output\\\", \\\"message_output\\\"]\\n\\n    def test_no_operation_emits_type_default_output(self):\\n        \\\"\\\"\\\"With no operation selected, the component advertises the input type's single default output.\\\"\\\"\\\"\\n        component = OperationsComponent()\\n        cases = {\\\"Text\\\": \\\"message_output\\\", \\\"JSON\\\": \\\"data_output\\\", \\\"Table\\\": \\\"dataframe_output\\\"}\\n        for input_type, expected in cases.items():\\n            frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"input_type\\\": {\\\"value\\\": input_type}}}\\n            result = component.update_outputs(frontend_node, \\\"operation\\\", [])\\n            assert [o.name for o in result[\\\"outputs\\\"]] == [expected]\\n\\n    def test_input_type_change_emits_type_default_output(self):\\n        \\\"\\\"\\\"Switching the Input Type advertises that type's single default output.\\\"\\\"\\\"\\n        component = OperationsComponent()\\n        cases = {\\\"Text\\\": \\\"message_output\\\", \\\"JSON\\\": \\\"data_output\\\", \\\"Table\\\": \\\"dataframe_output\\\"}\\n        for input_type, expected in cases.items():\\n            result = component.update_outputs({\\\"outputs\\\": []}, \\\"input_type\\\", input_type)\\n            assert [o.name for o in result[\\\"outputs\\\"]] == [expected]\\n\\n    def test_default_outputs_match_default_type(self):\\n        \\\"\\\"\\\"The class default output matches the default \\\"Text\\\" type so a fresh component is connectable.\\\"\\\"\\\"\\n        names = [o.name for o in OperationsComponent.outputs]\\n        assert names == [\\\"message_output\\\"]\\n\\n    def test_mapped_json_refresh_keeps_json_output(self):\\n        \\\"\\\"\\\"Refreshing Path Selection's \\\"JSON to Map\\\" field must not swap the JSON output for Message.\\n\\n        Real-time refreshes rebuild the frontend node with the class default\\n        (Message) output, so update_outputs has to re-derive the output from\\n        the saved operation for fields other than input_type/operation.\\n        \\\"\\\"\\\"\\n        component = OperationsComponent()\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\n                \\\"input_type\\\": {\\\"value\\\": \\\"JSON\\\"},\\n                \\\"operation\\\": {\\\"value\\\": [{\\\"name\\\": \\\"Path Selection\\\"}]},\\n            },\\n        }\\n        result = component.update_outputs(frontend_node, \\\"mapped_json_display\\\", '{\\\"a\\\": {\\\"b\\\": 1}}')\\n        assert [o.name for o in result[\\\"outputs\\\"]] == [\\\"data_output\\\"]\\n        assert result[\\\"outputs\\\"][0].method == \\\"as_data\\\"\\n\\n    def test_unrelated_field_refresh_without_operation_keeps_type_default(self):\\n        \\\"\\\"\\\"A non-operation refresh with no operation selected falls back to the input type's default output.\\\"\\\"\\\"\\n        component = OperationsComponent()\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\\"input_type\\\": {\\\"value\\\": \\\"JSON\\\"}, \\\"operation\\\": {\\\"value\\\": []}},\\n        }\\n        result = component.update_outputs(frontend_node, \\\"mapped_json_display\\\", \\\"{}\\\")\\n        assert [o.name for o in result[\\\"outputs\\\"]] == [\\\"data_output\\\"]\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    pytest.main([__file__])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_parse_dataframe_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3532c5e1578251fb7960899a0cf0ab1170407d7bccb8bb1a617033cabe8a0f22\",\"content\":\"import asyncio\\n\\nimport pandas as pd\\nimport pytest\\nfrom lfx.components.processing.parse_dataframe import ParseDataFrameComponent\\nfrom lfx.schema import DataFrame\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestParseDataFrameComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return ParseDataFrameComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\\"df\\\": DataFrame({\\\"text\\\": [\\\"Hello\\\"]}), \\\"template\\\": \\\"{text}\\\", \\\"sep\\\": \\\"\\\\n\\\"}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_successful_parse_with_default_template(self):\\n        # Create test data\\n        test_df = DataFrame({\\\"text\\\": [\\\"Hello\\\", \\\"World\\\", \\\"Test\\\"]})\\n\\n        component = ParseDataFrameComponent(df=test_df, template=\\\"{text}\\\", sep=\\\"\\\\n\\\")\\n\\n        # Run the parse process\\n        result = component.parse_data()\\n\\n        # Verify the results\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Hello\\\\nWorld\\\\nTest\\\"\\n        assert component.status == \\\"Hello\\\\nWorld\\\\nTest\\\"\\n\\n    def test_parse_with_custom_template(self):\\n        test_df = DataFrame({\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"age\\\": [30, 25]})\\n\\n        component = ParseDataFrameComponent(df=test_df, template=\\\"Name: {name}, Age: {age}\\\", sep=\\\" | \\\")\\n\\n        result = component.parse_data()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Name: John, Age: 30 | Name: Jane, Age: 25\\\"\\n\\n    def test_parse_with_custom_separator(self):\\n        test_df = DataFrame({\\\"text\\\": [\\\"Hello\\\", \\\"World\\\"]})\\n\\n        component = ParseDataFrameComponent(df=test_df, template=\\\"{text}\\\", sep=\\\" --- \\\")\\n\\n        result = component.parse_data()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Hello --- World\\\"\\n\\n    def test_empty_dataframe(self):\\n        component = ParseDataFrameComponent(df=DataFrame({\\\"text\\\": []}), template=\\\"{text}\\\", sep=\\\"\\\\n\\\")\\n\\n        result = component.parse_data()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"\\\"\\n\\n    def test_invalid_template_keys(self):\\n        component = ParseDataFrameComponent(\\n            df=DataFrame({\\\"text\\\": [\\\"Hello\\\"]}), template=\\\"{nonexistent_column}\\\", sep=\\\"\\\\n\\\"\\n        )\\n\\n        with pytest.raises(KeyError):\\n            component.parse_data()\\n\\n    def test_multiple_column_template(self):\\n        test_df = DataFrame({\\\"col1\\\": [\\\"A\\\", \\\"B\\\"], \\\"col2\\\": [1, 2], \\\"col3\\\": [\\\"X\\\", \\\"Y\\\"]})\\n\\n        component = ParseDataFrameComponent(df=test_df, template=\\\"{col1}-{col2}-{col3}\\\", sep=\\\", \\\")\\n\\n        result = component.parse_data()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"A-1-X, B-2-Y\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_async_invocation(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Verify that ParseDataFrameComponent can be called in an async context.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        # Use asyncio.to_thread to invoke the parse_data method in a thread pool\\n        result = await asyncio.to_thread(component.parse_data)\\n        assert isinstance(result, Message)\\n\\n    def test_various_data_types(self, component_class):\\n        \\\"\\\"\\\"Test that the component correctly formats differing data types.\\\"\\\"\\\"\\n        test_dataframe = DataFrame(\\n            {\\n                \\\"string_col\\\": [\\\"A\\\", \\\"B\\\"],\\n                \\\"int_col\\\": [1, 2],\\n                \\\"bool_col\\\": [True, False],\\n                \\\"time_col\\\": pd.to_datetime([\\\"2023-01-01\\\", \\\"2023-01-02\\\"]),\\n            }\\n        )\\n        template = \\\"{string_col}-{int_col}-{bool_col}-{time_col}\\\"\\n        component = component_class(df=test_dataframe, template=template, sep=\\\" | \\\")\\n        result = component.parse_data()\\n        assert isinstance(result, Message)\\n        # Just check that all columns are present in the text\\n        assert \\\"A-1-True-2023-01-01\\\" in result.text\\n\\n    def test_nan_values(self, component_class):\\n        \\\"\\\"\\\"Test how the component handles missing/NaN values in the DataFrame.\\\"\\\"\\\"\\n        test_dataframe = DataFrame(\\n            {\\n                \\\"col1\\\": [\\\"Hello\\\", None],\\n                \\\"col2\\\": [10, float(\\\"nan\\\")],\\n            }\\n        )\\n        template = \\\"{col1}-{col2}\\\"\\n        component = component_class(df=test_dataframe, template=template, sep=\\\"\\\\n\\\")\\n        result = component.parse_data()\\n        # Expect None or NaN to be converted to the string \\\"None\\\" or \\\"nan\\\"\\n        # depending on Python's behavior\\n        assert isinstance(result, Message)\\n        # The exact representation can depend on how pandas handles None/NaN.\\n        # Typically, None -> 'None' and NaN -> 'nan'.\\n        # You can refine these assertions if you have a custom conversion.\\n        assert \\\"Hello-10\\\" in result.text\\n\\n    def test_large_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test performance and correctness on a relatively large DataFrame.\\\"\\\"\\\"\\n        data = {\\n            \\\"col\\\": [f\\\"Row{i}\\\" for i in range(10000)],  # 10k rows\\n        }\\n        large_dataframe = DataFrame(data)\\n        component = component_class(df=large_dataframe, template=\\\"{col}\\\", sep=\\\", \\\")\\n        result = component.parse_data()\\n        assert isinstance(result, Message)\\n        # Check the length of the result isn't zero, ensuring it didn't fail\\n        assert len(result.text) > 0\\n        # Optionally, you can assert the result includes a substring from the middle\\n        assert \\\"Row5000\\\" in result.text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_parser_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"452fbb5135be94b56644e9ebbfd69880faddf3b398f64a527432e5b7ef019714\",\"content\":\"import re\\n\\nimport pytest\\nfrom lfx.components.processing.parser import ParserComponent\\nfrom lfx.schema import Data, DataFrame\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestParserComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return ParserComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"input_data\\\": DataFrame({\\\"Name\\\": [\\\"John\\\"], \\\"Age\\\": [30], \\\"Country\\\": [\\\"USA\\\"]}),\\n            \\\"pattern\\\": \\\"Name: {Name}, Age: {Age}, Country: {Country}\\\",\\n            \\\"sep\\\": \\\"\\\\n\\\",\\n            \\\"stringify\\\": False,\\n            \\\"clean_data\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_parse_dataframe(self, component_class, default_kwargs):\\n        # Arrange\\n        component = component_class(**default_kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Name: John, Age: 30, Country: USA\\\"\\n\\n    def test_parse_data_object(self, component_class):\\n        # Arrange\\n        data = Data(text=\\\"Hello World\\\")\\n        kwargs = {\\n            \\\"input_data\\\": data,\\n            \\\"pattern\\\": \\\"text: {text}\\\",\\n            \\\"sep\\\": \\\"\\\\n\\\",\\n            \\\"stringify\\\": False,\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"text: Hello World\\\"\\n\\n    def test_parse_data_list(self, component_class):\\n        data = [\\n            Data(data={\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}),\\n            Data(data={\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25}),\\n        ]\\n        component = component_class(\\n            input_data=data,\\n            pattern=\\\"{name} is {age} years old\\\",\\n            sep=\\\" | \\\",\\n            mode=\\\"Parser\\\",\\n        )\\n\\n        result = component.parse_combined_text()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"John is 30 years old | Jane is 25 years old\\\"\\n\\n    def test_parse_data_list_uses_each_item_default_value(self, component_class):\\n        data = [\\n            Data(data={\\\"name\\\": \\\"John\\\"}, default_value=\\\"unknown\\\"),\\n            Data(data={\\\"name\\\": \\\"Jane\\\"}, default_value=\\\"not provided\\\"),\\n        ]\\n        component = component_class(\\n            input_data=data,\\n            pattern=\\\"{name}: {role}\\\",\\n            sep=\\\"\\\\n\\\",\\n            mode=\\\"Parser\\\",\\n        )\\n\\n        result = component.parse_combined_text()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"John: unknown\\\\nJane: not provided\\\"\\n\\n    def test_stringify_dataframe(self, component_class):\\n        # Arrange\\n        data_frame = DataFrame({\\\"Name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"Age\\\": [30, 25]})\\n        kwargs = {\\n            \\\"input_data\\\": data_frame,\\n            \\\"mode\\\": \\\"Stringify\\\",\\n            \\\"clean_data\\\": False,\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        assert \\\"| Name   |   Age |\\\" in result.text\\n        assert \\\"| John   |    30 |\\\" in result.text\\n        assert \\\"| Jane   |    25 |\\\" in result.text\\n\\n    def test_stringify_data_object(self, component_class):\\n        # Arrange\\n        data = Data(text=\\\"Hello\\\\nWorld\\\\nMultiline\\\\nText\\\")\\n        kwargs = {\\n            \\\"input_data\\\": data,\\n            \\\"stringify\\\": True,\\n            \\\"clean_data\\\": True,\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        assert \\\"Hello\\\" in result.text\\n        assert \\\"World\\\" in result.text\\n        assert \\\"Multiline\\\" in result.text\\n        assert \\\"Text\\\" in result.text\\n\\n    def test_stringify_message_object(self, component_class):\\n        # Arrange\\n        message = Message(text=\\\"Test message content\\\")\\n        kwargs = {\\n            \\\"input_data\\\": message,\\n            \\\"mode\\\": \\\"Stringify\\\",\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Test message content\\\"\\n\\n    def test_stringify_list_without_clean_data(self, component_class):\\n        component = component_class(\\n            input_data=[Message(text=\\\"First\\\"), Message(text=\\\"Second\\\")],\\n            mode=\\\"Stringify\\\",\\n        )\\n\\n        result = component.parse_combined_text()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"First\\\\nSecond\\\"\\n\\n    @pytest.mark.parametrize((\\\"input_data\\\", \\\"expected\\\"), [(\\\"\\\", \\\"\\\"), (0, \\\"0\\\")])\\n    def test_stringify_preserves_falsy_scalar_input(self, component_class, input_data, expected):\\n        component = component_class(input_data=input_data, mode=\\\"Stringify\\\")\\n\\n        result = component.parse_combined_text()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == expected\\n\\n    def test_clean_data_with_stringify(self, component_class):\\n        # Arrange\\n        data_frame = DataFrame(\\n            {\\n                \\\"Name\\\": [\\\"John\\\", \\\"Jane\\\\n\\\", \\\"\\\\nBob\\\"],\\n                \\\"Age\\\": [30, None, 25],\\n                \\\"Notes\\\": [\\\"Good\\\\n\\\\nPerson\\\", \\\"\\\", \\\"Nice\\\\n\\\"],\\n            }\\n        )\\n        kwargs = {\\n            \\\"input_data\\\": data_frame,\\n            \\\"mode\\\": \\\"Stringify\\\",\\n            \\\"clean_data\\\": True,\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        # Check for table structure\\n        assert \\\"| Name\\\" in result.text\\n        assert \\\"|   Age\\\" in result.text\\n        assert \\\"| Notes\\\" in result.text\\n        # Check for cleaned data\\n        assert \\\"| John\\\" in result.text\\n        assert \\\"| Jane\\\" in result.text\\n        assert \\\"| Bob\\\" in result.text\\n        assert \\\"| Good\\\" in result.text\\n        assert \\\"| Person\\\" in result.text\\n        assert \\\"| Nice\\\" in result.text\\n        # Verify data is cleaned\\n        assert \\\"Jane\\\\n\\\" not in result.text\\n        assert \\\"\\\\nBob\\\" not in result.text\\n        assert \\\"Good\\\\n\\\\nPerson\\\" not in result.text\\n        assert \\\"Nice\\\\n\\\" not in result.text\\n\\n    def test_invalid_input_type(self, component_class):\\n        # Arrange\\n        kwargs = {\\n            \\\"input_data\\\": 123,  # Invalid input type\\n            \\\"pattern\\\": \\\"{value}\\\",\\n            \\\"sep\\\": \\\"\\\\n\\\",\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act & Assert\\n        with pytest.raises(\\n            ValueError,\\n            match=re.escape(\\\"Unsupported input type: <class 'int'>. Expected DataFrame, Data, or list[Data].\\\"),\\n        ):\\n            component.parse_combined_text()\\n\\n    def test_none_input(self, component_class):\\n        # Arrange\\n        kwargs = {\\n            \\\"input_data\\\": None,\\n            \\\"pattern\\\": \\\"{value}\\\",\\n            \\\"sep\\\": \\\"\\\\n\\\",\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act & Assert\\n        with pytest.raises(\\n            ValueError,\\n            match=re.escape(\\\"Unsupported input type: <class 'NoneType'>. Expected DataFrame, Data, or list[Data].\\\"),\\n        ):\\n            component.parse_combined_text()\\n\\n    def test_invalid_template(self, component_class):\\n        # Arrange\\n        data_frame = DataFrame({\\\"Name\\\": [\\\"John\\\"]})\\n        kwargs = {\\n            \\\"input_data\\\": data_frame,\\n            \\\"pattern\\\": \\\"{InvalidColumn}\\\",  # Invalid column name\\n            \\\"sep\\\": \\\"\\\\n\\\",\\n            \\\"stringify\\\": False,\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act & Assert\\n        with pytest.raises(KeyError):\\n            component.parse_combined_text()\\n\\n    def test_multiple_rows_with_custom_separator(self, component_class):\\n        # Arrange\\n        data_frame = DataFrame(\\n            {\\n                \\\"Name\\\": [\\\"John\\\", \\\"Jane\\\", \\\"Bob\\\"],\\n                \\\"Age\\\": [30, 25, 35],\\n            }\\n        )\\n        kwargs = {\\n            \\\"input_data\\\": data_frame,\\n            \\\"pattern\\\": \\\"{Name} is {Age} years old\\\",\\n            \\\"sep\\\": \\\" | \\\",\\n            \\\"mode\\\": \\\"Parser\\\",\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert\\n        assert isinstance(result, Message)\\n        expected = \\\"John is 30 years old | Jane is 25 years old | Bob is 35 years old\\\"\\n        assert result.text == expected\\n\\n    def test_empty_data_with_template(self, component_class):\\n        # Arrange - Data with empty data dict but template expects keys\\n        data = Data(text_key=\\\"text\\\", data={}, default_value=\\\"\\\")\\n        kwargs = {\\n            \\\"input_data\\\": data,\\n            \\\"pattern\\\": \\\"Text: {text}\\\",\\n            \\\"sep\\\": \\\"\\\\n\\\",\\n            \\\"mode\\\": \\\"Parser\\\",\\n        }\\n        component = component_class(**kwargs)\\n\\n        # Act\\n        result = component.parse_combined_text()\\n\\n        # Assert - Should use default_value when key is missing\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Text: \\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_regex_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"96e3c9d6bb270f0dbb6cfc71e795259a10fb6300518e087be2705c2606adda33\",\"content\":\"import pytest\\nfrom lfx.components.processing.regex import RegexExtractorComponent\\nfrom lfx.schema import Data\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestRegexExtractorComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return RegexExtractorComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"input_text\\\": \\\"Contact us at test@example.com\\\",\\n            \\\"pattern\\\": r\\\"\\\\b\\\\w+@\\\\w+\\\\.\\\\w+\\\\b\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_successful_regex_extraction(self):\\n        # Test with email pattern\\n        component = RegexExtractorComponent(\\n            input_text=\\\"Contact us at test@example.com or support@test.com\\\", pattern=r\\\"\\\\b\\\\w+@\\\\w+\\\\.\\\\w+\\\\b\\\"\\n        )\\n\\n        result = component.extract_matches()\\n        assert isinstance(result, list)\\n        assert all(isinstance(item, Data) for item in result)\\n        assert len(result) == 2\\n        assert result[0].data[\\\"match\\\"] == \\\"test@example.com\\\"\\n        assert result[1].data[\\\"match\\\"] == \\\"support@test.com\\\"\\n\\n    def test_no_matches_found(self):\\n        # Test with pattern that won't match\\n        component = RegexExtractorComponent(input_text=\\\"No email addresses here\\\", pattern=r\\\"\\\\b\\\\w+@\\\\w+\\\\.\\\\w+\\\\b\\\")\\n\\n        result = component.extract_matches()\\n        assert isinstance(result, list)\\n        assert len(result) == 0  # The implementation returns an empty list when no matches are found\\n\\n    def test_invalid_regex_pattern(self):\\n        # Test with invalid regex pattern\\n        component = RegexExtractorComponent(\\n            input_text=\\\"Some text\\\",\\n            pattern=\\\"[\\\",  # Invalid regex pattern\\n        )\\n\\n        result = component.extract_matches()\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert \\\"error\\\" in result[0].data\\n        assert \\\"Invalid regex pattern\\\" in result[0].data[\\\"error\\\"]\\n\\n    def test_empty_input_text(self):\\n        # Test with empty input\\n        component = RegexExtractorComponent(input_text=\\\"\\\", pattern=r\\\"\\\\b\\\\w+@\\\\w+\\\\.\\\\w+\\\\b\\\")\\n\\n        result = component.extract_matches()\\n        assert isinstance(result, list)\\n        assert len(result) == 0  # The implementation returns an empty list when input is empty\\n\\n    def test_get_matches_text_output(self):\\n        # Test the text output method\\n        component = RegexExtractorComponent(input_text=\\\"Contact: test@example.com\\\", pattern=r\\\"\\\\b\\\\w+@\\\\w+\\\\.\\\\w+\\\\b\\\")\\n\\n        result = component.get_matches_text()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"test@example.com\\\"\\n\\n    def test_get_matches_text_no_matches(self):\\n        # Test text output with no matches\\n        component = RegexExtractorComponent(input_text=\\\"No email addresses\\\", pattern=r\\\"\\\\b\\\\w+@\\\\w+\\\\.\\\\w+\\\\b\\\")\\n\\n        result = component.get_matches_text()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"No matches found\\\"\\n\\n    def test_get_matches_text_invalid_pattern(self):\\n        # Test text output with invalid pattern\\n        component = RegexExtractorComponent(\\n            input_text=\\\"Some text\\\",\\n            pattern=\\\"[\\\",  # Invalid regex pattern\\n        )\\n\\n        result = component.get_matches_text()\\n        assert isinstance(result, Message)\\n        assert \\\"Invalid regex pattern\\\" in result.text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_save_file_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1d8ee68b4a70e651e371819c35a880abd97f601701dc7ec9a43fe071f852c8a2\",\"content\":\"import contextlib\\nimport json\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pandas as pd\\nimport pytest\\nfrom lfx.components.files_and_knowledge.save_file import SaveToFileComponent\\nfrom lfx.schema import Data, DataFrame, Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestSaveToFileComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture(scope=\\\"class\\\", autouse=True)\\n    def cleanup_test_files(self):\\n        \\\"\\\"\\\"Clean up test files after all tests in the class complete.\\\"\\\"\\\"\\n        yield\\n        # Clean up test files created during tests\\n        test_files = [\\\"test_data.json\\\", \\\"test_message.txt\\\", \\\"test_output.csv\\\", \\\"test_page.html\\\", \\\"test_s3_output.txt\\\"]\\n        for filename in test_files:\\n            filepath = Path(filename)\\n            if filepath.exists():\\n                with contextlib.suppress(Exception):\\n                    filepath.unlink()\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return SaveToFileComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        sample_df = DataFrame([{\\\"col1\\\": 1, \\\"col2\\\": \\\"a\\\"}, {\\\"col1\\\": 2, \\\"col2\\\": \\\"b\\\"}])\\n        return {\\\"input\\\": sample_df, \\\"file_name\\\": \\\"test_output\\\", \\\"file_format\\\": \\\"csv\\\"}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        return []  # New component\\n\\n    def test_basic_setup(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test basic component initialization.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        assert component.file_name == \\\"test_output\\\"\\n        assert component.file_format == \\\"csv\\\"\\n\\n    def test_aws_fallback_inputs_are_optional(self, component_class):\\n        \\\"\\\"\\\"Allow the canvas to defer AWS fallback-backed inputs to runtime.\\\"\\\"\\\"\\n        inputs = {component_input.name: component_input for component_input in component_class.inputs}\\n\\n        for input_name in (\\\"aws_access_key_id\\\", \\\"aws_secret_access_key\\\", \\\"bucket_name\\\"):\\n            assert inputs[input_name].required is False\\n\\n    @pytest.mark.asyncio\\n    async def test_save_to_aws_uses_environment_and_settings_fallbacks(self, component_class, monkeypatch):\\n        \\\"\\\"\\\"Use resolved AWS values when the component credential inputs are empty.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"AWS_ACCESS_KEY_ID\\\", \\\"environment-access-key\\\")\\n        monkeypatch.setenv(\\\"AWS_SECRET_ACCESS_KEY\\\", \\\"environment-secret-key\\\")\\n        monkeypatch.setenv(\\\"AWS_SESSION_TOKEN\\\", \\\"environment-session-token\\\")\\n        monkeypatch.setenv(\\\"AWS_DEFAULT_REGION\\\", \\\"us-west-2\\\")\\n\\n        settings_service = MagicMock()\\n        settings_service.settings.object_storage_bucket_name = \\\"settings-bucket\\\"\\n        mock_s3_client = MagicMock()\\n\\n        component = component_class()\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": Message(text=\\\"AWS fallback content\\\"),\\n                \\\"file_name\\\": \\\"aws_report\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"AWS\\\"}],\\n                \\\"aws_format\\\": \\\"txt\\\",\\n                \\\"aws_access_key_id\\\": \\\"\\\",\\n                \\\"aws_secret_access_key\\\": \\\"\\\",\\n                \\\"bucket_name\\\": \\\"\\\",\\n                \\\"aws_region\\\": \\\"\\\",\\n                \\\"s3_prefix\\\": \\\"reports\\\",\\n            }\\n        )\\n\\n        with (\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.save_file.get_settings_service\\\",\\n                return_value=settings_service,\\n            ),\\n            patch(\\\"boto3.client\\\", return_value=mock_s3_client) as mock_boto3_client,\\n        ):\\n            result = await component.save_to_file()\\n\\n        mock_boto3_client.assert_called_once_with(\\n            \\\"s3\\\",\\n            aws_access_key_id=\\\"environment-access-key\\\",\\n            aws_secret_access_key=\\\"environment-secret-key\\\",  # noqa: S106  # pragma: allowlist secret\\n            aws_session_token=\\\"environment-session-token\\\",  # noqa: S106  # pragma: allowlist secret\\n            region_name=\\\"us-west-2\\\",\\n        )\\n        upload_args = mock_s3_client.upload_file.call_args.args\\n        assert upload_args[1:] == (\\\"settings-bucket\\\", \\\"reports/aws_report.txt\\\")\\n        assert result.text == \\\"File successfully uploaded to s3://settings-bucket/reports/aws_report.txt\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_save_to_aws_does_not_mix_environment_token_with_component_credentials(\\n        self, component_class, monkeypatch\\n    ):\\n        \\\"\\\"\\\"Keep an environment session token out of component-supplied credentials.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"AWS_SESSION_TOKEN\\\", \\\"environment-session-token\\\")\\n        mock_s3_client = MagicMock()\\n\\n        component = component_class()\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": Message(text=\\\"AWS component credential content\\\"),\\n                \\\"file_name\\\": \\\"aws_report\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"AWS\\\"}],\\n                \\\"aws_format\\\": \\\"txt\\\",\\n                \\\"aws_access_key_id\\\": \\\"component-access-key\\\",\\n                \\\"aws_secret_access_key\\\": \\\"component-secret-key\\\",  # pragma: allowlist secret\\n                \\\"bucket_name\\\": \\\"component-bucket\\\",\\n                \\\"aws_region\\\": \\\"us-west-2\\\",\\n                \\\"s3_prefix\\\": \\\"reports\\\",\\n            }\\n        )\\n\\n        with patch(\\\"boto3.client\\\", return_value=mock_s3_client) as mock_boto3_client:\\n            await component.save_to_file()\\n\\n        mock_boto3_client.assert_called_once_with(\\n            \\\"s3\\\",\\n            aws_access_key_id=\\\"component-access-key\\\",\\n            aws_secret_access_key=\\\"component-secret-key\\\",  # noqa: S106  # pragma: allowlist secret\\n            region_name=\\\"us-west-2\\\",\\n        )\\n\\n    def test_get_input_type_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test input type detection for DataFrame.\\\"\\\"\\\"\\n        component = component_class()\\n        df = DataFrame([{\\\"a\\\": 1}])\\n        component.set_attributes({\\\"input\\\": df, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"csv\\\"})\\n        assert component._get_input_type() == \\\"DataFrame\\\"\\n\\n    def test_get_input_type_data(self, component_class):\\n        \\\"\\\"\\\"Test input type detection for Data.\\\"\\\"\\\"\\n        component = component_class()\\n        data = Data(data={\\\"a\\\": 1})\\n        component.set_attributes({\\\"input\\\": data, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"json\\\"})\\n        assert component._get_input_type() == \\\"Data\\\"\\n\\n    def test_get_input_type_message(self, component_class):\\n        \\\"\\\"\\\"Test input type detection for Message.\\\"\\\"\\\"\\n        component = component_class()\\n        message = Message(text=\\\"test\\\")\\n        component.set_attributes({\\\"input\\\": message, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"txt\\\"})\\n        assert component._get_input_type() == \\\"Message\\\"\\n\\n    def test_get_default_format_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test default format for DataFrame is csv.\\\"\\\"\\\"\\n        component = component_class()\\n        df = DataFrame([{\\\"a\\\": 1}])\\n        component.set_attributes({\\\"input\\\": df, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"\\\"})\\n        assert component._get_default_format() == \\\"csv\\\"\\n\\n    def test_get_default_format_data(self, component_class):\\n        \\\"\\\"\\\"Test default format for Data is json.\\\"\\\"\\\"\\n        component = component_class()\\n        data = Data(data={\\\"a\\\": 1})\\n        component.set_attributes({\\\"input\\\": data, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"\\\"})\\n        assert component._get_default_format() == \\\"json\\\"\\n\\n    def test_get_default_format_message(self, component_class):\\n        \\\"\\\"\\\"Test default format for Message is json.\\\"\\\"\\\"\\n        component = component_class()\\n        message = Message(text=\\\"test\\\")\\n        component.set_attributes({\\\"input\\\": message, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"\\\"})\\n        assert component._get_default_format() == \\\"json\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_save_dataframe_to_csv(self, component_class):\\n        \\\"\\\"\\\"Test saving DataFrame to CSV format - only mock upload.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        df = DataFrame([{\\\"col1\\\": 1, \\\"col2\\\": \\\"a\\\"}, {\\\"col1\\\": 2, \\\"col2\\\": \\\"b\\\"}])\\n        component.set_attributes(\\n            {\\\"input\\\": df, \\\"file_name\\\": \\\"test_output\\\", \\\"local_format\\\": \\\"csv\\\", \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}]}\\n        )\\n\\n        # Mock only the database and upload functions - let file operations run normally\\n        with (\\n            patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n            mock_upload.return_value = MagicMock(path=\\\"test_output.csv\\\", provider=\\\"s3\\\")\\n\\n            # Execute - real temp file creation, real DataFrame.to_csv(), real cleanup\\n            result = await component.save_to_file()\\n\\n            # Verify\\n            assert \\\"saved successfully\\\" in result.text\\n            assert \\\"test_output.csv\\\" in result.text\\n\\n            # Verify upload was called with a real file\\n            mock_upload.assert_called_once()\\n            upload_file = mock_upload.call_args[1][\\\"file\\\"]\\n            assert upload_file.filename == \\\"test_output.csv\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_save_data_to_json(self, component_class):\\n        \\\"\\\"\\\"Test saving Data to JSON format - only mock upload.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        data = Data(data={\\\"col1\\\": \\\"value1\\\", \\\"col2\\\": \\\"value2\\\"})\\n        component.set_attributes(\\n            {\\\"input\\\": data, \\\"file_name\\\": \\\"test_data\\\", \\\"local_format\\\": \\\"json\\\", \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}]}\\n        )\\n\\n        # Mock only the database and upload functions - let file operations run normally\\n        with (\\n            patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n            mock_upload.return_value = MagicMock(path=\\\"test_data.json\\\", provider=\\\"s3\\\")\\n\\n            result = await component.save_to_file()\\n\\n            assert \\\"saved successfully\\\" in result.text\\n            assert \\\"test_data.json\\\" in result.text\\n\\n    @pytest.mark.asyncio\\n    async def test_save_message_to_txt(self, component_class):\\n        \\\"\\\"\\\"Test saving Message to txt format - only mock upload.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        message = Message(text=\\\"This is a test message\\\")\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": message,\\n                \\\"file_name\\\": \\\"test_message\\\",\\n                \\\"local_format\\\": \\\"txt\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n\\n        # Mock only the database and upload functions - let file operations run normally\\n        with (\\n            patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n            mock_upload.return_value = MagicMock(path=\\\"test_message.txt\\\", provider=\\\"s3\\\")\\n\\n            result = await component.save_to_file()\\n\\n            assert \\\"saved successfully\\\" in result.text\\n            assert \\\"test_message.txt\\\" in result.text\\n\\n    @pytest.mark.asyncio\\n    async def test_save_local_mode_with_s3_backend_cleans_staging_and_reports_storage_path(\\n        self, component_class, tmp_path\\n    ):\\n        \\\"\\\"\\\"Remote (S3) backend: Local mode deletes the staging file and reports the storage path.\\n\\n        This guards the fix for the leak where Local mode left a redundant copy in\\n        cwd and surfaced a misleading local path when the backend was S3.\\n        \\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        message = Message(text=\\\"This should end up only in S3\\\")\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": message,\\n                \\\"file_name\\\": \\\"test_s3_output\\\",\\n                \\\"local_format\\\": \\\"txt\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n\\n        # upload_user_file returns the durable storage location + provider\\n        upload_response = MagicMock()\\n        upload_response.path = \\\"files/user-uuid/test_s3_output.txt\\\"\\n        upload_response.provider = \\\"s3\\\"\\n\\n        # Force the storage backend to look remote (S3) without restricting paths\\n        settings_mock = MagicMock()\\n        settings_mock.storage_type = \\\"s3\\\"\\n        settings_mock.restrict_local_file_access = False\\n        settings_mock.config_dir = str(tmp_path)\\n        settings_service_mock = MagicMock()\\n        settings_service_mock.settings = settings_mock\\n\\n        with (\\n            patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.save_file.get_settings_service\\\",\\n                return_value=settings_service_mock,\\n            ),\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n            mock_upload.return_value = upload_response\\n\\n            result = await component.save_to_file()\\n\\n        # Message reports the durable storage destination + provider, not a local path\\n        assert \\\"files/user-uuid/test_s3_output.txt\\\" in result.text\\n        assert \\\"S3\\\" in result.text\\n        assert str(tmp_path) not in result.text\\n        # The local staging file was cleaned up\\n        assert not (Path.cwd() / \\\"test_s3_output.txt\\\").exists()\\n\\n    @pytest.mark.asyncio\\n    async def test_append_mode_remote_backend_accumulates_across_calls(self, component_class, tmp_path):\\n        \\\"\\\"\\\"append_mode + remote (S3) backend keeps accumulating, not resetting to overwrite.\\n\\n        Guards against the staging cleanup deleting the local accumulator that append\\n        relies on (should_append hinges on the file persisting across calls). Without\\n        the append exception, the second call would silently overwrite.\\n        \\\"\\\"\\\"\\n        file_name = \\\"test_append_remote\\\"\\n        staging = Path.cwd() / f\\\"{file_name}.txt\\\"\\n        if staging.exists():\\n            staging.unlink()\\n\\n        settings_mock = MagicMock()\\n        settings_mock.storage_type = \\\"s3\\\"\\n        settings_mock.restrict_local_file_access = False\\n        settings_mock.config_dir = str(tmp_path)\\n        settings_service_mock = MagicMock()\\n        settings_service_mock.settings = settings_mock\\n\\n        upload_response = MagicMock()\\n        upload_response.path = f\\\"files/uid/{file_name}.txt\\\"\\n        upload_response.provider = \\\"s3\\\"\\n\\n        def make_component(text):\\n            component = component_class(_user_id=str(uuid4()))\\n            component.set_attributes(\\n                {\\n                    \\\"input\\\": Message(text=text),\\n                    \\\"file_name\\\": file_name,\\n                    \\\"local_format\\\": \\\"txt\\\",\\n                    \\\"append_mode\\\": True,\\n                    \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n                }\\n            )\\n            return component\\n\\n        try:\\n            with (\\n                patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n                patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n                patch(\\n                    \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n                ) as mock_get_user,\\n                patch(\\n                    \\\"lfx.components.files_and_knowledge.save_file.get_settings_service\\\",\\n                    return_value=settings_service_mock,\\n                ),\\n            ):\\n                mock_db = AsyncMock()\\n                mock_session.return_value.__aenter__.return_value = mock_db\\n                mock_get_user.return_value = MagicMock()\\n                mock_upload.return_value = upload_response\\n\\n                await make_component(\\\"line one\\\").save_to_file()\\n                # Staging file must survive so the next call can append to it\\n                assert staging.exists()\\n                await make_component(\\\"line two\\\").save_to_file()\\n\\n            # Content accumulated across both calls \u2014 not overwritten\\n            assert staging.read_text(encoding=\\\"utf-8\\\") == \\\"line one\\\\nline two\\\"\\n        finally:\\n            if staging.exists():\\n                staging.unlink()\\n\\n    @pytest.mark.asyncio\\n    async def test_save_aws_mode_namespaces_key_by_user_id(self, component_class):\\n        \\\"\\\"\\\"AWS mode namespaces the S3 key by user_id so multi-user runs don't collide.\\n\\n        Layout must be {s3_prefix}/{user_id}/{file_name}.{ext} \u2014 otherwise every\\n        user writing the same file_name overwrites the same key.\\n        \\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        component = component_class(_user_id=user_id)\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": Message(text=\\\"hello aws\\\"),\\n                \\\"file_name\\\": \\\"report\\\",\\n                \\\"aws_format\\\": \\\"txt\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"AWS\\\"}],\\n                \\\"aws_access_key_id\\\": \\\"test-access-key\\\",  # pragma: allowlist secret\\n                \\\"aws_secret_access_key\\\": \\\"test-secret-key\\\",  # pragma: allowlist secret\\n                \\\"bucket_name\\\": \\\"my-bucket\\\",\\n                \\\"aws_region\\\": \\\"us-east-1\\\",\\n                \\\"s3_prefix\\\": \\\"files\\\",\\n            }\\n        )\\n\\n        mock_s3 = MagicMock()\\n        with (\\n            patch(\\\"boto3.client\\\", return_value=mock_s3),\\n            patch(\\\"lfx.base.data.cloud_storage_utils.validate_aws_credentials\\\"),\\n        ):\\n            result = await component.save_to_file()\\n\\n        # upload_file(temp_path, bucket, key) \u2014 third positional arg is the S3 key\\n        mock_s3.upload_file.assert_called_once()\\n        key = mock_s3.upload_file.call_args[0][2]\\n        assert key == f\\\"files/{user_id}/report.txt\\\"\\n        assert \\\"my-bucket\\\" in result.text\\n\\n    @pytest.mark.asyncio\\n    async def test_save_message_to_html(self, component_class):\\n        \\\"\\\"\\\"Test saving Message to html format.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        html_content = \\\"<html><body><h1>Test</h1></body></html>\\\"\\n        message = Message(text=html_content)\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": message,\\n                \\\"file_name\\\": \\\"test_page\\\",\\n                \\\"local_format\\\": \\\"html\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n\\n        with (\\n            patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n            mock_upload.return_value = MagicMock(path=\\\"test_page.html\\\", provider=\\\"s3\\\")\\n\\n            result = await component.save_to_file()\\n\\n            assert \\\"saved successfully\\\" in result.text\\n            assert \\\"test_page.html\\\" in result.text\\n\\n            # Verify upload was called with a real file containing the HTML\\n            mock_upload.assert_called_once()\\n            upload_file = mock_upload.call_args[1][\\\"file\\\"]\\n            assert upload_file.filename == \\\"test_page.html\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_cleanup_on_error(self, component_class):\\n        \\\"\\\"\\\"Test that temp file is cleaned up even when upload fails.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        df = DataFrame([{\\\"col1\\\": 1}])\\n        component.set_attributes(\\n            {\\\"input\\\": df, \\\"file_name\\\": \\\"test_output\\\", \\\"local_format\\\": \\\"csv\\\", \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}]}\\n        )\\n\\n        # Mock database and upload functions - let file operations run normally\\n        with (\\n            patch(\\n                \\\"langflow.api.v2.files.upload_user_file\\\",\\n                new_callable=AsyncMock,\\n                side_effect=Exception(\\\"Upload failed\\\"),\\n            ),\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n\\n            # Capture temp file path before it gets cleaned up\\n            import tempfile\\n\\n            temp_dir = Path(tempfile.gettempdir())\\n            temp_files_before = set(temp_dir.glob(\\\"test_output_*.csv\\\"))\\n\\n            with pytest.raises(Exception, match=\\\"Upload failed\\\"):\\n                await component.save_to_file()\\n\\n            # Verify temp file was cleaned up\\n            temp_files_after = set(temp_dir.glob(\\\"test_output_*.csv\\\"))\\n            # New temp files should have been created and cleaned up\\n            assert temp_files_after == temp_files_before\\n\\n    @pytest.mark.asyncio\\n    async def test_invalid_file_format_for_message(self, component_class):\\n        \\\"\\\"\\\"Test that invalid file format raises ValueError.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        message = Message(text=\\\"test\\\")\\n        component.set_attributes(\\n            {\\\"input\\\": message, \\\"file_name\\\": \\\"test\\\", \\\"local_format\\\": \\\"csv\\\", \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}]}\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid file format\\\"):\\n            await component.save_to_file()\\n\\n    @pytest.mark.asyncio\\n    async def test_invalid_file_format_for_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test that invalid file format raises ValueError for DataFrame.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        df = DataFrame([{\\\"a\\\": 1}])\\n        component.set_attributes(\\n            {\\\"input\\\": df, \\\"file_name\\\": \\\"test\\\", \\\"local_format\\\": \\\"txt\\\", \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}]}\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid file format\\\"):\\n            await component.save_to_file()\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_file_name(self, component_class):\\n        \\\"\\\"\\\"Test that missing file name raises ValueError.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        df = DataFrame([{\\\"a\\\": 1}])\\n        component.set_attributes(\\n            {\\\"input\\\": df, \\\"file_name\\\": \\\"\\\", \\\"local_format\\\": \\\"csv\\\", \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}]}\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"File name must be provided\\\"):\\n            await component.save_to_file()\\n\\n    @pytest.mark.asyncio\\n    async def test_file_name_with_extension_stripped(self, component_class):\\n        \\\"\\\"\\\"Test that file extension is properly handled when included in file_name.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n        df = DataFrame([{\\\"col1\\\": 1}])\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": df,\\n                \\\"file_name\\\": \\\"test_output.csv\\\",\\n                \\\"local_format\\\": \\\"csv\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n\\n        # Mock only the database and upload functions - let file operations run normally\\n        with (\\n            patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n            ) as mock_get_user,\\n        ):\\n            mock_db = AsyncMock()\\n            mock_session.return_value.__aenter__.return_value = mock_db\\n            mock_get_user.return_value = MagicMock()\\n            mock_upload.return_value = MagicMock(path=\\\"test_output.csv\\\", provider=\\\"s3\\\")\\n\\n            result = await component.save_to_file()\\n\\n            # Should only have .csv once, not .csv.csv\\n            assert \\\"test_output.csv\\\" in result.text\\n            assert \\\"test_output.csv.csv\\\" not in result.text\\n\\n    @pytest.mark.asyncio\\n    async def test_append_mode_txt_file(self, component_class):\\n        \\\"\\\"\\\"Test append mode for text files.\\\"\\\"\\\"\\n        from tempfile import NamedTemporaryFile\\n\\n        # Create a temporary file with existing content\\n        with NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".txt\\\", delete=False) as tmp_file:\\n            tmp_file.write(\\\"Existing content\\\")\\n            tmp_path = Path(tmp_file.name)\\n\\n        try:\\n            component = component_class(_user_id=str(uuid4()))\\n            component.set_attributes(\\n                {\\n                    \\\"input\\\": Message(text=\\\"New content\\\"),\\n                    \\\"file_name\\\": tmp_path.stem,  # Use filename without extension\\n                    \\\"local_format\\\": \\\"txt\\\",\\n                    \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n                    \\\"append_mode\\\": True,\\n                }\\n            )\\n\\n            # This test verifies LOCAL-backend append semantics (the file persists on\\n            # disk and is re-read), so pin the backend to local. Under a remote (S3)\\n            # backend the staging file is intentionally deleted after upload.\\n            settings_mock = MagicMock()\\n            settings_mock.storage_type = \\\"local\\\"\\n            settings_mock.restrict_local_file_access = False\\n            settings_mock.config_dir = str(tmp_path.parent)\\n            settings_service_mock = MagicMock()\\n            settings_service_mock.settings = settings_mock\\n\\n            # Mock the path resolution to return our temp file\\n            with (\\n                patch(\\\"lfx.components.files_and_knowledge.save_file.Path\\\") as mock_path_class,\\n                patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n                patch(\\\"lfx.services.deps.session_scope\\\") as mock_session,\\n                patch(\\n                    \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n                ) as mock_get_user,\\n                patch(\\n                    \\\"lfx.components.files_and_knowledge.save_file.get_settings_service\\\",\\n                    return_value=settings_service_mock,\\n                ),\\n            ):\\n                # Make Path() return our temp file path\\n                mock_path_class.return_value = tmp_path\\n                mock_db = AsyncMock()\\n                mock_session.return_value.__aenter__.return_value = mock_db\\n                mock_get_user.return_value = MagicMock()\\n                mock_upload.return_value = MagicMock(path=tmp_path.name, provider=\\\"local\\\")\\n\\n                result = await component.save_to_file()\\n\\n                # Verify append happened\\n                assert \\\"appended to\\\" in result.text\\n                # Verify the file contains both old and new content\\n                assert tmp_path.read_text(encoding=\\\"utf-8\\\") == \\\"Existing content\\\\nNew content\\\"\\n        finally:\\n            # Clean up temp file\\n            if tmp_path.exists():\\n                tmp_path.unlink()\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.parametrize(\\\"append_mode\\\", [False, True])\\n    async def test_local_save_rejects_absolute_paths_before_file_access(self, component_class, tmp_path, append_mode):\\n        \\\"\\\"\\\"Reject path-shaped local file names before they can read or write a file.\\\"\\\"\\\"\\n        owner_file = tmp_path / \\\"owner-user-id\\\" / \\\"owner-file.txt\\\"\\n        owner_file.parent.mkdir()\\n        owner_file.write_text(\\\"owner content\\\", encoding=\\\"utf-8\\\")\\n\\n        component = component_class(_user_id=str(uuid4()))\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": Message(text=\\\"attacker content\\\"),\\n                \\\"file_name\\\": str(owner_file),\\n                \\\"local_format\\\": \\\"txt\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n                \\\"append_mode\\\": append_mode,\\n            }\\n        )\\n\\n        with (\\n            patch.object(component, \\\"_upload_file\\\", new_callable=AsyncMock) as mock_upload,\\n            pytest.raises(ValueError, match=\\\"Local file name must be a file name only\\\"),\\n        ):\\n            await component.save_to_file()\\n\\n        assert owner_file.read_text(encoding=\\\"utf-8\\\") == \\\"owner content\\\"\\n        mock_upload.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.parametrize(\\n        \\\"file_name\\\",\\n        [\\n            \\\"../owner-file\\\",\\n            \\\"owner-user-id/owner-file\\\",\\n            r\\\"owner-user-id\\\\owner-file\\\",\\n            r\\\"C:\\\\Users\\\\owner\\\\file\\\",\\n            \\\"C:owner-file\\\",\\n        ],\\n    )\\n    async def test_local_save_rejects_nested_or_traversal_paths(\\n        self, component_class, tmp_path, monkeypatch, file_name\\n    ):\\n        \\\"\\\"\\\"Reject relative path traversal and storage-prefix style local file names.\\\"\\\"\\\"\\n        monkeypatch.chdir(tmp_path)\\n        component = component_class(_user_id=str(uuid4()))\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": Message(text=\\\"attacker content\\\"),\\n                \\\"file_name\\\": file_name,\\n                \\\"local_format\\\": \\\"txt\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n\\n        with (\\n            patch.object(component, \\\"_upload_file\\\", new_callable=AsyncMock) as mock_upload,\\n            pytest.raises(ValueError, match=\\\"Local file name must be a file name only\\\"),\\n        ):\\n            await component.save_to_file()\\n\\n        assert not list(tmp_path.rglob(\\\"*.txt\\\"))\\n        mock_upload.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"fake_googleapiclient\\\")\\n    async def test_google_drive_credential_parsing_with_control_characters(self, component_class):\\n        \\\"\\\"\\\"Test that GCP service account JSON with literal newlines (control characters) can be parsed.\\n\\n        This tests the fix for the bug where pasted GCP service account JSON fails with:\\n        'Invalid control character at: line 1 column 183 (char 182)'\\n        \\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n\\n        # Simulate a GCP service account JSON with literal newlines in the private_key field.\\n        # Use a clearly fake, short key to avoid tripping secret scanners while preserving the newline pattern.\\n        fake_private_key = \\\"-----BEGIN KEY-----\\\\nFAKE\\\\n-----END KEY-----\\\\n\\\"\\n        service_account_json = (\\n            f'{{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test-project-123\\\", \\\"private_key\\\": \\\"{fake_private_key}\\\"}}'\\n        )\\n\\n        message = Message(text=\\\"test content\\\")\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": message,\\n                \\\"file_name\\\": \\\"test_gdrive_file\\\",\\n                \\\"gdrive_format\\\": \\\"txt\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Google Drive\\\"}],\\n                \\\"service_account_key\\\": service_account_json,\\n                \\\"folder_id\\\": \\\"test_folder_id_123\\\",\\n            }\\n        )\\n\\n        # Mock Google Drive dependencies\\n        with (\\n            patch(\\\"google.oauth2.service_account.Credentials.from_service_account_info\\\") as mock_creds,\\n            patch(\\\"googleapiclient.discovery.build\\\") as mock_build,\\n        ):\\n            mock_drive_service = MagicMock()\\n            mock_build.return_value = mock_drive_service\\n\\n            # Mock the file upload response\\n            mock_drive_service.files().create().execute.return_value = {\\\"id\\\": \\\"file123\\\"}\\n\\n            result = await component.save_to_file()\\n\\n            # Verify credentials were parsed successfully (should not raise JSONDecodeError)\\n            mock_creds.assert_called_once()\\n            creds_dict = mock_creds.call_args[0][0]\\n\\n            # Verify the parsed credentials have the expected structure\\n            assert creds_dict[\\\"type\\\"] == \\\"service_account\\\"\\n            assert creds_dict[\\\"project_id\\\"] == \\\"test-project-123\\\"\\n            assert \\\"private_key\\\" in creds_dict\\n            assert \\\"BEGIN KEY\\\" in creds_dict[\\\"private_key\\\"]\\n\\n            # Verify successful upload message\\n            assert \\\"successfully uploaded to Google Drive\\\" in result.text\\n            assert \\\"file123\\\" in result.text\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"fake_googleapiclient\\\")\\n    async def test_google_drive_credential_parsing_strategies(self, component_class):\\n        \\\"\\\"\\\"Test various GCP credential parsing strategies.\\\"\\\"\\\"\\n        component = component_class(_user_id=str(uuid4()))\\n\\n        test_cases = [\\n            # Case 1: Normal JSON (should work)\\n            ('{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}', \\\"Normal JSON\\\"),\\n            # Case 2: JSON with literal newlines (the bug case)\\n            ('{\\\"type\\\": \\\"service_account\\\", \\\"private_key\\\": \\\"-----BEGIN\\\\nKEY\\\\n-----END\\\"}', \\\"With control chars\\\"),\\n            # Case 3: JSON with extra whitespace\\n            ('  \\\\n{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}  \\\\n', \\\"With whitespace\\\"),\\n            # Case 4: Double-encoded JSON, as emitted by some secret pipelines (LE-2561)\\n            (json.dumps('{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}'), \\\"Double-encoded\\\"),\\n        ]\\n\\n        for service_account_json, test_name in test_cases:\\n            message = Message(text=\\\"test\\\")\\n            component.set_attributes(\\n                {\\n                    \\\"input\\\": message,\\n                    \\\"file_name\\\": \\\"test_file\\\",\\n                    \\\"gdrive_format\\\": \\\"txt\\\",\\n                    \\\"storage_location\\\": [{\\\"name\\\": \\\"Google Drive\\\"}],\\n                    \\\"service_account_key\\\": service_account_json,\\n                    \\\"folder_id\\\": \\\"test_folder\\\",\\n                }\\n            )\\n\\n            with (\\n                patch(\\\"google.oauth2.service_account.Credentials.from_service_account_info\\\") as mock_creds,\\n                patch(\\\"googleapiclient.discovery.build\\\") as mock_build,\\n            ):\\n                mock_drive_service = MagicMock()\\n                mock_build.return_value = mock_drive_service\\n                mock_drive_service.files().create().execute.return_value = {\\\"id\\\": f\\\"file_{test_name}\\\"}\\n\\n                # Should not raise JSONDecodeError for any case\\n                await component.save_to_file()\\n\\n                # Verify credentials were parsed\\n                mock_creds.assert_called_once()\\n                creds_dict = mock_creds.call_args[0][0]\\n                assert isinstance(creds_dict, dict)\\n                assert creds_dict[\\\"type\\\"] == \\\"service_account\\\"\\n\\n                mock_creds.reset_mock()\\n\\n    def test_append_mode_hidden_for_cloud_storage(self, component_class):\\n        \\\"\\\"\\\"Test that append_mode is hidden for AWS and Google Drive storage.\\\"\\\"\\\"\\n        component = component_class()\\n\\n        # Test Local storage - append_mode should be visible\\n        build_config = {\\n            \\\"file_name\\\": {\\\"show\\\": False},\\n            \\\"append_mode\\\": {\\\"show\\\": False},\\n            \\\"local_format\\\": {\\\"show\\\": False},\\n        }\\n        result = component.update_build_config(build_config, [{\\\"name\\\": \\\"Local\\\"}], \\\"storage_location\\\")\\n        assert result[\\\"append_mode\\\"][\\\"show\\\"] is True, \\\"append_mode should be visible for Local storage\\\"\\n        assert result[\\\"file_name\\\"][\\\"show\\\"] is True\\n        assert result[\\\"local_format\\\"][\\\"show\\\"] is True\\n\\n        # Test AWS storage - append_mode should be hidden\\n        build_config = {\\n            \\\"file_name\\\": {\\\"show\\\": False},\\n            \\\"append_mode\\\": {\\\"show\\\": False},\\n            \\\"aws_format\\\": {\\\"show\\\": False},\\n        }\\n        result = component.update_build_config(build_config, [{\\\"name\\\": \\\"AWS\\\"}], \\\"storage_location\\\")\\n        assert result[\\\"append_mode\\\"][\\\"show\\\"] is False, \\\"append_mode should be hidden for AWS storage\\\"\\n        assert result[\\\"file_name\\\"][\\\"show\\\"] is True\\n        assert result[\\\"aws_format\\\"][\\\"show\\\"] is True\\n\\n        # Test Google Drive storage - append_mode should be hidden\\n        build_config = {\\n            \\\"file_name\\\": {\\\"show\\\": False},\\n            \\\"append_mode\\\": {\\\"show\\\": False},\\n            \\\"gdrive_format\\\": {\\\"show\\\": False},\\n        }\\n        result = component.update_build_config(build_config, [{\\\"name\\\": \\\"Google Drive\\\"}], \\\"storage_location\\\")\\n        assert result[\\\"append_mode\\\"][\\\"show\\\"] is False, \\\"append_mode should be hidden for Google Drive storage\\\"\\n        assert result[\\\"file_name\\\"][\\\"show\\\"] is True\\n        assert result[\\\"gdrive_format\\\"][\\\"show\\\"] is True\\n\\n    def test_storage_location_defaults_to_local(self, component_class):\\n        \\\"\\\"\\\"Test that storage_location input defaults to Local when component is dropped.\\\"\\\"\\\"\\n        storage_input = next(i for i in component_class.inputs if i.name == \\\"storage_location\\\")\\n        assert storage_input.value == [{\\\"name\\\": \\\"Local\\\", \\\"icon\\\": \\\"hard-drive\\\"}]\\n\\n    def test_default_local_fields_are_visible(self, component_class):\\n        \\\"\\\"\\\"Test that required local fields are visible on first render.\\\"\\\"\\\"\\n        inputs_by_name = {component_input.name: component_input for component_input in component_class.inputs}\\n\\n        assert inputs_by_name[\\\"file_name\\\"].show is True\\n        assert inputs_by_name[\\\"append_mode\\\"].show is True\\n        assert inputs_by_name[\\\"local_format\\\"].show is True\\n        assert inputs_by_name[\\\"aws_format\\\"].show is False\\n        assert inputs_by_name[\\\"gdrive_format\\\"].show is False\\n\\n    def test_storage_location_is_advanced(self, component_class):\\n        \\\"\\\"\\\"Test that storage_location is in advanced controls.\\\"\\\"\\\"\\n        storage_input = next(i for i in component_class.inputs if i.name == \\\"storage_location\\\")\\n        assert storage_input.advanced is True\\n\\n    def test_get_input_type_raw_pandas_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test that a raw pandas DataFrame is auto-wrapped into Langflow DataFrame.\\\"\\\"\\\"\\n        component = component_class()\\n        raw_df = pd.DataFrame([{\\\"a\\\": 1, \\\"b\\\": 2}])\\n        component.set_attributes({\\\"input\\\": raw_df, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"csv\\\"})\\n        assert component._get_input_type() == \\\"DataFrame\\\"\\n        assert type(component.input) is DataFrame\\n\\n    def test_get_input_type_string_json_array(self, component_class):\\n        \\\"\\\"\\\"Test that a JSON array string is coerced into a DataFrame.\\\"\\\"\\\"\\n        component = component_class()\\n        json_str = '[{\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 30}, {\\\"name\\\": \\\"Bob\\\", \\\"age\\\": 25}]'\\n        component.set_attributes({\\\"input\\\": json_str, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"csv\\\"})\\n        assert component._get_input_type() == \\\"DataFrame\\\"\\n        assert type(component.input) is DataFrame\\n\\n    def test_get_input_type_string_json_object(self, component_class):\\n        \\\"\\\"\\\"Test that a single JSON object string is coerced into a DataFrame.\\\"\\\"\\\"\\n        component = component_class()\\n        json_str = '{\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 30}'\\n        component.set_attributes({\\\"input\\\": json_str, \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"csv\\\"})\\n        assert component._get_input_type() == \\\"DataFrame\\\"\\n        assert type(component.input) is DataFrame\\n\\n    def test_get_input_type_string_plain_text(self, component_class):\\n        \\\"\\\"\\\"Test that plain text is coerced into a Message.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"input\\\": \\\"Hello world\\\", \\\"file_name\\\": \\\"test\\\", \\\"file_format\\\": \\\"txt\\\"})\\n        assert component._get_input_type() == \\\"Message\\\"\\n        assert type(component.input) is Message\\n\\n    def test_file_format_overrides_storage_format(self, component_class):\\n        \\\"\\\"\\\"Test that tool-mode file_format overrides the storage-specific format.\\\"\\\"\\\"\\n        component = component_class()\\n        df = DataFrame([{\\\"a\\\": 1}])\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": df,\\n                \\\"file_name\\\": \\\"test\\\",\\n                \\\"local_format\\\": \\\"json\\\",\\n                \\\"file_format\\\": \\\"csv\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n        assert component._get_file_format_for_location(\\\"Local\\\") == \\\"csv\\\"\\n\\n    def test_file_format_empty_falls_back_to_storage_format(self, component_class):\\n        \\\"\\\"\\\"Test that empty file_format falls back to the storage-specific format.\\\"\\\"\\\"\\n        component = component_class()\\n        df = DataFrame([{\\\"a\\\": 1}])\\n        component.set_attributes(\\n            {\\n                \\\"input\\\": df,\\n                \\\"file_name\\\": \\\"test\\\",\\n                \\\"local_format\\\": \\\"json\\\",\\n                \\\"file_format\\\": \\\"\\\",\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Local\\\"}],\\n            }\\n        )\\n        assert component._get_file_format_for_location(\\\"Local\\\") == \\\"json\\\"\\n\\n    def test_input_has_tool_mode(self, component_class):\\n        \\\"\\\"\\\"Test that the input field has tool_mode enabled.\\\"\\\"\\\"\\n        input_field = next(i for i in component_class.inputs if i.name == \\\"input\\\")\\n        assert getattr(input_field, \\\"tool_mode\\\", False) is True\\n\\n    def test_file_format_has_tool_mode(self, component_class):\\n        \\\"\\\"\\\"Test that the file_format field has tool_mode enabled.\\\"\\\"\\\"\\n        format_field = next(i for i in component_class.inputs if i.name == \\\"file_format\\\")\\n        assert getattr(format_field, \\\"tool_mode\\\", False) is True\\n\\n    def test_file_format_hidden_in_ui(self, component_class):\\n        \\\"\\\"\\\"Test that file_format is hidden in the flow UI.\\\"\\\"\\\"\\n        format_field = next(i for i in component_class.inputs if i.name == \\\"file_format\\\")\\n        assert format_field.show is False\\n\\n\\n# --- serving-plane end-user namespacing (files owned by the end user, not the SID) ---\\n\\nfrom types import SimpleNamespace  # noqa: E402\\n\\n\\ndef _save_component_with_end_user(end_user):\\n    component = SaveToFileComponent()\\n    component._vertex = MagicMock()\\n    component._vertex.graph = SimpleNamespace(end_user_id=end_user)\\n    return component\\n\\n\\ndef test_end_user_segment_none_when_absent():\\n    # BC: no end user -> None -> save path falls back to the SID scope, unchanged.\\n    assert _save_component_with_end_user(None)._serving_end_user_segment() is None\\n\\n\\ndef test_end_user_segment_readable_id_preserved():\\n    assert _save_component_with_end_user(\\\"alice\\\")._serving_end_user_segment() == \\\"alice\\\"\\n\\n\\ndef test_end_user_segment_uuid_preserved():\\n    uid = \\\"0c870455-b9e3-480c-bc84-0794de978f51\\\"\\n    assert _save_component_with_end_user(uid)._serving_end_user_segment() == uid\\n\\n\\ndef test_end_user_segment_blocks_path_traversal():\\n    seg = _save_component_with_end_user(\\\"../../etc/passwd\\\")._serving_end_user_segment()\\n    assert seg is not None\\n    # single path component -> cannot escape the root\\n    assert \\\"/\\\" not in seg\\n    assert \\\"\\\\\\\\\\\" not in seg\\n\\n\\ndef test_end_user_segment_sanitizes_separators():\\n    assert _save_component_with_end_user(\\\"a/b\\\\\\\\c\\\")._serving_end_user_segment() == \\\"a_b_c\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_split_text_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30367ab361c7d17aa8fa04ee43204604865d0fabc3d6df3ca4fc64da9cc4c8a9\",\"content\":\"import pytest\\nfrom lfx.components.data import URLComponent\\nfrom lfx.components.processing import SplitTextComponent\\nfrom lfx.schema import Data, DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestSplitTextComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return SplitTextComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"data_inputs\\\": [Data(text=\\\"Hello World\\\")],\\n            \\\"chunk_overlap\\\": 200,\\n            \\\"chunk_size\\\": 1000,\\n            \\\"separator\\\": \\\"\\\\n\\\",\\n            \\\"session_id\\\": \\\"test_session\\\",\\n            \\\"sender\\\": \\\"test_sender\\\",\\n            \\\"sender_name\\\": \\\"test_sender_name\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        return [\\n            # It was in helpers in version 1.0.19\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"helpers\\\", \\\"file_name\\\": \\\"SplitText\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"processing\\\", \\\"file_name\\\": \\\"split_text\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"processing\\\", \\\"file_name\\\": \\\"split_text\\\"},\\n        ]\\n\\n    def test_split_text_basic(self):\\n        \\\"\\\"\\\"Test basic text splitting functionality.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_text = \\\"First chunk\\\\nSecond chunk\\\\nThird chunk\\\"\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=test_text)],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 15,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"text_key\\\": \\\"text\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        data_frame = component.split_text()\\n        assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n        assert len(data_frame) == 3, f\\\"Expected DataFrame with 3 rows, got {len(data_frame)}\\\"\\n        assert list(data_frame.columns) == [\\\"text\\\"], f\\\"Expected columns ['text'], got {list(data_frame.columns)}\\\"\\n        assert \\\"First chunk\\\" in data_frame.iloc[0][\\\"text\\\"], (\\n            f\\\"Expected 'First chunk', got '{data_frame.iloc[0]['text']}'\\\"\\n        )\\n        assert \\\"Second chunk\\\" in data_frame.iloc[1][\\\"text\\\"], (\\n            f\\\"Expected 'Second chunk', got '{data_frame.iloc[1]['text']}'\\\"\\n        )\\n        assert \\\"Third chunk\\\" in data_frame.iloc[2][\\\"text\\\"], (\\n            f\\\"Expected 'Third chunk', got '{data_frame.iloc[2]['text']}'\\\"\\n        )\\n\\n    def test_split_text_with_overlap(self):\\n        \\\"\\\"\\\"Test text splitting with overlap.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_text = \\\"First chunk.\\\\nSecond chunk.\\\\nThird chunk.\\\"\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=test_text)],\\n                \\\"chunk_overlap\\\": 5,  # Small overlap to test functionality\\n                \\\"chunk_size\\\": 20,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        data_frame = component.split_text()\\n        assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n        assert len(data_frame) == 3, f\\\"Expected DataFrame with 3 rows, got {len(data_frame)}\\\"\\n        assert list(data_frame.columns) == [\\\"text\\\"], f\\\"Expected columns ['text'], got {list(data_frame.columns)}\\\"\\n        assert \\\"First chunk\\\" in data_frame.iloc[0][\\\"text\\\"], (\\n            f\\\"Expected 'First chunk', got '{data_frame.iloc[0]['text']}'\\\"\\n        )\\n        assert \\\"Second chunk\\\" in data_frame.iloc[1][\\\"text\\\"], (\\n            f\\\"Expected 'Second chunk', got '{data_frame.iloc[1]['text']}'\\\"\\n        )\\n        assert \\\"Third chunk\\\" in data_frame.iloc[2][\\\"text\\\"], (\\n            f\\\"Expected 'Third chunk', got '{data_frame.iloc[2]['text']}'\\\"\\n        )\\n\\n    def test_split_text_custom_separator(self):\\n        \\\"\\\"\\\"Test text splitting with a custom separator.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_text = \\\"First chunk.|Second chunk.|Third chunk.\\\"\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=test_text)],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 10,\\n                \\\"separator\\\": \\\"|\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        data_frame = component.split_text()\\n        assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n        assert len(data_frame) == 3, f\\\"Expected DataFrame with 3 rows, got {len(data_frame)}\\\"\\n        assert list(data_frame.columns) == [\\\"text\\\"], f\\\"Expected columns ['text'], got {list(data_frame.columns)}\\\"\\n        assert \\\"First chunk\\\" in data_frame.iloc[0][\\\"text\\\"], (\\n            f\\\"Expected 'First chunk', got '{data_frame.iloc[0]['text']}'\\\"\\n        )\\n        assert \\\"Second chunk\\\" in data_frame.iloc[1][\\\"text\\\"], (\\n            f\\\"Expected 'Second chunk', got '{data_frame.iloc[1]['text']}'\\\"\\n        )\\n        assert \\\"Third chunk\\\" in data_frame.iloc[2][\\\"text\\\"], (\\n            f\\\"Expected 'Third chunk', got '{data_frame.iloc[2]['text']}'\\\"\\n        )\\n\\n    def test_split_text_with_metadata(self):\\n        \\\"\\\"\\\"Test text splitting while preserving metadata.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_metadata = {\\\"source\\\": \\\"test.txt\\\", \\\"author\\\": \\\"test\\\"}\\n        test_text = \\\"First chunk\\\\nSecond chunk\\\"\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=test_text, data=test_metadata)],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 7,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"clean_output\\\": False,\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        data_frame = component.split_text()\\n        assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n        assert len(data_frame) == 2, f\\\"Expected DataFrame with 2 rows, got {len(data_frame)}\\\"\\n        assert \\\"First chunk\\\" in data_frame.iloc[0][\\\"text\\\"], (\\n            f\\\"Expected 'First chunk', got '{data_frame.iloc[0]['text']}'\\\"\\n        )\\n        assert \\\"Second chunk\\\" in data_frame.iloc[1][\\\"text\\\"], (\\n            f\\\"Expected 'Second chunk', got '{data_frame.iloc[1]['text']}'\\\"\\n        )\\n        # Loop over each row to check metadata\\n        for _, row in data_frame.iterrows():\\n            assert row[\\\"source\\\"] == test_metadata[\\\"source\\\"], (\\n                f\\\"Expected source '{test_metadata['source']}', got '{row['source']}'\\\"\\n            )\\n            assert row[\\\"author\\\"] == test_metadata[\\\"author\\\"], (\\n                f\\\"Expected author '{test_metadata['author']}', got '{row['author']}'\\\"\\n            )\\n\\n    def test_split_text_clean_output_strips_metadata(self):\\n        \\\"\\\"\\\"Test that clean_output=True strips metadata columns from the output.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_metadata = {\\\"source\\\": \\\"test.txt\\\", \\\"author\\\": \\\"test\\\"}\\n        test_text = \\\"First chunk\\\\nSecond chunk\\\"\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=test_text, data=test_metadata)],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 7,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"clean_output\\\": True,\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        data_frame = component.split_text()\\n        assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n        assert len(data_frame) == 2, f\\\"Expected DataFrame with 2 rows, got {len(data_frame)}\\\"\\n        assert list(data_frame.columns) == [\\\"text\\\"], f\\\"Expected only ['text'] column, got {list(data_frame.columns)}\\\"\\n        assert \\\"source\\\" not in data_frame.columns, \\\"Metadata column 'source' should not be present\\\"\\n        assert \\\"author\\\" not in data_frame.columns, \\\"Metadata column 'author' should not be present\\\"\\n\\n    def test_split_text_empty_input(self):\\n        \\\"\\\"\\\"Test handling of empty input text.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=\\\"\\\")],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 10,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        results = component.split_text()\\n        assert len(results) == 0, f\\\"Expected 0 chunks for empty input, got {len(results)}\\\"\\n\\n    def test_split_text_single_chunk(self):\\n        \\\"\\\"\\\"Test text that fits in a single chunk.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_text = \\\"Small text\\\"\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=test_text)],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 100,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        results = component.split_text()\\n        assert len(results) == 1, f\\\"Expected 1 chunk, got {len(results)}\\\"\\n        assert results[\\\"text\\\"][0] == test_text, f\\\"Expected '{test_text}', got '{results['text'][0]}'\\\"\\n\\n    def test_split_text_multiple_inputs(self):\\n        \\\"\\\"\\\"Test splitting multiple input texts.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_texts = [\\\"First text\\\\nSecond line\\\", \\\"Another text\\\\nAnother line\\\"]\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": [Data(text=text) for text in test_texts],\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 10,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        results = component.split_text()\\n        assert len(results) == 4, f\\\"Expected 4 chunks (2 from each text), got {len(results)}\\\"\\n        assert \\\"First text\\\" in results[\\\"text\\\"][0], f\\\"Expected 'First text', got '{results['text'][0]}'\\\"\\n        assert \\\"Second line\\\" in results[\\\"text\\\"][1], f\\\"Expected 'Second line', got '{results['text'][1]}'\\\"\\n        assert \\\"Another text\\\" in results[\\\"text\\\"][2], f\\\"Expected 'Another text', got '{results['text'][2]}'\\\"\\n        assert \\\"Another line\\\" in results[\\\"text\\\"][3], f\\\"Expected 'Another line', got '{results['text'][3]}'\\\"\\n\\n    def test_split_text_with_dataframe_input(self):\\n        \\\"\\\"\\\"Test splitting text with DataFrame input.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        test_texts = [\\\"First text\\\\nSecond line\\\", \\\"Another text\\\\nAnother line\\\"]\\n        data_frame = DataFrame([Data(text=text) for text in test_texts])\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": data_frame,\\n                \\\"chunk_overlap\\\": 0,\\n                \\\"chunk_size\\\": 10,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        results = component.split_text()\\n        assert len(results) == 4, f\\\"Expected 4 chunks (2 from each text), got {len(results)}\\\"\\n        assert \\\"First text\\\" in results[\\\"text\\\"][0], f\\\"Expected 'First text', got '{results['text'][0]}'\\\"\\n        assert \\\"Second line\\\" in results[\\\"text\\\"][1], f\\\"Expected 'Second line', got '{results['text'][1]}'\\\"\\n        assert \\\"Another text\\\" in results[\\\"text\\\"][2], f\\\"Expected 'Another text', got '{results['text'][2]}'\\\"\\n        assert \\\"Another line\\\" in results[\\\"text\\\"][3], f\\\"Expected 'Another line', got '{results['text'][3]}'\\\"\\n\\n    async def test_with_url_loader(self):\\n        \\\"\\\"\\\"Test splitting text with URL loader.\\\"\\\"\\\"\\n        component = SplitTextComponent()\\n        url = [\\\"https://en.wikipedia.org/wiki/London\\\", \\\"https://en.wikipedia.org/wiki/Paris\\\"]\\n        data_frame = await URLComponent(urls=url, format=\\\"Text\\\").fetch_content()\\n        assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n        assert len(data_frame) == 2, f\\\"Expected DataFrame with 2 rows, got {len(data_frame)}\\\"\\n\\n        # Use a reasonable chunk size that will work with varying URL content lengths\\n        # The test validates that URL-loaded content can be split, not the exact number of chunks\\n        component.set_attributes(\\n            {\\n                \\\"data_inputs\\\": data_frame,\\n                \\\"chunk_overlap\\\": 200,\\n                \\\"chunk_size\\\": 1000,\\n                \\\"separator\\\": \\\"\\\\n\\\",\\n                \\\"session_id\\\": \\\"test_session\\\",\\n                \\\"sender\\\": \\\"test_sender\\\",\\n                \\\"sender_name\\\": \\\"test_sender_name\\\",\\n            }\\n        )\\n\\n        results = component.split_text()\\n        assert isinstance(results, DataFrame), \\\"Expected DataFrame instance\\\"\\n        # Verify we get at least as many chunks as inputs (could be more if content is large)\\n        assert len(results) >= 2, f\\\"Expected DataFrame with at least 2 rows, got {len(results)}\\\"\\n        # Verify the results have the expected text column\\n        assert \\\"text\\\" in results.columns, f\\\"Expected 'text' column in results, got {list(results.columns)}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_text_operations_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"83ebb05a08e35f2f1533e18ea149749d8378151402fe089517e97fde16bacf71\",\"content\":\"\\\"\\\"\\\"Tests for TextOperations component.\\n\\nIncludes regression tests for QA-reported bugs.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.components.processing.text_operations import TextOperations\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestTextOperationsComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return TextOperations\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"text_input\\\": \\\"Hello world\\\",\\n            \\\"operation\\\": [{\\\"name\\\": \\\"Word Count\\\"}],\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n\\nclass TestTextOperationsWordCount:\\n    def test_word_count_basic(self):\\n        \\\"\\\"\\\"Test basic word count operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input = \\\"Hello world this is a test\\\"\\n        component.count_words = True\\n        component.count_characters = True\\n        component.count_lines = True\\n\\n        result = component._word_count(component.text_input)\\n\\n        assert result[\\\"word_count\\\"] == 6\\n        assert result[\\\"unique_words\\\"] == 6\\n        assert result[\\\"character_count\\\"] == 26\\n        assert result[\\\"character_count_no_spaces\\\"] == 21\\n        assert result[\\\"line_count\\\"] == 1\\n        assert result[\\\"non_empty_lines\\\"] == 1\\n\\n    def test_word_count_multiline(self):\\n        \\\"\\\"\\\"Test word count with multiple lines.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.count_words = True\\n        component.count_characters = True\\n        component.count_lines = True\\n\\n        result = component._word_count(\\\"Line one\\\\nLine two\\\\n\\\\nLine four\\\")\\n\\n        assert result[\\\"line_count\\\"] == 4\\n        assert result[\\\"non_empty_lines\\\"] == 3\\n\\n    def test_word_count_disabled_options(self):\\n        \\\"\\\"\\\"Test word count with disabled options.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.count_words = False\\n        component.count_characters = False\\n        component.count_lines = True\\n\\n        result = component._word_count(\\\"Hello world\\\")\\n\\n        assert \\\"word_count\\\" not in result\\n        assert \\\"character_count\\\" not in result\\n        assert \\\"line_count\\\" in result\\n\\n\\nclass TestTextOperationsCaseConversion:\\n    def test_case_uppercase(self):\\n        \\\"\\\"\\\"Test uppercase conversion.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.case_type = \\\"uppercase\\\"\\n\\n        result = component._case_conversion(\\\"hello world\\\")\\n\\n        assert result == \\\"HELLO WORLD\\\"\\n\\n    def test_case_lowercase(self):\\n        \\\"\\\"\\\"Test lowercase conversion.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.case_type = \\\"lowercase\\\"\\n\\n        result = component._case_conversion(\\\"HELLO WORLD\\\")\\n\\n        assert result == \\\"hello world\\\"\\n\\n    def test_case_title(self):\\n        \\\"\\\"\\\"Test title case conversion.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.case_type = \\\"title\\\"\\n\\n        result = component._case_conversion(\\\"hello world\\\")\\n\\n        assert result == \\\"Hello World\\\"\\n\\n    def test_case_capitalize(self):\\n        \\\"\\\"\\\"Test capitalize conversion.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.case_type = \\\"capitalize\\\"\\n\\n        result = component._case_conversion(\\\"hello world\\\")\\n\\n        assert result == \\\"Hello world\\\"\\n\\n    def test_case_swapcase(self):\\n        \\\"\\\"\\\"Test swapcase conversion.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.case_type = \\\"swapcase\\\"\\n\\n        result = component._case_conversion(\\\"Hello World\\\")\\n\\n        assert result == \\\"hELLO wORLD\\\"\\n\\n\\nclass TestTextOperationsReplace:\\n    def test_replace_simple(self):\\n        \\\"\\\"\\\"Test simple text replacement.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.search_pattern = \\\"hello\\\"\\n        component.replacement_text = \\\"hi\\\"\\n        component.use_regex = False\\n\\n        result = component._text_replace(\\\"hello world\\\")\\n\\n        assert result == \\\"hi world\\\"\\n\\n    def test_replace_multiple_occurrences(self):\\n        \\\"\\\"\\\"Test replacement of multiple occurrences.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.search_pattern = \\\"a\\\"\\n        component.replacement_text = \\\"X\\\"\\n        component.use_regex = False\\n\\n        result = component._text_replace(\\\"banana\\\")\\n\\n        assert result == \\\"bXnXnX\\\"\\n\\n    def test_replace_regex(self):\\n        \\\"\\\"\\\"Test regex replacement.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.search_pattern = r\\\"\\\\d+\\\"\\n        component.replacement_text = \\\"NUM\\\"\\n        component.use_regex = True\\n\\n        result = component._text_replace(\\\"abc123def456\\\")\\n\\n        assert result == \\\"abcNUMdefNUM\\\"\\n\\n    def test_replace_empty_pattern(self):\\n        \\\"\\\"\\\"Test replacement with empty pattern.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.search_pattern = \\\"\\\"\\n        component.replacement_text = \\\"X\\\"\\n        component.use_regex = False\\n\\n        result = component._text_replace(\\\"hello\\\")\\n\\n        assert result == \\\"hello\\\"\\n\\n    def test_replace_invalid_regex(self):\\n        \\\"\\\"\\\"Test replacement with invalid regex pattern.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.search_pattern = \\\"[invalid\\\"\\n        component.replacement_text = \\\"X\\\"\\n        component.use_regex = True\\n        component.log = lambda _: None\\n\\n        result = component._text_replace(\\\"hello\\\")\\n\\n        assert result == \\\"hello\\\"\\n\\n\\nclass TestTextOperationsExtract:\\n    def test_extract_numbers(self):\\n        \\\"\\\"\\\"Test extracting numbers from text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.extract_pattern = r\\\"\\\\d+\\\"\\n        component.max_matches = 10\\n\\n        result = component._text_extract(\\\"abc123def456ghi789\\\")\\n\\n        assert result == [\\\"123\\\", \\\"456\\\", \\\"789\\\"]\\n\\n    def test_extract_with_limit(self):\\n        \\\"\\\"\\\"Test extraction with max matches limit.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.extract_pattern = r\\\"\\\\d+\\\"\\n        component.max_matches = 2\\n\\n        result = component._text_extract(\\\"abc123def456ghi789\\\")\\n\\n        assert result == [\\\"123\\\", \\\"456\\\"]\\n\\n    def test_extract_no_matches(self):\\n        \\\"\\\"\\\"Test extraction with no matches.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.extract_pattern = r\\\"\\\\d+\\\"\\n        component.max_matches = 10\\n\\n        result = component._text_extract(\\\"no numbers here\\\")\\n\\n        assert result == []\\n\\n    def test_extract_empty_pattern(self):\\n        \\\"\\\"\\\"Test extraction with empty pattern.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.extract_pattern = \\\"\\\"\\n        component.max_matches = 10\\n\\n        result = component._text_extract(\\\"hello\\\")\\n\\n        assert result == []\\n\\n    def test_extract_invalid_regex(self):\\n        \\\"\\\"\\\"Test extraction with invalid regex raises ValueError (Bug #3 fix).\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.extract_pattern = \\\"[invalid\\\"\\n        component.max_matches = 10\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid regex pattern\\\"):\\n            component._text_extract(\\\"hello\\\")\\n\\n\\nclass TestTextOperationsHead:\\n    def test_head_basic(self):\\n        \\\"\\\"\\\"Test extracting head of text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.head_characters = 5\\n\\n        result = component._text_head(\\\"Hello World\\\")\\n\\n        assert result == \\\"Hello\\\"\\n\\n    def test_head_longer_than_text(self):\\n        \\\"\\\"\\\"Test head with length longer than text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.head_characters = 100\\n\\n        result = component._text_head(\\\"Hello\\\")\\n\\n        assert result == \\\"Hello\\\"\\n\\n    def test_head_zero_characters(self):\\n        \\\"\\\"\\\"Test head with zero characters.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.head_characters = 0\\n\\n        result = component._text_head(\\\"Hello\\\")\\n\\n        assert result == \\\"\\\"\\n\\n    def test_head_negative_characters(self):\\n        \\\"\\\"\\\"Test head with negative characters raises ValueError (Bug #4 fix).\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.head_characters = -5\\n\\n        with pytest.raises(ValueError, match=\\\"non-negative\\\"):\\n            component._text_head(\\\"Hello\\\")\\n\\n\\nclass TestTextOperationsTail:\\n    def test_tail_basic(self):\\n        \\\"\\\"\\\"Test extracting tail of text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.tail_characters = 5\\n\\n        result = component._text_tail(\\\"Hello World\\\")\\n\\n        assert result == \\\"World\\\"\\n\\n    def test_tail_longer_than_text(self):\\n        \\\"\\\"\\\"Test tail with length longer than text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.tail_characters = 100\\n\\n        result = component._text_tail(\\\"Hello\\\")\\n\\n        assert result == \\\"Hello\\\"\\n\\n    def test_tail_zero_characters(self):\\n        \\\"\\\"\\\"Test tail with zero characters.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.tail_characters = 0\\n\\n        result = component._text_tail(\\\"Hello\\\")\\n\\n        assert result == \\\"\\\"\\n\\n    def test_tail_negative_characters(self):\\n        \\\"\\\"\\\"Test tail with negative characters raises ValueError (Bug #7 fix).\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.tail_characters = -5\\n\\n        with pytest.raises(ValueError, match=\\\"non-negative\\\"):\\n            component._text_tail(\\\"Hello\\\")\\n\\n\\nclass TestTextOperationsStrip:\\n    def test_strip_both(self):\\n        \\\"\\\"\\\"Test stripping from both sides.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.strip_mode = \\\"both\\\"\\n        component.strip_characters = \\\"\\\"\\n\\n        result = component._text_strip(\\\"  hello  \\\")\\n\\n        assert result == \\\"hello\\\"\\n\\n    def test_strip_left(self):\\n        \\\"\\\"\\\"Test stripping from left side only.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.strip_mode = \\\"left\\\"\\n        component.strip_characters = \\\"\\\"\\n\\n        result = component._text_strip(\\\"  hello  \\\")\\n\\n        assert result == \\\"hello  \\\"\\n\\n    def test_strip_right(self):\\n        \\\"\\\"\\\"Test stripping from right side only.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.strip_mode = \\\"right\\\"\\n        component.strip_characters = \\\"\\\"\\n\\n        result = component._text_strip(\\\"  hello  \\\")\\n\\n        assert result == \\\"  hello\\\"\\n\\n    def test_strip_specific_characters(self):\\n        \\\"\\\"\\\"Test stripping specific characters.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.strip_mode = \\\"both\\\"\\n        component.strip_characters = \\\"xy\\\"\\n\\n        result = component._text_strip(\\\"xyhelloyx\\\")\\n\\n        assert result == \\\"hello\\\"\\n\\n\\nclass TestTextOperationsJoin:\\n    def test_join_two_texts(self):\\n        \\\"\\\"\\\"Test joining two texts.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input_2 = \\\"world\\\"\\n\\n        result = component._text_join(\\\"hello\\\")\\n\\n        assert result == \\\"hello\\\\nworld\\\"\\n\\n    def test_join_empty_first(self):\\n        \\\"\\\"\\\"Test joining with empty first text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input_2 = \\\"world\\\"\\n\\n        result = component._text_join(\\\"\\\")\\n\\n        assert result == \\\"world\\\"\\n\\n    def test_join_empty_second(self):\\n        \\\"\\\"\\\"Test joining with empty second text.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input_2 = \\\"\\\"\\n\\n        result = component._text_join(\\\"hello\\\")\\n\\n        assert result == \\\"hello\\\"\\n\\n    def test_join_both_empty(self):\\n        \\\"\\\"\\\"Test joining with both texts empty.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input_2 = \\\"\\\"\\n\\n        result = component._text_join(\\\"\\\")\\n\\n        assert result == \\\"\\\"\\n\\n\\nclass TestTextOperationsClean:\\n    def test_clean_extra_spaces(self):\\n        \\\"\\\"\\\"Test removing extra spaces.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.remove_extra_spaces = True\\n        component.remove_special_chars = False\\n        component.remove_empty_lines = False\\n\\n        result = component._text_clean(\\\"hello   world\\\")\\n\\n        assert result == \\\"hello world\\\"\\n\\n    def test_clean_special_chars(self):\\n        \\\"\\\"\\\"Test removing ALL special characters (Bug #10 fix).\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.remove_extra_spaces = False\\n        component.remove_special_chars = True\\n        component.remove_empty_lines = False\\n\\n        result = component._text_clean(\\\"hello@world#test!\\\")\\n\\n        # All special characters are removed including @ # and !\\n        assert result == \\\"helloworldtest\\\"\\n        assert \\\"@\\\" not in result\\n        assert \\\"#\\\" not in result\\n        assert \\\"!\\\" not in result\\n\\n    def test_clean_empty_lines(self):\\n        \\\"\\\"\\\"Test removing empty lines.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.remove_extra_spaces = False\\n        component.remove_special_chars = False\\n        component.remove_empty_lines = True\\n\\n        result = component._text_clean(\\\"line1\\\\n\\\\nline2\\\\n\\\\n\\\\nline3\\\")\\n\\n        assert result == \\\"line1\\\\nline2\\\\nline3\\\"\\n\\n    def test_clean_all_options(self):\\n        \\\"\\\"\\\"Test all cleaning options together.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.remove_extra_spaces = True\\n        component.remove_special_chars = True\\n        component.remove_empty_lines = True\\n\\n        result = component._text_clean(\\\"hello   @world\\\\n\\\\ntest!\\\")\\n\\n        assert \\\"  \\\" not in result\\n        assert \\\"@\\\" not in result\\n\\n\\nclass TestTextOperationsToDataFrame:\\n    def test_dataframe_basic(self):\\n        \\\"\\\"\\\"Test basic table to DataFrame conversion.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.table_separator = \\\"|\\\"\\n        component.has_header = True\\n        component.log = lambda _: None\\n\\n        table = \\\"| Name | Age |\\\\n| John | 25 |\\\\n| Jane | 30 |\\\"\\n        result = component._text_to_dataframe(table)\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 2\\n        assert list(result.columns) == [\\\"Name\\\", \\\"Age\\\"]\\n\\n    def test_dataframe_no_header(self):\\n        \\\"\\\"\\\"Test DataFrame conversion without header.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.table_separator = \\\"|\\\"\\n        component.has_header = False\\n        component.log = lambda _: None\\n\\n        table = \\\"| John | 25 |\\\\n| Jane | 30 |\\\"\\n        result = component._text_to_dataframe(table)\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 2\\n        assert \\\"col_0\\\" in result.columns\\n\\n    def test_dataframe_empty_input(self):\\n        \\\"\\\"\\\"Test DataFrame conversion with empty input.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.table_separator = \\\"|\\\"\\n        component.has_header = True\\n        component.log = lambda _: None\\n\\n        result = component._text_to_dataframe(\\\"\\\")\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 0\\n\\n    def test_dataframe_custom_separator(self):\\n        \\\"\\\"\\\"Test DataFrame conversion with custom separator.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.table_separator = \\\",\\\"\\n        component.has_header = True\\n        component.log = lambda _: None\\n\\n        table = \\\"Name,Age\\\\nJohn,25\\\\nJane,30\\\"\\n        result = component._text_to_dataframe(table)\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 2\\n\\n\\nclass TestTextOperationsUpdateBuildConfig:\\n    def test_update_build_config_word_count(self):\\n        \\\"\\\"\\\"Test build config update for Word Count operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        build_config = {\\n            field: {\\\"show\\\": True}\\n            for field in [\\\"count_words\\\", \\\"count_characters\\\", \\\"count_lines\\\", \\\"case_type\\\", \\\"search_pattern\\\"]\\n        }\\n\\n        result = component.update_build_config(build_config, [{\\\"name\\\": \\\"Word Count\\\"}], \\\"operation\\\")\\n\\n        assert result[\\\"count_words\\\"][\\\"show\\\"] is True\\n        assert result[\\\"count_characters\\\"][\\\"show\\\"] is True\\n        assert result[\\\"count_lines\\\"][\\\"show\\\"] is True\\n        assert result[\\\"case_type\\\"][\\\"show\\\"] is False\\n        assert result[\\\"search_pattern\\\"][\\\"show\\\"] is False\\n\\n    def test_update_build_config_case_conversion(self):\\n        \\\"\\\"\\\"Test build config update for Case Conversion operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        build_config = {field: {\\\"show\\\": True} for field in [\\\"count_words\\\", \\\"case_type\\\", \\\"search_pattern\\\"]}\\n\\n        result = component.update_build_config(build_config, [{\\\"name\\\": \\\"Case Conversion\\\"}], \\\"operation\\\")\\n\\n        assert result[\\\"case_type\\\"][\\\"show\\\"] is True\\n        assert result[\\\"count_words\\\"][\\\"show\\\"] is False\\n\\n    def test_update_build_config_text_replace(self):\\n        \\\"\\\"\\\"Test build config update for Text Replace operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        build_config = {\\n            field: {\\\"show\\\": True} for field in [\\\"search_pattern\\\", \\\"replacement_text\\\", \\\"use_regex\\\", \\\"case_type\\\"]\\n        }\\n\\n        result = component.update_build_config(build_config, [{\\\"name\\\": \\\"Text Replace\\\"}], \\\"operation\\\")\\n\\n        assert result[\\\"search_pattern\\\"][\\\"show\\\"] is True\\n        assert result[\\\"replacement_text\\\"][\\\"show\\\"] is True\\n        assert result[\\\"use_regex\\\"][\\\"show\\\"] is True\\n        assert result[\\\"case_type\\\"][\\\"show\\\"] is False\\n\\n\\nclass TestTextOperationsUpdateOutputs:\\n    def test_update_outputs_word_count(self):\\n        \\\"\\\"\\\"Test output update for Word Count operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        frontend_node = {\\\"outputs\\\": []}\\n\\n        result = component.update_outputs(frontend_node, \\\"operation\\\", [{\\\"name\\\": \\\"Word Count\\\"}])\\n\\n        assert len(result[\\\"outputs\\\"]) == 1\\n        assert result[\\\"outputs\\\"][0].name == \\\"data\\\"\\n\\n    def test_update_outputs_dataframe(self):\\n        \\\"\\\"\\\"Test output update for Text to DataFrame operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        frontend_node = {\\\"outputs\\\": []}\\n\\n        result = component.update_outputs(frontend_node, \\\"operation\\\", [{\\\"name\\\": \\\"Text to DataFrame\\\"}])\\n\\n        assert len(result[\\\"outputs\\\"]) == 1\\n        assert result[\\\"outputs\\\"][0].name == \\\"dataframe\\\"\\n\\n    def test_update_outputs_text_join(self):\\n        \\\"\\\"\\\"Test output update for Text Join operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        frontend_node = {\\\"outputs\\\": []}\\n\\n        result = component.update_outputs(frontend_node, \\\"operation\\\", [{\\\"name\\\": \\\"Text Join\\\"}])\\n\\n        assert len(result[\\\"outputs\\\"]) == 2\\n        assert result[\\\"outputs\\\"][0].name == \\\"text\\\"\\n        assert result[\\\"outputs\\\"][1].name == \\\"message\\\"\\n\\n    def test_update_outputs_message_operations(self):\\n        \\\"\\\"\\\"Test output update for message-returning operations.\\\"\\\"\\\"\\n        component = TextOperations()\\n\\n        for operation in [\\n            \\\"Case Conversion\\\",\\n            \\\"Text Replace\\\",\\n            \\\"Text Extract\\\",\\n            \\\"Text Head\\\",\\n            \\\"Text Tail\\\",\\n            \\\"Text Strip\\\",\\n            \\\"Text Clean\\\",\\n        ]:\\n            frontend_node = {\\\"outputs\\\": []}\\n            result = component.update_outputs(frontend_node, \\\"operation\\\", [{\\\"name\\\": operation}])\\n\\n            assert len(result[\\\"outputs\\\"]) == 1\\n            assert result[\\\"outputs\\\"][0].name == \\\"message\\\"\\n\\n\\nclass TestTextOperationsOutputMethods:\\n    def test_get_data_word_count(self):\\n        \\\"\\\"\\\"Test get_data method for Word Count.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.operation = [{\\\"name\\\": \\\"Word Count\\\"}]\\n        component.text_input = \\\"hello world\\\"\\n        component.count_words = True\\n        component.count_characters = True\\n        component.count_lines = True\\n\\n        result = component.get_data()\\n\\n        assert isinstance(result, Data)\\n        assert \\\"word_count\\\" in result.data\\n\\n    def test_get_data_non_word_count(self):\\n        \\\"\\\"\\\"Test get_data method for non-Word Count operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.operation = [{\\\"name\\\": \\\"Case Conversion\\\"}]\\n        component.text_input = \\\"hello\\\"\\n\\n        result = component.get_data()\\n\\n        assert isinstance(result, Data)\\n        assert result.data == {}\\n\\n    def test_get_message(self):\\n        \\\"\\\"\\\"Test get_message method.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.operation = [{\\\"name\\\": \\\"Case Conversion\\\"}]\\n        component.text_input = \\\"hello\\\"\\n        component.case_type = \\\"uppercase\\\"\\n\\n        result = component.get_message()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"HELLO\\\"\\n\\n    def test_get_dataframe(self):\\n        \\\"\\\"\\\"Test get_dataframe method.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.operation = [{\\\"name\\\": \\\"Text to DataFrame\\\"}]\\n        component.text_input = \\\"| A | B |\\\\n| 1 | 2 |\\\"\\n        component.table_separator = \\\"|\\\"\\n        component.has_header = True\\n        component.log = lambda _: None\\n\\n        result = component.get_dataframe()\\n\\n        assert isinstance(result, DataFrame)\\n\\n    def test_get_text(self):\\n        \\\"\\\"\\\"Test get_text method.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.operation = [{\\\"name\\\": \\\"Text Join\\\"}]\\n        component.text_input = \\\"hello\\\"\\n        component.text_input_2 = \\\"world\\\"\\n\\n        result = component.get_text()\\n\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"hello\\\\nworld\\\"\\n\\n\\n# ============================================================================\\n# Bug Regression Tests\\n# These tests ensure reported bugs remain fixed and don't regress.\\n# ============================================================================\\n\\n\\nclass TestBugFixWordCountEmptyText:\\n    \\\"\\\"\\\"Bug #2: Word Count should return zeros for empty text.\\\"\\\"\\\"\\n\\n    def test_word_count_empty_string_returns_zeros(self):\\n        \\\"\\\"\\\"Empty text should return all zeros, not non-zero values.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.count_words = True\\n        component.count_characters = True\\n        component.count_lines = True\\n\\n        result = component._word_count(\\\"\\\")\\n\\n        assert result[\\\"word_count\\\"] == 0\\n        assert result[\\\"unique_words\\\"] == 0\\n        assert result[\\\"character_count\\\"] == 0\\n        assert result[\\\"character_count_no_spaces\\\"] == 0\\n        assert result[\\\"line_count\\\"] == 0\\n        assert result[\\\"non_empty_lines\\\"] == 0\\n\\n    def test_word_count_whitespace_only_returns_zeros(self):\\n        \\\"\\\"\\\"Whitespace-only text should return zeros.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.count_words = True\\n        component.count_characters = True\\n        component.count_lines = True\\n\\n        result = component._word_count(\\\"   \\\\n\\\\t\\\\n   \\\")\\n\\n        assert result[\\\"word_count\\\"] == 0\\n        assert result[\\\"unique_words\\\"] == 0\\n        assert result[\\\"character_count\\\"] == 0\\n        assert result[\\\"character_count_no_spaces\\\"] == 0\\n        assert result[\\\"line_count\\\"] == 0\\n        assert result[\\\"non_empty_lines\\\"] == 0\\n\\n    def test_process_text_allows_empty_for_word_count(self):\\n        \\\"\\\"\\\"process_text should allow empty text for Word Count operation.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input = \\\"\\\"\\n        component.operation = [{\\\"name\\\": \\\"Word Count\\\"}]\\n        component.count_words = True\\n        component.count_characters = True\\n        component.count_lines = True\\n\\n        result = component.process_text()\\n\\n        assert result is not None\\n        assert result[\\\"word_count\\\"] == 0\\n\\n\\nclass TestBugFixTextJoinEmptyFirst:\\n    \\\"\\\"\\\"Bug #9: Text Join should return second text when first is empty.\\\"\\\"\\\"\\n\\n    def test_process_text_allows_empty_for_text_join(self):\\n        \\\"\\\"\\\"process_text should allow empty first text for Text Join.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.text_input = \\\"\\\"\\n        component.operation = [{\\\"name\\\": \\\"Text Join\\\"}]\\n        component.text_input_2 = \\\"world\\\"\\n\\n        result = component.process_text()\\n\\n        assert result == \\\"world\\\"\\n\\n\\nclass TestBugFixTextStripTabs:\\n    \\\"\\\"\\\"Bug #8: Text Strip should remove tab characters.\\\"\\\"\\\"\\n\\n    def test_strip_removes_tabs(self):\\n        \\\"\\\"\\\"Strip should remove tabs when using default whitespace stripping.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.strip_mode = \\\"both\\\"\\n        component.strip_characters = \\\"\\\"\\n\\n        result = component._text_strip(\\\"\\\\t\\\\thello world\\\\t\\\\t\\\")\\n\\n        assert result == \\\"hello world\\\"\\n\\n    def test_strip_removes_mixed_whitespace(self):\\n        \\\"\\\"\\\"Strip should remove all whitespace types including tabs and newlines.\\\"\\\"\\\"\\n        component = TextOperations()\\n        component.strip_mode = \\\"both\\\"\\n        component.strip_characters = \\\"\\\"\\n\\n        result = component._text_strip(\\\"\\\\n\\\\t  hello world  \\\\t\\\\n\\\")\\n\\n        assert result == \\\"hello world\\\"\\n\\n\\nclass TestBugFixDataFrameHeaderValidation:\\n    \\\"\\\"\\\"Bug #11: DataFrame should validate header column count matches data.\\\"\\\"\\\"\\n\\n    def test_header_column_mismatch_raises_error(self):\\n        \\\"\\\"\\\"Mismatched header/data columns should raise clear error.\\\"\\\"\\\"\\n        component = TextOperations()\\n\\n        rows = [\\n            [\\\"Name Age City\\\"],  # 1 column (malformed header)\\n            [\\\"John\\\", \\\"30\\\", \\\"NYC\\\"],  # 3 columns\\n        ]\\n\\n        with pytest.raises(ValueError, match=\\\"Header mismatch\\\"):\\n            component._create_dataframe(rows, has_header=True)\\n\\n    def test_error_message_includes_column_counts(self):\\n        \\\"\\\"\\\"Error message should include both column counts.\\\"\\\"\\\"\\n        component = TextOperations()\\n\\n        rows = [\\n            [\\\"Name\\\"],  # 1 column\\n            [\\\"John\\\", \\\"30\\\"],  # 2 columns\\n        ]\\n\\n        with pytest.raises(ValueError, match=r\\\"1 column\\\\(s\\\\) in header.*2 column\\\\(s\\\\) in data\\\"):\\n            component._create_dataframe(rows, has_header=True)\\n\\n\\nclass TestBugFixInputValidation:\\n    \\\"\\\"\\\"Tests for input validation improvements.\\\"\\\"\\\"\\n\\n    def test_head_characters_has_range_spec(self):\\n        \\\"\\\"\\\"head_characters should have range_spec with min=0.\\\"\\\"\\\"\\n        component = TextOperations()\\n\\n        head_input = next(\\n            (inp for inp in component.inputs if inp.name == \\\"head_characters\\\"),\\n            None,\\n        )\\n\\n        assert head_input is not None\\n        assert head_input.range_spec is not None\\n        assert head_input.range_spec.min == 0\\n\\n    def test_tail_characters_has_range_spec(self):\\n        \\\"\\\"\\\"tail_characters should have range_spec with min=0.\\\"\\\"\\\"\\n        component = TextOperations()\\n\\n        tail_input = next(\\n            (inp for inp in component.inputs if inp.name == \\\"tail_characters\\\"),\\n            None,\\n        )\\n\\n        assert tail_input is not None\\n        assert tail_input.range_spec is not None\\n        assert tail_input.range_spec.min == 0\\n\\n    def test_text_input_uses_message_text_input(self):\\n        \\\"\\\"\\\"Bug #1: text_input should use MessageTextInput type.\\\"\\\"\\\"\\n        component = TextOperations()\\n\\n        text_input = next(\\n            (inp for inp in component.inputs if inp.name == \\\"text_input\\\"),\\n            None,\\n        )\\n\\n        assert text_input is not None\\n        # MessageTextInput is the correct type for variable input support\\n        assert text_input.name == \\\"text_input\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/processing/test_type_converter_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"67e6cec72af75ef5157d67e5cae236d59d0d941ce39ee29a72fdf5f0dba8822a\",\"content\":\"import json\\nfrom io import StringIO\\n\\nimport pandas as pd\\nimport pytest\\nfrom lfx.components.processing.converter import TypeConverterComponent\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestTypeConverterComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return TypeConverterComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    # Message to other types\\n    def test_message_to_message(self, component_class):\\n        \\\"\\\"\\\"Test converting Message to Message.\\\"\\\"\\\"\\n        component = component_class(input_data=Message(text=\\\"Hello World\\\"), output_type=\\\"Message\\\")\\n        result = component.convert_to_message()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Hello World\\\"\\n\\n    def test_message_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting Message to Data.\\\"\\\"\\\"\\n        component = component_class(input_data=Message(text=\\\"Hello\\\"), output_type=\\\"Data\\\")\\n        result = component.convert_to_data()\\n        assert isinstance(result, Data)\\n        assert result.data == {\\\"text\\\": \\\"Hello\\\"}\\n\\n    def test_message_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting Message to DataFrame.\\\"\\\"\\\"\\n        component = component_class(input_data=Message(text=\\\"Hello\\\"), output_type=\\\"DataFrame\\\")\\n        result = component.convert_to_dataframe()\\n        assert isinstance(result, DataFrame)\\n        assert list(result.columns) == [\\\"text\\\"]\\n        assert result.iloc[0][\\\"text\\\"] == \\\"Hello\\\"\\n\\n    # Data to other types\\n    def test_data_to_message(self, component_class):\\n        \\\"\\\"\\\"Test converting Data to Message.\\\"\\\"\\\"\\n        component = component_class(input_data=Data(data={\\\"text\\\": \\\"Hello World\\\"}), output_type=\\\"Message\\\")\\n        result = component.convert_to_message()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"Hello World\\\"\\n\\n    def test_data_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting Data to Data.\\\"\\\"\\\"\\n        component = component_class(input_data=Data(data={\\\"key\\\": \\\"value\\\"}), output_type=\\\"Data\\\")\\n        result = component.convert_to_data()\\n        assert isinstance(result, Data)\\n        assert result.data == {\\\"key\\\": \\\"value\\\"}\\n\\n    def test_data_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting Data to DataFrame.\\\"\\\"\\\"\\n        component = component_class(input_data=Data(data={\\\"text\\\": \\\"Hello World\\\"}), output_type=\\\"DataFrame\\\")\\n        result = component.convert_to_dataframe()\\n        assert isinstance(result, DataFrame)\\n        assert \\\"text\\\" in result.columns\\n        assert result.iloc[0][\\\"text\\\"] == \\\"Hello World\\\"\\n\\n    # DataFrame to other types\\n    def test_dataframe_to_message(self, component_class):\\n        \\\"\\\"\\\"Test converting DataFrame to Message.\\\"\\\"\\\"\\n        df_data = pd.DataFrame({\\\"col1\\\": [\\\"Hello\\\"], \\\"col2\\\": [\\\"World\\\"]})\\n        component = component_class(input_data=DataFrame(data=df_data), output_type=\\\"Message\\\")\\n        result = component.convert_to_message()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"| col1   | col2   |\\\\n|:-------|:-------|\\\\n| Hello  | World  |\\\"\\n\\n    def test_dataframe_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting DataFrame to Data.\\\"\\\"\\\"\\n        df_data = pd.DataFrame({\\\"col1\\\": [\\\"Hello\\\"]})\\n        component = component_class(input_data=DataFrame(data=df_data), output_type=\\\"Data\\\")\\n        result = component.convert_to_data()\\n        assert isinstance(result, Data)\\n        assert isinstance(result.data, dict)\\n\\n    def test_dataframe_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting DataFrame to DataFrame.\\\"\\\"\\\"\\n        df_data = pd.DataFrame({\\\"col1\\\": [\\\"Hello\\\"], \\\"col2\\\": [\\\"World\\\"]})\\n        component = component_class(input_data=DataFrame(data=df_data), output_type=\\\"DataFrame\\\")\\n        result = component.convert_to_dataframe()\\n        assert isinstance(result, DataFrame)\\n        assert \\\"col1\\\" in result.columns\\n        assert \\\"col2\\\" in result.columns\\n        assert result.iloc[0][\\\"col1\\\"] == \\\"Hello\\\"\\n        assert result.iloc[0][\\\"col2\\\"] == \\\"World\\\"\\n\\n    def test_update_outputs(self, component_class):\\n        \\\"\\\"\\\"Test the update_outputs method.\\\"\\\"\\\"\\n        component = component_class(input_data=Message(text=\\\"Hello\\\"), output_type=\\\"Message\\\")\\n        frontend_node = {\\\"outputs\\\": []}\\n\\n        # Test with Message output\\n        updated = component.update_outputs(frontend_node, \\\"output_type\\\", \\\"Message\\\")\\n        assert len(updated[\\\"outputs\\\"]) == 1\\n        assert updated[\\\"outputs\\\"][0][\\\"name\\\"] == \\\"message_output\\\"\\n\\n        # Test with Data output\\n        updated = component.update_outputs(frontend_node, \\\"output_type\\\", \\\"Data\\\")\\n        assert len(updated[\\\"outputs\\\"]) == 1\\n        assert updated[\\\"outputs\\\"][0][\\\"name\\\"] == \\\"data_output\\\"\\n\\n        # Test with DataFrame output\\n        updated = component.update_outputs(frontend_node, \\\"output_type\\\", \\\"DataFrame\\\")\\n        assert len(updated[\\\"outputs\\\"]) == 1\\n        assert updated[\\\"outputs\\\"][0][\\\"name\\\"] == \\\"dataframe_output\\\"\\n\\n    def test_message_with_valid_json_text_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting Message to Data.\\\"\\\"\\\"\\n        valid_json_text = '{\\\"foo\\\": \\\"bar\\\"}'\\n        component = component_class(input_data=Message(text=valid_json_text), output_type=\\\"Data\\\", auto_parse=True)\\n        result = component.convert_to_data()\\n        assert isinstance(result, Data)\\n        assert result.data == json.loads(valid_json_text)\\n\\n    def test_message_with_invalid_json_text_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting Message to Data.\\\"\\\"\\\"\\n        invalid_json_text = '{\\\"foo\\\", \\\"bar\\\"}'\\n        component = component_class(input_data=Message(text=invalid_json_text), output_type=\\\"Data\\\", auto_parse=True)\\n        result = component.convert_to_data()\\n        assert isinstance(result, Data)\\n        assert isinstance(result.data[\\\"text\\\"], str)\\n        assert result.data == {\\\"text\\\": invalid_json_text}\\n\\n    def test_message_with_valid_json_array_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting Message with JSON array to Data.\\\"\\\"\\\"\\n        valid_json_text = '[{\\\"name\\\": \\\"Ana\\\", \\\"age\\\": 28}, {\\\"name\\\": \\\"Bruno\\\", \\\"age\\\": 34}]'\\n        component = component_class(input_data=Message(text=valid_json_text), output_type=\\\"Data\\\", auto_parse=True)\\n        result = component.convert_to_data()\\n\\n        expected_data = {\\\"records\\\": json.loads(valid_json_text)}\\n\\n        assert isinstance(result, Data)\\n        assert result.data == expected_data\\n\\n    def test_message_with_valid_csv_to_data(self, component_class):\\n        \\\"\\\"\\\"Test converting Message with CSV to Data.\\\"\\\"\\\"\\n        valid_csv_text = \\\"name,age,email\\\\nAna,28,ana@email.com\\\\nBruno,34,bruno@email.com\\\\nCarla,22,carla@email.com\\\\n\\\"\\n        component = component_class(input_data=Message(text=valid_csv_text), output_type=\\\"Data\\\", auto_parse=True)\\n        result = component.convert_to_data()\\n\\n        expected_data = {\\n            \\\"records\\\": [\\n                {\\\"name\\\": \\\"Ana\\\", \\\"age\\\": 28, \\\"email\\\": \\\"ana@email.com\\\"},\\n                {\\\"name\\\": \\\"Bruno\\\", \\\"age\\\": 34, \\\"email\\\": \\\"bruno@email.com\\\"},\\n                {\\\"name\\\": \\\"Carla\\\", \\\"age\\\": 22, \\\"email\\\": \\\"carla@email.com\\\"},\\n            ]\\n        }\\n\\n        assert isinstance(result, Data)\\n        assert result.data == expected_data\\n\\n    def test_message_with_valid_csv_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting Message to DataFrame.\\\"\\\"\\\"\\n        valid_csv_text = (\\n            \\\"name,age,email,city\\\\n\\\"\\n            \\\"Ana,28,ana@email.com,S\u00e3o Paulo\\\\n\\\"\\n            \\\"Bruno,34,bruno@email.com,Rio de Janeiro\\\\n\\\"\\n            \\\"Carla,22,carla@email.com,Belo Horizonte\\\\n\\\"\\n            \\\"Diego,40,diego@email.com,Curitiba\\\\n\\\"\\n            \\\"Elisa,31,elisa@email.com,Porto Alegre\\\\n\\\"\\n        )\\n        component = component_class(input_data=Message(text=valid_csv_text), output_type=\\\"DataFrame\\\", auto_parse=True)\\n        result = component.convert_to_dataframe()\\n        expected = pd.read_csv(StringIO(valid_csv_text))\\n        assert isinstance(result, DataFrame)\\n        assert list(result.columns) == [\\\"name\\\", \\\"age\\\", \\\"email\\\", \\\"city\\\"]\\n        pd.testing.assert_frame_equal(result, expected)\\n\\n    def test_message_with_valid_json_object_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting Message with JSON object to DataFrame.\\\"\\\"\\\"\\n        valid_json_text = '{\\\"name\\\": \\\"Ana\\\", \\\"age\\\": 28, \\\"email\\\": \\\"ana@email.com\\\", \\\"city\\\": \\\"S\u00e3o Paulo\\\"}'\\n        component = component_class(input_data=Message(text=valid_json_text), output_type=\\\"DataFrame\\\", auto_parse=True)\\n        result = component.convert_to_dataframe()\\n\\n        expected_data = [json.loads(valid_json_text)]\\n        expected = pd.DataFrame(expected_data)\\n\\n        assert isinstance(result, DataFrame)\\n        assert list(result.columns) == [\\\"name\\\", \\\"age\\\", \\\"email\\\", \\\"city\\\"]\\n        pd.testing.assert_frame_equal(result, expected)\\n\\n    def test_message_with_valid_json_array_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting Message with JSON array to DataFrame.\\\"\\\"\\\"\\n        valid_json_text = \\\"\\\"\\\"[\\n            {\\\"name\\\": \\\"Ana\\\", \\\"age\\\": 28, \\\"email\\\": \\\"ana@email.com\\\", \\\"city\\\": \\\"S\u00e3o Paulo\\\"},\\n            {\\\"name\\\": \\\"Bruno\\\", \\\"age\\\": 34, \\\"email\\\": \\\"bruno@email.com\\\", \\\"city\\\": \\\"Rio de Janeiro\\\"},\\n            {\\\"name\\\": \\\"Carla\\\", \\\"age\\\": 22, \\\"email\\\": \\\"carla@email.com\\\", \\\"city\\\": \\\"Belo Horizonte\\\"}\\n        ]\\\"\\\"\\\"\\n        component = component_class(input_data=Message(text=valid_json_text), output_type=\\\"DataFrame\\\", auto_parse=True)\\n        result = component.convert_to_dataframe()\\n\\n        expected_data = json.loads(valid_json_text)\\n        expected = pd.DataFrame(expected_data)\\n\\n        assert isinstance(result, DataFrame)\\n        assert list(result.columns) == [\\\"name\\\", \\\"age\\\", \\\"email\\\", \\\"city\\\"]\\n        assert len(result) == 3\\n        pd.testing.assert_frame_equal(result, expected)\\n\\n    def test_message_with_compact_json_array_to_dataframe(self, component_class):\\n        \\\"\\\"\\\"Test converting Message with compact JSON array to DataFrame.\\\"\\\"\\\"\\n        valid_json_text = '[{\\\"name\\\":\\\"Ana\\\",\\\"age\\\":28},{\\\"name\\\":\\\"Bruno\\\",\\\"age\\\":34},{\\\"name\\\":\\\"Carla\\\",\\\"age\\\":22}]'\\n        component = component_class(input_data=Message(text=valid_json_text), output_type=\\\"DataFrame\\\", auto_parse=True)\\n        result = component.convert_to_dataframe()\\n\\n        expected_data = json.loads(valid_json_text)\\n        expected = pd.DataFrame(expected_data)\\n\\n        assert isinstance(result, DataFrame)\\n        assert list(result.columns) == [\\\"name\\\", \\\"age\\\"]\\n        assert len(result) == 3\\n        pd.testing.assert_frame_equal(result, expected)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/prompts/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/prompts/test_validate_prompt_mustache.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4326b3a09c4f1f9bcb210ed07c966e08867eefaca420dac3a411b0c476913b54\",\"content\":\"\\\"\\\"\\\"Tests for validate_prompt function with mustache templates.\\n\\nThese tests ensure that complex mustache syntax is rejected during the \\\"Check & Save\\\"\\nvalidation phase, not just at runtime. This prevents users from saving templates that\\nare guaranteed to fail at runtime.\\n\\nRegression test for: Complex mustache patterns like {{#section}}{{/section}} were being\\naccepted during save but causing \\\"Complex mustache syntax is not allowed\\\" errors at runtime.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.base.prompts.api_utils import validate_prompt\\n\\n\\nclass TestValidatePromptMustache:\\n    \\\"\\\"\\\"Test validate_prompt function with mustache templates.\\\"\\\"\\\"\\n\\n    def test_simple_variable_accepted(self):\\n        \\\"\\\"\\\"Test that simple mustache variables are accepted.\\\"\\\"\\\"\\n        result = validate_prompt(\\\"Hello {{name}}!\\\", is_mustache=True)\\n        assert result == [\\\"name\\\"]\\n\\n    def test_multiple_simple_variables_accepted(self):\\n        \\\"\\\"\\\"Test that multiple simple variables are accepted.\\\"\\\"\\\"\\n        result = validate_prompt(\\\"Hello {{first_name}} {{last_name}}!\\\", is_mustache=True)\\n        assert sorted(result) == [\\\"first_name\\\", \\\"last_name\\\"]\\n\\n    def test_underscore_variables_accepted(self):\\n        \\\"\\\"\\\"Test that variables with underscores are accepted.\\n\\n        A leading underscore is rejected -- see TestValidatePromptReservedPrefix in\\n        test_validate_prompt_reserved_prefix.py. Underscores anywhere else are fine.\\n        \\\"\\\"\\\"\\n        result = validate_prompt(\\\"{{user_name}} - {{private_}}\\\", is_mustache=True)\\n        assert sorted(result) == [\\\"private_\\\", \\\"user_name\\\"]\\n\\n    def test_numeric_suffix_variables_accepted(self):\\n        \\\"\\\"\\\"Test that variables with numeric suffixes are accepted.\\\"\\\"\\\"\\n        result = validate_prompt(\\\"{{var1}} {{var2}} {{price_100}}\\\", is_mustache=True)\\n        assert sorted(result) == [\\\"price_100\\\", \\\"var1\\\", \\\"var2\\\"]\\n\\n    def test_empty_template_accepted(self):\\n        \\\"\\\"\\\"Test that empty template is accepted.\\\"\\\"\\\"\\n        result = validate_prompt(\\\"\\\", is_mustache=True)\\n        assert result == []\\n\\n    def test_no_variables_accepted(self):\\n        \\\"\\\"\\\"Test that template without variables is accepted.\\\"\\\"\\\"\\n        result = validate_prompt(\\\"Hello World!\\\", is_mustache=True)\\n        assert result == []\\n\\n    # Regression tests for the bug: complex syntax should be rejected during validation\\n    # These patterns were previously accepted during \\\"Check & Save\\\" but failed at runtime\\n\\n    def test_section_syntax_rejected(self):\\n        \\\"\\\"\\\"Test that section syntax ({{#section}}{{/section}}) is rejected.\\n\\n        This is the main regression test for the bug where closed sections were\\n        accepted during save but caused runtime errors.\\n        \\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{#section}}content{{/section}}\\\", is_mustache=True)\\n\\n    def test_conditional_syntax_rejected(self):\\n        \\\"\\\"\\\"Test that conditional syntax is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{#if}}show this{{/if}}\\\", is_mustache=True)\\n\\n    def test_inverted_section_rejected(self):\\n        \\\"\\\"\\\"Test that inverted section syntax ({{^section}}) is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{^empty}}not empty{{/empty}}\\\", is_mustache=True)\\n\\n    def test_unescaped_variable_rejected(self):\\n        \\\"\\\"\\\"Test that unescaped variable syntax ({{&var}}) is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{&html_content}}\\\", is_mustache=True)\\n\\n    def test_triple_braces_rejected(self):\\n        \\\"\\\"\\\"Test that triple braces ({{{var}}}) for unescaped HTML are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{{unescaped}}}\\\", is_mustache=True)\\n\\n    def test_partial_syntax_rejected(self):\\n        \\\"\\\"\\\"Test that partial syntax ({{>partial}}) is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{>header}}\\\", is_mustache=True)\\n\\n    def test_comment_syntax_rejected(self):\\n        \\\"\\\"\\\"Test that comment syntax ({{!comment}}) is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{!this is a comment}}\\\", is_mustache=True)\\n\\n    def test_current_context_rejected(self):\\n        \\\"\\\"\\\"Test that current context syntax ({{.}}) is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{.}}\\\", is_mustache=True)\\n\\n    def test_nested_sections_rejected(self):\\n        \\\"\\\"\\\"Test that nested sections are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{#outer}}{{#inner}}content{{/inner}}{{/outer}}\\\", is_mustache=True)\\n\\n    def test_loop_syntax_rejected(self):\\n        \\\"\\\"\\\"Test that loop syntax is rejected (sections are used for loops in Mustache).\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{#items}}{{name}}{{/items}}\\\", is_mustache=True)\\n\\n    # Tests for invalid variable names\\n\\n    def test_dot_notation_rejected(self):\\n        \\\"\\\"\\\"Test that dot notation ({{user.name}}) is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_prompt(\\\"{{user.name}}\\\", is_mustache=True)\\n\\n    def test_spaces_in_variable_rejected(self):\\n        \\\"\\\"\\\"Test that spaces in variable names are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_prompt(\\\"{{ variable with spaces }}\\\", is_mustache=True)\\n\\n    def test_variable_starting_with_number_rejected(self):\\n        \\\"\\\"\\\"Test that variables starting with numbers are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_prompt(\\\"{{123abc}}\\\", is_mustache=True)\\n\\n    def test_empty_variable_rejected(self):\\n        \\\"\\\"\\\"Test that empty variables ({{}}) are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_prompt(\\\"{{}}\\\", is_mustache=True)\\n\\n    def test_special_characters_rejected(self):\\n        \\\"\\\"\\\"Test that special characters in variable names are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_prompt(\\\"{{price-$100}}\\\", is_mustache=True)\\n\\n    # Tests for malformed syntax (unclosed tags)\\n\\n    def test_unclosed_section_rejected(self):\\n        \\\"\\\"\\\"Test that unclosed section tags are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{#section}}\\\", is_mustache=True)\\n\\n    def test_unclosed_inverted_section_rejected(self):\\n        \\\"\\\"\\\"Test that unclosed inverted section tags are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{^section}}\\\", is_mustache=True)\\n\\n    def test_closing_tag_without_opening_rejected(self):\\n        \\\"\\\"\\\"Test that closing tags without opening are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"{{/section}}\\\", is_mustache=True)\\n\\n    # Tests for mixed content\\n\\n    def test_simple_variable_with_text(self):\\n        \\\"\\\"\\\"Test simple variable mixed with text content.\\\"\\\"\\\"\\n        result = validate_prompt(\\\"Dear {{name}}, your order {{order_id}} is ready.\\\", is_mustache=True)\\n        assert sorted(result) == [\\\"name\\\", \\\"order_id\\\"]\\n\\n    def test_complex_syntax_mixed_with_simple_rejected(self):\\n        \\\"\\\"\\\"Test that complex syntax mixed with simple variables is still rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_prompt(\\\"Hello {{name}}! {{#show}}extra{{/show}}\\\", is_mustache=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/prompts/test_validate_prompt_reserved_prefix.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1c25ae7fc202c3e2616cf77a468b96db7a2cf96699c960ac02644696e214be03\",\"content\":\"\\\"\\\"\\\"Tests for the reserved `_*` namespace in prompt variable names.\\n\\nKeys prefixed with an underscore are node-template metadata (`_type`,\\n`_frontend_node_flow_id`, ...), not component fields. The frontend filters that namespace\\nout of every render path, so a variable such as `{_x}` used to be accepted by\\n`validate_prompt` and written into the template while never producing an input field or a\\nhandle -- it could not be given a value and resolved to an empty string at run time.\\n\\nRegression test for LE-2144. The case list is mirrored by the frontend unit test for\\n`isReservedVariableName`; keep the two in sync.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.base.prompts.api_utils import validate_prompt\\n\\nREJECTED = [\\\"_x\\\", \\\"_\\\", \\\"__y\\\", \\\"_type\\\", \\\"_frontend_node_flow_id\\\"]\\nACCEPTED = [\\\"var\\\", \\\"a_b\\\", \\\"var_1\\\", \\\"private_\\\", \\\"x\\\"]\\n\\n\\nclass TestValidatePromptReservedPrefix:\\n    \\\"\\\"\\\"Variable names starting with an underscore are rejected in both syntaxes.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"name\\\", REJECTED)\\n    def test_leading_underscore_rejected_fstring(self, name):\\n        with pytest.raises(ValueError, match=\\\"cannot start with `_`\\\"):\\n            validate_prompt(f\\\"Hello {{{name}}}, how are you?\\\")\\n\\n    @pytest.mark.parametrize(\\\"name\\\", REJECTED)\\n    def test_leading_underscore_rejected_mustache(self, name):\\n        with pytest.raises(ValueError, match=\\\"cannot start with `_`\\\"):\\n            validate_prompt(f\\\"Hello {{{{{name}}}}}, how are you?\\\", is_mustache=True)\\n\\n    @pytest.mark.parametrize(\\\"name\\\", ACCEPTED)\\n    def test_regular_names_still_accepted_fstring(self, name):\\n        assert validate_prompt(f\\\"Hello {{{name}}}, how are you?\\\") == [name]\\n\\n    @pytest.mark.parametrize(\\\"name\\\", ACCEPTED)\\n    def test_regular_names_still_accepted_mustache(self, name):\\n        assert validate_prompt(f\\\"Hello {{{{{name}}}}}, how are you?\\\", is_mustache=True) == [name]\\n\\n    def test_error_names_only_the_offending_variables(self):\\n        \\\"\\\"\\\"A mixed template reports the rejected names, not every variable in it.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=r\\\"Invalid input variables: `_a`, `_b`\\\\.\\\") as exc_info:\\n            validate_prompt(\\\"{name} {_a} {city} {_b}\\\")\\n        assert \\\"name\\\" not in str(exc_info.value).split(\\\".\\\")[0]\\n\\n    def test_names_are_backticked_so_markdown_keeps_the_underscores(self):\\n        \\\"\\\"\\\"The frontend renders this message with react-markdown.\\n\\n        Bare underscores pair up into emphasis markers there, so `_x` would reach the\\n        user as `x` and the rule itself would read \\\"cannot start with ''\\\".\\n        \\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid input variables\\\") as exc_info:\\n            validate_prompt(\\\"{_a} {_b}\\\")\\n        message = str(exc_info.value)\\n        assert \\\"`_a`\\\" in message\\n        assert \\\"`_b`\\\" in message\\n        assert \\\"start with `_`\\\" in message\\n\\n    def test_metadata_key_no_longer_reaches_the_template_writer(self):\\n        \\\"\\\"\\\"`{_type}` used to pass validation and then fail with an opaque HTTP 500.\\n\\n        `add_new_variables_to_template` read `template[\\\"_type\\\"][\\\"value\\\"]` on the plain\\n        string that holds the node type, raising `string indices must be integers`.\\n        It is now rejected up front with an actionable message.\\n        \\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"cannot start with `_`\\\"):\\n            validate_prompt(\\\"Hello {_type}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/prototypes/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/prototypes/test_create_data_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6e20f3ed68b5833d9cd74ac9bce45efa8ac01275546d16b74bf6b76e7e147e68\",\"content\":\"import re\\n\\nimport pytest\\nfrom lfx.components.processing.create_data import CreateDataComponent\\nfrom lfx.schema import Data\\n\\n\\n@pytest.fixture\\ndef create_data_component():\\n    return CreateDataComponent()\\n\\n\\ndef test_update_build_config(create_data_component):\\n    build_config = {\\n        \\\"number_of_fields\\\": {\\n            \\\"type\\\": \\\"int\\\",\\n            \\\"value\\\": 2,\\n        },\\n        \\\"text_key\\\": {\\n            \\\"type\\\": \\\"str\\\",\\n            \\\"value\\\": \\\"\\\",\\n        },\\n        \\\"text_key_validator\\\": {\\n            \\\"type\\\": \\\"bool\\\",\\n            \\\"value\\\": False,\\n        },\\n    }\\n    updated_config = create_data_component.update_build_config(\\n        build_config=build_config, field_value=3, field_name=\\\"number_of_fields\\\"\\n    )\\n\\n    assert \\\"field_1_key\\\" in updated_config\\n    assert \\\"field_2_key\\\" in updated_config\\n    assert \\\"field_3_key\\\" in updated_config\\n    assert updated_config[\\\"number_of_fields\\\"][\\\"value\\\"] == 3\\n\\n\\ndef test_update_build_config_exceed_limit(create_data_component):\\n    build_config = {\\n        \\\"number_of_fields\\\": {\\n            \\\"type\\\": \\\"int\\\",\\n            \\\"value\\\": 2,\\n        },\\n        \\\"text_key\\\": {\\n            \\\"type\\\": \\\"str\\\",\\n            \\\"value\\\": \\\"\\\",\\n        },\\n        \\\"text_key_validator\\\": {\\n            \\\"type\\\": \\\"bool\\\",\\n            \\\"value\\\": False,\\n        },\\n    }\\n    with pytest.raises(ValueError, match=re.escape(\\\"Number of fields cannot exceed 15.\\\")):\\n        create_data_component.update_build_config(build_config, 16, \\\"number_of_fields\\\")\\n\\n\\nasync def test_build_data(create_data_component):\\n    create_data_component._attributes = {\\n        \\\"field_1_key\\\": {\\\"key1\\\": \\\"value1\\\"},\\n        \\\"field_2_key\\\": {\\\"key2\\\": \\\"value2\\\"},\\n    }\\n    create_data_component.text_key = \\\"key1\\\"\\n    create_data_component.text_key_validator = False\\n\\n    result = await create_data_component.build_data()\\n\\n    assert isinstance(result, Data)\\n    assert result.data == {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}\\n    assert result.text_key == \\\"key1\\\"\\n\\n\\ndef test_get_data(create_data_component):\\n    create_data_component._attributes = {\\n        \\\"field_1_key\\\": {\\\"key1\\\": \\\"value1\\\"},\\n        \\\"field_2_key\\\": {\\\"key2\\\": \\\"value2\\\"},\\n    }\\n\\n    result = create_data_component.get_data()\\n\\n    assert result == {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}\\n\\n\\ndef test_validate_text_key_valid(create_data_component):\\n    # Arrange\\n    create_data_component._attributes = {\\n        \\\"field_1_key\\\": {\\\"key1\\\": \\\"value1\\\"},\\n        \\\"field_2_key\\\": {\\\"key2\\\": \\\"value2\\\"},\\n    }\\n    create_data_component.text_key = \\\"key1\\\"\\n\\n    # Act & Assert\\n    try:\\n        create_data_component.validate_text_key()\\n    except ValueError:\\n        pytest.fail(\\\"validate_text_key() raised ValueError unexpectedly!\\\")\\n\\n    # Additional assertions\\n    assert create_data_component.text_key == \\\"key1\\\"\\n    assert \\\"key1\\\" in create_data_component.get_data()\\n\\n\\ndef test_validate_text_key_invalid(create_data_component):\\n    # Arrange\\n    create_data_component._attributes = {\\n        \\\"field_1_key\\\": {\\\"key1\\\": \\\"value1\\\"},\\n        \\\"field_2_key\\\": {\\\"key2\\\": \\\"value2\\\"},\\n    }\\n    create_data_component.text_key = \\\"invalid_key\\\"\\n\\n    # Act & Assert\\n    with pytest.raises(ValueError, match=\\\"Text Key: 'invalid_key' not found in the Data keys: 'key1, key2'\\\"):\\n        create_data_component.validate_text_key()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/prototypes/test_update_data_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0cd20b0f261d31ff873a7f216887fcbc0e2addfb35a3adb6cb9984e7a5eb19a\",\"content\":\"import re\\n\\nimport pytest\\nfrom lfx.components.processing.update_data import UpdateDataComponent\\nfrom lfx.schema import Data\\n\\n\\n@pytest.fixture\\ndef update_data_component():\\n    return UpdateDataComponent()\\n\\n\\ndef test_update_build_config(update_data_component):\\n    build_config = {\\n        \\\"number_of_fields\\\": {\\n            \\\"type\\\": \\\"int\\\",\\n            \\\"value\\\": 2,\\n        },\\n        \\\"text_key\\\": {\\n            \\\"type\\\": \\\"str\\\",\\n            \\\"value\\\": \\\"\\\",\\n        },\\n        \\\"text_key_validator\\\": {\\n            \\\"type\\\": \\\"bool\\\",\\n            \\\"value\\\": False,\\n        },\\n    }\\n    updated_config = update_data_component.update_build_config(\\n        build_config=build_config, field_value=3, field_name=\\\"number_of_fields\\\"\\n    )\\n\\n    assert \\\"field_1_key\\\" in updated_config\\n    assert \\\"field_2_key\\\" in updated_config\\n    assert \\\"field_3_key\\\" in updated_config\\n    assert updated_config[\\\"number_of_fields\\\"][\\\"value\\\"] == 3\\n\\n\\ndef test_update_build_config_exceed_limit(update_data_component):\\n    build_config = {\\n        \\\"number_of_fields\\\": {\\n            \\\"type\\\": \\\"int\\\",\\n            \\\"value\\\": 2,\\n        },\\n        \\\"text_key\\\": {\\n            \\\"type\\\": \\\"str\\\",\\n            \\\"value\\\": \\\"\\\",\\n        },\\n        \\\"text_key_validator\\\": {\\n            \\\"type\\\": \\\"bool\\\",\\n            \\\"value\\\": False,\\n        },\\n    }\\n    with pytest.raises(ValueError, match=re.escape(\\\"Number of fields cannot exceed 15.\\\")):\\n        update_data_component.update_build_config(build_config, 16, \\\"number_of_fields\\\")\\n\\n\\nasync def test_build_data(update_data_component):\\n    update_data_component._attributes = {\\n        \\\"field_1_key\\\": {\\\"key1\\\": \\\"new_value1\\\"},\\n        \\\"field_2_key\\\": {\\\"key3\\\": \\\"value3\\\"},\\n    }\\n    update_data_component.text_key = \\\"key1\\\"\\n    update_data_component.text_key_validator = False\\n    update_data_component.old_data = Data(data={\\\"key1\\\": \\\"old_value1\\\", \\\"key2\\\": \\\"value2\\\"}, text_key=\\\"key2\\\")\\n\\n    result = await update_data_component.build_data()\\n\\n    assert isinstance(result, Data)\\n    assert result.data == {\\\"key1\\\": \\\"new_value1\\\", \\\"key2\\\": \\\"value2\\\", \\\"key3\\\": \\\"value3\\\"}\\n    assert result.text_key == \\\"key1\\\"\\n\\n\\ndef test_get_data(update_data_component):\\n    update_data_component._attributes = {\\n        \\\"field_1_key\\\": {\\\"key1\\\": \\\"value1\\\"},\\n        \\\"field_2_key\\\": {\\\"key2\\\": \\\"value2\\\"},\\n    }\\n\\n    result = update_data_component.get_data()\\n\\n    assert result == {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}\\n\\n\\ndef test_validate_text_key_valid(update_data_component):\\n    data = Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}, text_key=\\\"key1\\\")\\n    update_data_component.text_key = \\\"key1\\\"\\n\\n    try:\\n        update_data_component.validate_text_key(data)\\n    except ValueError:\\n        pytest.fail(\\\"validate_text_key() raised ValueError unexpectedly!\\\")\\n\\n\\ndef test_validate_text_key_invalid(update_data_component):\\n    data = Data(data={\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}, text_key=\\\"key1\\\")\\n    update_data_component.text_key = \\\"invalid_key\\\"\\n    with pytest.raises(ValueError) as exc_info:  # noqa: PT011\\n        update_data_component.validate_text_key(data)\\n    expected_error_message = (\\n        f\\\"Text Key: '{update_data_component.text_key}' not found in the Data keys: {', '.join(data.data.keys())}\\\"\\n    )\\n    assert str(exc_info.value) == expected_error_message\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/search/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/search/test_wikidata_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c2720e3d24cce73d503558c640090045206492ae12ddc38f2132d696fed72b22\",\"content\":\"from unittest.mock import MagicMock, patch\\n\\nimport httpx\\nimport pytest\\nfrom langchain_core.tools import ToolException\\nfrom langflow.custom import Component\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.components.wikipedia import WikidataComponent\\nfrom lfx.custom.utils import build_custom_component_template\\n\\n# Import the base test class\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestWikidataComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Fixture to create a WikidataComponent instance.\\\"\\\"\\\"\\n        return WikidataComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    @pytest.fixture\\n    def mock_query(self):\\n        \\\"\\\"\\\"Fixture to provide a default query.\\\"\\\"\\\"\\n        return \\\"test query\\\"\\n\\n    def test_wikidata_initialization(self, component_class):\\n        component = component_class()\\n        assert component.display_name == \\\"Wikidata\\\"\\n        assert component.description == \\\"Performs a search using the Wikidata API.\\\"\\n        assert component.icon == \\\"Wikipedia\\\"\\n\\n    def test_wikidata_template(self, component_class):\\n        component = component_class()\\n        frontend_node, _ = build_custom_component_template(Component(_code=component._code))\\n\\n        # Verify basic structure\\n        assert isinstance(frontend_node, dict)\\n\\n        # Verify inputs\\n        assert \\\"template\\\" in frontend_node\\n        input_names = [input_[\\\"name\\\"] for input_ in frontend_node[\\\"template\\\"].values() if isinstance(input_, dict)]\\n        assert \\\"query\\\" in input_names\\n\\n    @patch(\\\"lfx.components.tools.wikidata_api.httpx.get\\\")\\n    def test_fetch_content_success(self, mock_httpx, component_class, mock_query):\\n        component = component_class()\\n        component.query = mock_query\\n\\n        # Mock successful API response\\n        mock_response = MagicMock()\\n        mock_response.json.return_value = {\\n            \\\"search\\\": [\\n                {\\n                    \\\"label\\\": \\\"Test Label\\\",\\n                    \\\"id\\\": \\\"Q123\\\",\\n                    \\\"url\\\": \\\"https://test.com\\\",\\n                    \\\"description\\\": \\\"Test Description\\\",\\n                    \\\"concepturi\\\": \\\"https://test.com/concept\\\",\\n                }\\n            ]\\n        }\\n        mock_httpx.return_value = mock_response\\n\\n        result = component.fetch_content()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert result[0].text == \\\"Test Label: Test Description\\\"\\n        assert result[0].data[\\\"label\\\"] == \\\"Test Label\\\"\\n        assert result[0].data[\\\"id\\\"] == \\\"Q123\\\"\\n\\n    @patch(\\\"lfx.components.tools.wikidata_api.httpx.get\\\")\\n    def test_fetch_content_empty_response(self, mock_httpx, component_class, mock_query):\\n        component = component_class()\\n        component.query = mock_query\\n\\n        # Mock empty API response\\n        mock_response = MagicMock()\\n        mock_response.json.return_value = {\\\"search\\\": []}\\n        mock_httpx.return_value = mock_response\\n\\n        result = component.fetch_content()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert \\\"error\\\" in result[0].data\\n        assert \\\"No search results found\\\" in result[0].data[\\\"error\\\"]\\n\\n    @patch(\\\"lfx.components.tools.wikidata_api.httpx.get\\\")\\n    def test_fetch_content_error_handling(self, mock_httpx, component_class, mock_query):\\n        component = component_class()\\n        component.query = mock_query\\n\\n        # Mock HTTP error\\n        mock_httpx.side_effect = httpx.HTTPError(\\\"API Error\\\")\\n\\n        with pytest.raises(ToolException):\\n            component.fetch_content()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/search/test_wikipedia_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6df611b063d91615b1cb5f0818aae16e2f0475933ca33e63c80fc9d3fd90207a\",\"content\":\"from unittest.mock import MagicMock\\n\\nimport pytest\\nfrom langflow.custom import Component\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.components.wikipedia import WikipediaComponent\\nfrom lfx.custom.utils import build_custom_component_template\\n\\n# Import the base test class\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestWikipediaComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Fixture to create a WikipediaComponent instance.\\\"\\\"\\\"\\n        return WikipediaComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"input_value\\\": \\\"test query\\\",\\n            \\\"lang\\\": \\\"en\\\",\\n            \\\"k\\\": 3,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_wikipedia_initialization(self, component_class):\\n        component = component_class()\\n        assert component.display_name == \\\"Wikipedia\\\"\\n        assert component.description == \\\"Call Wikipedia API.\\\"\\n        assert component.icon == \\\"Wikipedia\\\"\\n\\n    def test_wikipedia_template(self, component_class):\\n        component = component_class()\\n        frontend_node, _ = build_custom_component_template(Component(_code=component._code))\\n\\n        # Verify basic structure\\n        assert isinstance(frontend_node, dict)\\n\\n        # Verify inputs\\n        assert \\\"template\\\" in frontend_node\\n        input_names = [input_[\\\"name\\\"] for input_ in frontend_node[\\\"template\\\"].values() if isinstance(input_, dict)]\\n\\n        expected_inputs = [\\\"input_value\\\", \\\"lang\\\", \\\"k\\\", \\\"load_all_available_meta\\\", \\\"doc_content_chars_max\\\"]\\n\\n        for input_name in expected_inputs:\\n            assert input_name in input_names\\n\\n    @pytest.fixture\\n    def mock_wikipedia_wrapper(self, mocker):\\n        return mocker.patch(\\\"langchain_community.utilities.wikipedia.WikipediaAPIWrapper\\\")\\n\\n    def test_fetch_content(self, component_class, mock_wikipedia_wrapper):\\n        component = component_class()\\n        component.input_value = \\\"test query\\\"\\n        component.k = 3\\n        component.lang = \\\"en\\\"\\n\\n        # Mock the WikipediaAPIWrapper and its load method\\n        mock_instance = MagicMock()\\n        mock_wikipedia_wrapper.return_value = mock_instance\\n        mock_doc = MagicMock()\\n        mock_doc.page_content = \\\"Test content\\\"\\n        mock_doc.metadata = {\\\"source\\\": \\\"wikipedia\\\", \\\"title\\\": \\\"Test Page\\\"}\\n        mock_instance.load.return_value = [mock_doc]\\n\\n        # Mock the _build_wrapper method to return our mock instance\\n        component._build_wrapper = MagicMock(return_value=mock_instance)\\n\\n        result = component.fetch_content()\\n\\n        # Verify wrapper was built with correct params\\n        component._build_wrapper.assert_called_once()\\n        mock_instance.load.assert_called_once_with(\\\"test query\\\")\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert result[0].text == \\\"Test content\\\"\\n\\n    def test_wikipedia_error_handling(self, component_class):\\n        component = component_class()\\n        # Mock _build_wrapper to raise exception\\n        component._build_wrapper = MagicMock(side_effect=Exception(\\\"API Error\\\"))\\n\\n        with pytest.raises(Exception, match=\\\"API Error\\\"):\\n            component.fetch_content()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/search/test_yfinance_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8440cec6a0cf67c1cbc56de6c1242c5d092e47aa40d7fc3061dcc8f9833bde9d\",\"content\":\"from unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_core.tools import ToolException\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.components.yahoosearch.yahoo import YahooFinanceMethod, YfinanceComponent\\nfrom lfx.custom.utils import build_custom_component_template\\nfrom lfx.schema import Data\\n\\n\\nclass TestYfinanceComponent:\\n    @pytest.fixture\\n    def component_class(self):\\n        return YfinanceComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\\"symbol\\\": \\\"AAPL\\\", \\\"method\\\": YahooFinanceMethod.GET_INFO, \\\"num_news\\\": 5, \\\"_session_id\\\": \\\"test-session\\\"}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_initialization(self, component_class):\\n        component = component_class()\\n        assert component.display_name == \\\"Yahoo! Finance\\\"\\n        assert component.icon == \\\"trending-up\\\"\\n        assert \\\"yfinance\\\" in component.description\\n\\n    def test_template_structure(self, component_class):\\n        component = component_class()\\n        frontend_node, _ = build_custom_component_template(component)\\n\\n        assert \\\"template\\\" in frontend_node\\n        input_names = [input_[\\\"name\\\"] for input_ in frontend_node[\\\"template\\\"].values() if isinstance(input_, dict)]\\n\\n        expected_inputs = [\\\"symbol\\\", \\\"method\\\", \\\"num_news\\\"]\\n        for input_name in expected_inputs:\\n            assert input_name in input_names\\n\\n    @patch(\\\"lfx.components.yahoosearch.yahoo.yf.Ticker\\\")\\n    def test_fetch_info(self, mock_ticker, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n\\n        # Setup mock\\n        mock_instance = MagicMock()\\n        mock_ticker.return_value = mock_instance\\n        mock_instance.info = {\\\"companyName\\\": \\\"Apple Inc.\\\"}\\n\\n        result = component.fetch_content()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert \\\"Apple Inc.\\\" in result[0].text\\n\\n    @patch(\\\"lfx.components.yahoosearch.yahoo.yf.Ticker\\\")\\n    def test_fetch_news(self, mock_ticker, component_class):\\n        component = component_class(symbol=\\\"AAPL\\\", method=YahooFinanceMethod.GET_NEWS, num_news=2)\\n\\n        # Setup mock\\n        mock_instance = MagicMock()\\n        mock_ticker.return_value = mock_instance\\n        mock_instance.news = [\\n            {\\\"title\\\": \\\"News 1\\\", \\\"link\\\": \\\"http://example.com/1\\\"},\\n            {\\\"title\\\": \\\"News 2\\\", \\\"link\\\": \\\"http://example.com/2\\\"},\\n        ]\\n\\n        result = component.fetch_content()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 2\\n        assert all(isinstance(item, Data) for item in result)\\n        assert \\\"News 1\\\" in result[0].text\\n        assert \\\"http://example.com/1\\\" in result[0].text\\n\\n    def test_error_handling(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n\\n        with patch.object(component, \\\"_fetch_yfinance_data\\\") as mock_fetch:\\n            mock_fetch.side_effect = Exception(\\\"API Error\\\")\\n\\n            with pytest.raises(ToolException):\\n                component.fetch_content()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/test_all_modules_importable.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"278342c09bcc52010ed110b5c38a1c6b506eaa97a8ea7f7062dc4bdc3097ba9d\",\"content\":\"\\\"\\\"\\\"Test to ensure all component modules are importable after dynamic import refactor.\\n\\nThis test validates that every component module can be imported successfully\\nand that all components listed in __all__ can be accessed.\\n\\nThis test suite includes:\\n1. Dynamic import system tests (lazy loading, caching, error handling)\\n2. Direct module import tests (catches actual import errors, syntax errors, deprecated imports)\\n3. AST-based code quality checks (deprecated import patterns)\\n4. Async parallel testing for performance\\n\\nThe combination of dynamic and direct import testing ensures both the import\\nsystem functionality AND the actual module code quality are validated.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport importlib\\nimport pkgutil\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom langflow import components\\nfrom lfx.interface.components import _warm_circular_imports\\n\\n# Provider components ship in bundle distributions. Partner packages are\\n# expected in the base Langflow install, but the long-tail lfx-bundles\\n# metapackage is opt-in. While an optional bundle is absent its compatibility\\n# shim stays in ``components.__all__`` but cannot be imported, so these tests\\n# skip that category instead of failing.\\n_OPTIONAL_PARTNER_BUNDLE_CATEGORIES = (\\\"openai\\\", \\\"datastax\\\", \\\"oracle\\\", \\\"exa\\\")\\n\\n\\ndef _lfx_bundles_shim_categories() -> tuple[str, ...]:\\n    components_dir = Path(components.__file__).parent\\n    return tuple(\\n        sorted(\\n            init_file.parent.name\\n            for init_file in components_dir.glob(\\\"*/__init__.py\\\")\\n            if 'importlib.import_module(\\\"lfx_bundles.' in init_file.read_text(encoding=\\\"utf-8\\\")\\n        )\\n    )\\n\\n\\n_OPTIONAL_BUNDLE_CATEGORIES = (*_OPTIONAL_PARTNER_BUNDLE_CATEGORIES, *_lfx_bundles_shim_categories())\\n\\n\\ndef _unavailable_bundle_categories() -> set[str]:\\n    unavailable = set()\\n    for category_name in _OPTIONAL_BUNDLE_CATEGORIES:\\n        try:\\n            getattr(components, category_name)\\n        except Exception:\\n            unavailable.add(category_name)\\n    return unavailable\\n\\n\\nUNAVAILABLE_BUNDLE_CATEGORIES = _unavailable_bundle_categories()\\n\\n\\nclass TestAllModulesImportable:\\n    \\\"\\\"\\\"Test that all component modules are importable.\\\"\\\"\\\"\\n\\n    def test_all_component_categories_importable(self):\\n        \\\"\\\"\\\"Test that all component categories in __all__ can be imported.\\\"\\\"\\\"\\n        failed_imports = []\\n\\n        for category_name in components.__all__:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            try:\\n                category_module = getattr(components, category_name)\\n                assert category_module is not None, f\\\"Category {category_name} is None\\\"\\n\\n                # Verify it's actually a module\\n                assert hasattr(category_module, \\\"__name__\\\"), f\\\"Category {category_name} is not a module\\\"\\n\\n            except Exception as e:\\n                failed_imports.append(f\\\"{category_name}: {e!s}\\\")\\n\\n        if failed_imports:\\n            pytest.fail(f\\\"Failed to import categories: {failed_imports}\\\")\\n\\n    def test_all_components_in_categories_importable(self):\\n        \\\"\\\"\\\"Test that all components in each category's __all__ can be imported.\\\"\\\"\\\"\\n        failed_imports = []\\n        successful_imports = 0\\n\\n        print(f\\\"Testing component imports across {len(components.__all__)} categories\\\")  # noqa: T201\\n\\n        for category_name in components.__all__:\\n            if category_name in UNAVAILABLE_BUNDLE_CATEGORIES:\\n                continue\\n            try:\\n                category_module = getattr(components, category_name)\\n\\n                if hasattr(category_module, \\\"__all__\\\"):\\n                    category_components = len(category_module.__all__)\\n                    print(f\\\"Testing {category_components} components in {category_name}\\\")  # noqa: T201\\n\\n                    for component_name in category_module.__all__:\\n                        qualified = f\\\"{category_name}.{component_name}\\\"\\n                        try:\\n                            component = getattr(category_module, component_name)\\n                            assert component is not None, f\\\"Component {component_name} is None\\\"\\n                            assert callable(component), f\\\"Component {component_name} is not callable\\\"\\n                            successful_imports += 1\\n\\n                        except Exception as e:\\n                            if \\\"lfx-bundles\\\" in str(e):\\n                                print(f\\\"SKIPPED optional lfx-bundles component: {qualified}: {e!s}\\\")  # noqa: T201\\n                                continue\\n                            failed_imports.append(f\\\"{qualified}: {e!s}\\\")\\n                            print(f\\\"FAILED: {qualified}: {e!s}\\\")  # noqa: T201\\n                else:\\n                    # Category doesn't have __all__, skip\\n                    print(f\\\"Skipping {category_name} (no __all__ attribute)\\\")  # noqa: T201\\n                    continue\\n\\n            except E";
